func isS3VectorsRequest(r *http.Request) bool {
	if strings.Contains(strings.ToLower(r.Host), "s3vectors") {
		return true
	}
	_, ok := s3VectorsOperations[r.URL.Path]
	return ok
}

func (s *Server) handleRedshiftRouter(w http.ResponseWriter, r *http.Request) {
	if !s.requireSigV4ServiceRedshift(w, r, "redshift") {
		return
	}
	if err := r.ParseForm(); err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid form")
		return
	}
	action := strings.TrimSpace(r.Form.Get("Action"))
	if action == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "MissingAction", "Action is required")
		return
	}
	if !awsmodels.IsRedshiftOperation(action) {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidAction", "unknown operation")
		return
	}
	handler, ok := redshiftHandlers[action]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusNotImplemented, "NotImplemented", "operation not implemented")
		return
	}
	handler(s, w, r)
}

