func (s *Server) handleRedshiftNotImplemented(w http.ResponseWriter, r *http.Request) {
	respondRedshiftErrorXML(w, http.StatusNotImplemented, "NotImplemented", "operation not implemented")
}

func (s *Server) handleRedshiftCreateCluster(w http.ResponseWriter, r *http.Request) {
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	if clusterID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterIdentifier is required")
		return
	}
	nodeType := strings.TrimSpace(r.Form.Get("NodeType"))
	if nodeType == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "NodeType is required")
		return
	}
	clusterType := strings.TrimSpace(r.Form.Get("ClusterType"))
	if clusterType == "" {
		clusterType = "single-node"
	}
	if clusterType != "single-node" && clusterType != "multi-node" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterType is invalid")
		return
	}
	numberOfNodes := 1
	if r.Form.Get("NumberOfNodes") != "" {
		nodes, err := strconv.Atoi(r.Form.Get("NumberOfNodes"))
		if err != nil || nodes < 1 {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "NumberOfNodes is invalid")
			return
		}
		numberOfNodes = nodes
	}
	if clusterType == "multi-node" && numberOfNodes < 2 {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "NumberOfNodes must be at least 2 for multi-node clusters")
		return
	}
	if clusterType == "single-node" && numberOfNodes != 1 {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "NumberOfNodes must be 1 for single-node clusters")
		return
	}
	masterUser := strings.TrimSpace(r.Form.Get("MasterUsername"))
	if masterUser == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "MasterUsername is required")
		return
	}
	dbName := strings.TrimSpace(r.Form.Get("DBName"))
	if dbName == "" {
		dbName = "dev"
	}
	paramGroup := strings.TrimSpace(r.Form.Get("ClusterParameterGroupName"))
	subnetGroup := strings.TrimSpace(r.Form.Get("ClusterSubnetGroupName"))
	vpcGroups := redshiftFormList(r.Form, "VpcSecurityGroupIds.member.")
	if len(vpcGroups) == 0 {
		vpcGroups = redshiftFormList(r.Form, "VpcSecurityGroupIds.member")
	}

	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	if subnetGroup != "" {
		if _, ok := s.redshift.subnetGroups[subnetGroup]; !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterSubnetGroupNotFound", "cluster subnet group not found")
			return
		}
	}
	if paramGroup != "" {
		if _, ok := s.redshift.paramGroups[paramGroup]; !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterParameterGroupNotFound", "cluster parameter group not found")
			return
		}
	}
	if len(vpcGroups) > 0 {
		for _, group := range vpcGroups {
			if _, ok := s.redshift.securityGroups[group]; !ok {
				respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterSecurityGroupNotFound", "cluster security group not found")
				return
			}
		}
	}
	if _, exists := s.redshift.clusters[clusterID]; exists {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterAlreadyExists", "cluster already exists")
		return
	}
	cluster := &redshiftCluster{
		ID:                   clusterID,
		NodeType:             nodeType,
		ClusterType:          clusterType,
		NumberOfNode:         numberOfNodes,
		Status:               "available",
		CreatedAt:            time.Now().UTC(),
		MasterUser:           masterUser,
		DBName:               dbName,
		ParameterGroupName:   paramGroup,
		SubnetGroupName:      subnetGroup,
		VpcSecurityGroupIds:  vpcGroups,
		DBRevision:           "1.0",
		EncryptionKeyVersion: 1,
	}
	s.redshift.clusters[clusterID] = cluster
	respondRedshiftClusterResponse(w, http.StatusOK, "CreateCluster", cluster)
}

func (s *Server) handleRedshiftModifyCluster(w http.ResponseWriter, r *http.Request) {
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	if clusterID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterIdentifier is required")
		return
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	cluster, ok := s.redshift.clusters[clusterID]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
		return
	}
	subnetGroup := strings.TrimSpace(r.Form.Get("ClusterSubnetGroupName"))
	paramGroup := strings.TrimSpace(r.Form.Get("ClusterParameterGroupName"))
	vpcGroups := redshiftFormList(r.Form, "VpcSecurityGroupIds.member.")
	if len(vpcGroups) == 0 {
		vpcGroups = redshiftFormList(r.Form, "VpcSecurityGroupIds.member")
	}
	if paramGroup != "" {
		if _, ok := s.redshift.paramGroups[paramGroup]; !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterParameterGroupNotFound", "cluster parameter group not found")
			return
		}
		cluster.ParameterGroupName = paramGroup
	}
	if subnetGroup != "" {
		if _, ok := s.redshift.subnetGroups[subnetGroup]; !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterSubnetGroupNotFound", "cluster subnet group not found")
			return
		}
		cluster.SubnetGroupName = subnetGroup
	}
	if len(vpcGroups) > 0 {
		for _, group := range vpcGroups {
			if _, ok := s.redshift.securityGroups[group]; !ok {
				respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterSecurityGroupNotFound", "cluster security group not found")
				return
			}
		}
		cluster.VpcSecurityGroupIds = vpcGroups
	}

	if val := strings.TrimSpace(r.Form.Get("ClusterType")); val != "" {
		if val != "single-node" && val != "multi-node" {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterType is invalid")
			return
		}
		cluster.ClusterType = val
	}
	if val := strings.TrimSpace(r.Form.Get("NodeType")); val != "" {
		cluster.NodeType = val
	}
	if r.Form.Get("NumberOfNodes") != "" {
		nodes, err := strconv.Atoi(r.Form.Get("NumberOfNodes"))
		if err != nil || nodes < 1 {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "NumberOfNodes is invalid")
			return
		}
		cluster.NumberOfNode = nodes
	}
	if cluster.ClusterType == "multi-node" && cluster.NumberOfNode < 2 {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "NumberOfNodes must be at least 2 for multi-node clusters")
		return
	}
	if cluster.ClusterType == "single-node" && cluster.NumberOfNode != 1 {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "NumberOfNodes must be 1 for single-node clusters")
		return
	}
	respondRedshiftClusterResponse(w, http.StatusOK, "ModifyCluster", cluster)
}

func (s *Server) handleRedshiftDeleteCluster(w http.ResponseWriter, r *http.Request) {
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	if clusterID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterIdentifier is required")
		return
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	cluster, ok := s.redshift.clusters[clusterID]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
		return
	}
	delete(s.redshift.clusters, clusterID)
	respondRedshiftClusterResponse(w, http.StatusOK, "DeleteCluster", cluster)
}

func (s *Server) handleRedshiftDescribeClusters(w http.ResponseWriter, r *http.Request) {
	filterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	var clusters []*redshiftCluster
	if filterID != "" {
		cluster, ok := s.redshift.clusters[filterID]
		if !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
			return
		}
		clusters = append(clusters, cluster)
	} else {
		for _, cluster := range s.redshift.clusters {
			clusters = append(clusters, cluster)
		}
		sort.Slice(clusters, func(i, j int) bool {
			return clusters[i].ID < clusters[j].ID
		})
	}
	respondRedshiftClustersResponse(w, http.StatusOK, "DescribeClusters", clusters)
}

