func (s *Server) handleRedshiftDescribeClusterDbRevisions(w http.ResponseWriter, r *http.Request) {
	if _, _, err := redshiftParsePagination(r.Form); err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", err.Error())
		return
	}
	filter := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	type revision struct {
		ClusterIdentifier       string `xml:"ClusterIdentifier,omitempty"`
		CurrentDatabaseRevision string `xml:"CurrentDatabaseRevision,omitempty"`
	}
	revisions := []revision{}
	if filter != "" {
		if _, ok := s.redshift.clusters[filter]; !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
			return
		}
		revisions = append(revisions, revision{
			ClusterIdentifier:       filter,
			CurrentDatabaseRevision: "1.0",
		})
	} else {
		clusterIDs := make([]string, 0, len(s.redshift.clusters))
		for id := range s.redshift.clusters {
			clusterIDs = append(clusterIDs, id)
		}
		sort.Strings(clusterIDs)
		for _, id := range clusterIDs {
			revisions = append(revisions, revision{
				ClusterIdentifier:       id,
				CurrentDatabaseRevision: "1.0",
			})
		}
	}
	respondRedshiftXML(w, http.StatusOK, struct {
		XMLName xml.Name `xml:"DescribeClusterDbRevisionsResponse"`
		XMLNS   string   `xml:"xmlns,attr"`
		Result  struct {
			XMLName            xml.Name   `xml:"DescribeClusterDbRevisionsResult"`
			ClusterDbRevisions []revision `xml:"ClusterDbRevisions>ClusterDbRevision"`
		} `xml:"DescribeClusterDbRevisionsResult"`
		ResponseMetadata redshiftResponseMetadata `xml:"ResponseMetadata"`
	}{
		XMLNS: redshiftNamespace,
		Result: struct {
			XMLName            xml.Name   `xml:"DescribeClusterDbRevisionsResult"`
			ClusterDbRevisions []revision `xml:"ClusterDbRevisions>ClusterDbRevision"`
		}{
			XMLName:            xml.Name{Local: "DescribeClusterDbRevisionsResult"},
			ClusterDbRevisions: revisions,
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

