func (s *Server) handleRedshiftDescribeReservedNodeExchangeStatus(w http.ResponseWriter, r *http.Request) {
	if _, _, err := redshiftParsePagination(r.Form); err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", err.Error())
		return
	}
	s.redshiftMu.Lock()
	exchanges := make([]redshiftReservedNodeExchangeStatusXML, 0, len(s.redshift.reservedExchanges)+1)
	for _, item := range s.redshift.reservedExchanges {
		exchanges = append(exchanges, redshiftReservedNodeExchangeStatusXML{
			ReservedNodeExchangeRequestId: item.RequestID,
			Status:                        item.Status,
			ReservedNodeId:                item.ReservedNodeID,
			SourceReservedNodeOfferingId:  item.SourceOfferingID,
			TargetReservedNodeOfferingId:  item.TargetOfferingID,
		})
	}
	s.redshiftMu.Unlock()
	if len(exchanges) == 0 {
		exchanges = append(exchanges, redshiftReservedNodeExchangeStatusXML{
			ReservedNodeExchangeRequestId: "exchange-1",
			Status:                        "SUCCEEDED",
			ReservedNodeId:                "reserved-node-1",
			SourceReservedNodeOfferingId:  "offering-1",
			TargetReservedNodeOfferingId:  "exchange-offering-1",
		})
	}
	sort.Slice(exchanges, func(i, j int) bool {
		return exchanges[i].ReservedNodeExchangeRequestId < exchanges[j].ReservedNodeExchangeRequestId
	})
	respondRedshiftXML(w, http.StatusOK, struct {
		XMLName xml.Name `xml:"DescribeReservedNodeExchangeStatusResponse"`
		XMLNS   string   `xml:"xmlns,attr"`
		Result  struct {
			XMLName                      xml.Name                                `xml:"DescribeReservedNodeExchangeStatusResult"`
			ReservedNodeExchangeStatuses []redshiftReservedNodeExchangeStatusXML `xml:"ReservedNodeExchangeStatusDetails>ReservedNodeExchangeStatus"`
		} `xml:"DescribeReservedNodeExchangeStatusResult"`
		ResponseMetadata redshiftResponseMetadata `xml:"ResponseMetadata"`
	}{
		XMLNS: redshiftNamespace,
		Result: struct {
			XMLName                      xml.Name                                `xml:"DescribeReservedNodeExchangeStatusResult"`
			ReservedNodeExchangeStatuses []redshiftReservedNodeExchangeStatusXML `xml:"ReservedNodeExchangeStatusDetails>ReservedNodeExchangeStatus"`
		}{
			XMLName:                      xml.Name{Local: "DescribeReservedNodeExchangeStatusResult"},
			ReservedNodeExchangeStatuses: exchanges,
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

func (s *Server) handleRedshiftPurchaseReservedNodeOffering(w http.ResponseWriter, r *http.Request) {
	offeringID := strings.TrimSpace(r.Form.Get("ReservedNodeOfferingId"))
	if offeringID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ReservedNodeOfferingId is required")
		return
	}
	nodeCount := 1
	if raw := strings.TrimSpace(r.Form.Get("NodeCount")); raw != "" {
		parsed, err := strconv.Atoi(raw)
		if err != nil || parsed <= 0 {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "NodeCount is invalid")
			return
		}
		nodeCount = parsed
	}
	id := strings.TrimSpace(r.Form.Get("ReservedNodeId"))
	if id == "" {
		id = fmt.Sprintf("reserved-node-%d", time.Now().UTC().UnixNano())
	}
	node := &redshiftReservedNode{
		ID:                id,
		OfferingID:        offeringID,
		NodeType:          "ra3.xlplus",
		State:             "active",
		NodeCount:         nodeCount,
		StartTime:         time.Now().UTC(),
		DurationInSeconds: 31536000,
		FixedPrice:        1000,
		UsagePrice:        0,
		CurrencyCode:      "USD",
	}
	s.redshiftMu.Lock()
	s.redshift.reservedNodes[node.ID] = node
	s.redshiftMu.Unlock()
	respondRedshiftXML(w, http.StatusOK, struct {
		XMLName xml.Name `xml:"PurchaseReservedNodeOfferingResponse"`
		XMLNS   string   `xml:"xmlns,attr"`
		Result  struct {
			XMLName      xml.Name                `xml:"PurchaseReservedNodeOfferingResult"`
			ReservedNode redshiftReservedNodeXML `xml:"ReservedNode"`
		} `xml:"PurchaseReservedNodeOfferingResult"`
		ResponseMetadata redshiftResponseMetadata `xml:"ResponseMetadata"`
	}{
		XMLNS: redshiftNamespace,
		Result: struct {
			XMLName      xml.Name                `xml:"PurchaseReservedNodeOfferingResult"`
			ReservedNode redshiftReservedNodeXML `xml:"ReservedNode"`
		}{
			XMLName: xml.Name{Local: "PurchaseReservedNodeOfferingResult"},
			ReservedNode: redshiftReservedNodeXML{
				ReservedNodeId:         node.ID,
				ReservedNodeOfferingId: node.OfferingID,
				NodeType:               node.NodeType,
				State:                  node.State,
				StartTime:              node.StartTime.Format(time.RFC3339),
				Duration:               node.DurationInSeconds,
				FixedPrice:             node.FixedPrice,
				UsagePrice:             node.UsagePrice,
				CurrencyCode:           node.CurrencyCode,
				NodeCount:              node.NodeCount,
			},
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

func (s *Server) handleRedshiftAcceptReservedNodeExchange(w http.ResponseWriter, r *http.Request) {
	reservedNodeID := strings.TrimSpace(r.Form.Get("ReservedNodeId"))
	if reservedNodeID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ReservedNodeId is required")
		return
	}
	targetOfferingID := strings.TrimSpace(r.Form.Get("TargetReservedNodeOfferingId"))
	if targetOfferingID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "TargetReservedNodeOfferingId is required")
		return
	}
	requestID := fmt.Sprintf("exchange-%d", time.Now().UTC().UnixNano())
	s.redshiftMu.Lock()
	node, ok := s.redshift.reservedNodes[reservedNodeID]
	if !ok && reservedNodeID != "reserved-node-1" {
		s.redshiftMu.Unlock()
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ReservedNodeNotFound", "reserved node not found")
		return
	}
	sourceOfferingID := "offering-1"
	if node != nil {
		sourceOfferingID = node.OfferingID
		node.OfferingID = targetOfferingID
		node.State = "exchanging"
	}
	exchange := &redshiftReservedNodeExchange{
		RequestID:        requestID,
		ReservedNodeID:   reservedNodeID,
		SourceOfferingID: sourceOfferingID,
		TargetOfferingID: targetOfferingID,
		Status:           "SUCCEEDED",
		CreatedAt:        time.Now().UTC(),
	}
	s.redshift.reservedExchanges[requestID] = exchange
	s.redshiftMu.Unlock()
	respondRedshiftXML(w, http.StatusOK, struct {
		XMLName xml.Name `xml:"AcceptReservedNodeExchangeResponse"`
		XMLNS   string   `xml:"xmlns,attr"`
		Result  struct {
			XMLName        xml.Name                              `xml:"AcceptReservedNodeExchangeResult"`
			ExchangeStatus redshiftReservedNodeExchangeStatusXML `xml:"ExchangeStatus"`
		} `xml:"AcceptReservedNodeExchangeResult"`
		ResponseMetadata redshiftResponseMetadata `xml:"ResponseMetadata"`
	}{
		XMLNS: redshiftNamespace,
		Result: struct {
			XMLName        xml.Name                              `xml:"AcceptReservedNodeExchangeResult"`
			ExchangeStatus redshiftReservedNodeExchangeStatusXML `xml:"ExchangeStatus"`
		}{
			XMLName: xml.Name{Local: "AcceptReservedNodeExchangeResult"},
			ExchangeStatus: redshiftReservedNodeExchangeStatusXML{
				ReservedNodeExchangeRequestId: exchange.RequestID,
				Status:                        exchange.Status,
				ReservedNodeId:                exchange.ReservedNodeID,
				SourceReservedNodeOfferingId:  exchange.SourceOfferingID,
				TargetReservedNodeOfferingId:  exchange.TargetOfferingID,
			},
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

