func (s *Server) handleRedshiftEnableSnapshotCopy(w http.ResponseWriter, r *http.Request) {
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	if clusterID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterIdentifier is required")
		return
	}
	destinationRegion := strings.TrimSpace(r.Form.Get("DestinationRegion"))
	if destinationRegion == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "DestinationRegion is required")
		return
	}
	retention := 0
	if raw := strings.TrimSpace(r.Form.Get("RetentionPeriod")); raw != "" {
		val, err := strconv.Atoi(raw)
		if err != nil || val < -1 {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "RetentionPeriod is invalid")
			return
		}
		retention = val
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	cluster, ok := s.redshift.clusters[clusterID]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
		return
	}
	cluster.SnapshotCopyEnabled = true
	cluster.SnapshotCopyDestination = destinationRegion
	cluster.SnapshotCopyRetentionDays = retention
	respondRedshiftClusterResponse(w, http.StatusOK, "EnableSnapshotCopy", cluster)
}

