func (s *Server) handleRedshiftDescribeRedshiftIdcApplications(w http.ResponseWriter, r *http.Request) {
	if _, _, err := redshiftParsePagination(r.Form); err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", err.Error())
		return
	}
	filterARN := strings.TrimSpace(r.Form.Get("RedshiftIdcApplicationArn"))
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	items := make([]redshiftIdcApplicationXML, 0)
	if filterARN != "" {
		app, ok := s.redshift.idcApplications[filterARN]
		if !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "RedshiftIdcApplicationNotFound", "idc application not found")
			return
		}
		items = append(items, redshiftIdcApplicationXML{
			RedshiftIdcApplicationName: app.Name,
			RedshiftIdcApplicationArn:  app.ARN,
			IdcInstanceArn:             app.IdcInstanceArn,
			Status:                     app.Status,
		})
	} else {
		arns := make([]string, 0, len(s.redshift.idcApplications))
		for arn := range s.redshift.idcApplications {
			arns = append(arns, arn)
		}
		sort.Strings(arns)
		for _, arn := range arns {
			app := s.redshift.idcApplications[arn]
			items = append(items, redshiftIdcApplicationXML{
				RedshiftIdcApplicationName: app.Name,
				RedshiftIdcApplicationArn:  app.ARN,
				IdcInstanceArn:             app.IdcInstanceArn,
				Status:                     app.Status,
			})
		}
	}
	respondRedshiftXML(w, http.StatusOK, struct {
		XMLName xml.Name `xml:"DescribeRedshiftIdcApplicationsResponse"`
		XMLNS   string   `xml:"xmlns,attr"`
		Result  struct {
			XMLName                 xml.Name                    `xml:"DescribeRedshiftIdcApplicationsResult"`
			RedshiftIdcApplications []redshiftIdcApplicationXML `xml:"RedshiftIdcApplications>RedshiftIdcApplication"`
		} `xml:"DescribeRedshiftIdcApplicationsResult"`
		ResponseMetadata redshiftResponseMetadata `xml:"ResponseMetadata"`
	}{
		XMLNS: redshiftNamespace,
		Result: struct {
			XMLName                 xml.Name                    `xml:"DescribeRedshiftIdcApplicationsResult"`
			RedshiftIdcApplications []redshiftIdcApplicationXML `xml:"RedshiftIdcApplications>RedshiftIdcApplication"`
		}{
			XMLName:                 xml.Name{Local: "DescribeRedshiftIdcApplicationsResult"},
			RedshiftIdcApplications: items,
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

