func (s *Server) handleRedshiftGetIdentityCenterAuthToken(w http.ResponseWriter, r *http.Request) {
	arn := strings.TrimSpace(r.Form.Get("RedshiftIdcApplicationArn"))
	if arn == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "RedshiftIdcApplicationArn is required")
		return
	}
	s.redshiftMu.Lock()
	_, ok := s.redshift.idcApplications[arn]
	s.redshiftMu.Unlock()
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "RedshiftIdcApplicationNotFound", "idc application not found")
		return
	}
	expiration := time.Now().UTC().Add(15 * time.Minute)
	respondRedshiftXML(w, http.StatusOK, struct {
		XMLName xml.Name `xml:"GetIdentityCenterAuthTokenResponse"`
		XMLNS   string   `xml:"xmlns,attr"`
		Result  struct {
			XMLName     xml.Name `xml:"GetIdentityCenterAuthTokenResult"`
			AccessToken string   `xml:"AccessToken"`
			ExpiresAt   string   `xml:"ExpiresAt"`
		} `xml:"GetIdentityCenterAuthTokenResult"`
		ResponseMetadata redshiftResponseMetadata `xml:"ResponseMetadata"`
	}{
		XMLNS: redshiftNamespace,
		Result: struct {
			XMLName     xml.Name `xml:"GetIdentityCenterAuthTokenResult"`
			AccessToken string   `xml:"AccessToken"`
			ExpiresAt   string   `xml:"ExpiresAt"`
		}{
			XMLName:     xml.Name{Local: "GetIdentityCenterAuthTokenResult"},
			AccessToken: "idc-token-" + strconv.FormatInt(time.Now().UTC().UnixNano(), 10),
			ExpiresAt:   expiration.Format(time.RFC3339),
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

