func (s *Server) handleRedshiftModifyClusterIamRoles(w http.ResponseWriter, r *http.Request) {
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	if clusterID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterIdentifier is required")
		return
	}
	addRoles := redshiftFormList(r.Form, "AddIamRoles.member.")
	if len(addRoles) == 0 {
		addRoles = redshiftFormList(r.Form, "AddIamRoles.member")
	}
	removeRoles := redshiftFormList(r.Form, "RemoveIamRoles.member.")
	if len(removeRoles) == 0 {
		removeRoles = redshiftFormList(r.Form, "RemoveIamRoles.member")
	}
	for _, role := range append(append([]string{}, addRoles...), removeRoles...) {
		if !isValidRedshiftIamRoleArn(role) {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "IamRoleArn is invalid")
			return
		}
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	cluster, ok := s.redshift.clusters[clusterID]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
		return
	}
	roleSet := make(map[string]struct{}, len(cluster.IamRoles))
	for _, role := range cluster.IamRoles {
		roleSet[role] = struct{}{}
	}
	for _, role := range addRoles {
		roleSet[role] = struct{}{}
	}
	for _, role := range removeRoles {
		delete(roleSet, role)
	}
	cluster.IamRoles = cluster.IamRoles[:0]
	for role := range roleSet {
		cluster.IamRoles = append(cluster.IamRoles, role)
	}
	sort.Strings(cluster.IamRoles)
	respondRedshiftClusterResponse(w, http.StatusOK, "ModifyClusterIamRoles", cluster)
}

func (s *Server) handleRedshiftCreateClusterParameterGroup(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimSpace(r.Form.Get("ParameterGroupName"))
	if name == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ParameterGroupName is required")
		return
	}
	family := strings.TrimSpace(r.Form.Get("ParameterGroupFamily"))
	if family == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ParameterGroupFamily is required")
		return
	}
	description := strings.TrimSpace(r.Form.Get("Description"))
	if description == "" {
		description = "stackyard parameter group"
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	if _, exists := s.redshift.paramGroups[name]; exists {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterParameterGroupAlreadyExists", "cluster parameter group already exists")
		return
	}
	group := &redshiftParameterGroup{
		Name:        name,
		Family:      family,
		Description: description,
		Parameters:  make(map[string]string),
		CreatedAt:   time.Now().UTC(),
	}
	s.redshift.paramGroups[name] = group
	respondRedshiftParameterGroupResponse(w, http.StatusOK, "CreateClusterParameterGroup", group)
}

func (s *Server) handleRedshiftModifyClusterParameterGroup(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimSpace(r.Form.Get("ParameterGroupName"))
	if name == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ParameterGroupName is required")
		return
	}
	params := redshiftParseParameters(r.Form)
	if len(params) == 0 {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "Parameters is required")
		return
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	group, ok := s.redshift.paramGroups[name]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterParameterGroupNotFound", "cluster parameter group not found")
		return
	}
	for _, param := range params {
		if param.ParameterName == "" {
			continue
		}
		group.Parameters[param.ParameterName] = param.ParameterValue
	}
	respondRedshiftParameterGroupResponse(w, http.StatusOK, "ModifyClusterParameterGroup", group)
}

func (s *Server) handleRedshiftResetClusterParameterGroup(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimSpace(r.Form.Get("ParameterGroupName"))
	if name == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ParameterGroupName is required")
		return
	}
	params := redshiftParseParameters(r.Form)
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	group, ok := s.redshift.paramGroups[name]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterParameterGroupNotFound", "cluster parameter group not found")
		return
	}
	if len(params) == 0 {
		group.Parameters = make(map[string]string)
	} else {
		for _, param := range params {
			delete(group.Parameters, param.ParameterName)
		}
	}
	respondRedshiftParameterGroupResponse(w, http.StatusOK, "ResetClusterParameterGroup", group)
}

