func (s *Server) handleRedshiftDescribeClusterParameters(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimSpace(r.Form.Get("ParameterGroupName"))
	if name == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ParameterGroupName is required")
		return
	}
	maxRecords, marker, err := redshiftParsePagination(r.Form)
	if err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", err.Error())
		return
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	group, ok := s.redshift.paramGroups[name]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterParameterGroupNotFound", "cluster parameter group not found")
		return
	}
	keys := make([]string, 0, len(group.Parameters))
	for key := range group.Parameters {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	start := 0
	if marker != "" {
		for i, key := range keys {
			if key == marker {
				start = i + 1
				break
			}
		}
	}
	end := len(keys)
	if maxRecords > 0 && start+maxRecords < end {
		end = start + maxRecords
	}
	params := make([]redshiftParameterXML, 0, end-start)
	for _, key := range keys[start:end] {
		params = append(params, redshiftParameterXML{
			ParameterName:  key,
			ParameterValue: group.Parameters[key],
		})
	}
	respondRedshiftParametersResponse(w, http.StatusOK, "DescribeClusterParameters", params)
}

func (s *Server) handleRedshiftModifyClusterMaintenance(w http.ResponseWriter, r *http.Request) {
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	if clusterID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterIdentifier is required")
		return
	}
	window := strings.TrimSpace(r.Form.Get("PreferredMaintenanceWindow"))
	deferMaintenance := strings.TrimSpace(r.Form.Get("DeferMaintenance"))
	deferMaintenanceID := strings.TrimSpace(r.Form.Get("DeferMaintenanceIdentifier"))
	deferStart := strings.TrimSpace(r.Form.Get("DeferMaintenanceStartTime"))
	deferEnd := strings.TrimSpace(r.Form.Get("DeferMaintenanceEndTime"))
	deferDuration := strings.TrimSpace(r.Form.Get("DeferMaintenanceDuration"))
	hasDeferParams := deferMaintenance != "" || deferMaintenanceID != "" || deferStart != "" || deferEnd != "" || deferDuration != ""
	if window == "" && !hasDeferParams {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "PreferredMaintenanceWindow or DeferMaintenance parameters are required")
		return
	}
	if window != "" && !isValidRedshiftMaintenanceWindow(window) {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "PreferredMaintenanceWindow is invalid")
		return
	}
	if deferMaintenance != "" {
		if _, err := strconv.ParseBool(deferMaintenance); err != nil {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "DeferMaintenance is invalid")
			return
		}
	}
	if deferDuration != "" {
		duration, err := strconv.Atoi(deferDuration)
		if err != nil || duration < 1 || duration > 45 {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "DeferMaintenanceDuration is invalid")
			return
		}
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	cluster, ok := s.redshift.clusters[clusterID]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
		return
	}
	if window != "" {
		cluster.PreferredMaintenanceWindow = window
	}
	respondRedshiftClusterResponse(w, http.StatusOK, "ModifyClusterMaintenance", cluster)
}

