func (s *Server) handleRedshiftResizeCluster(w http.ResponseWriter, r *http.Request) {
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	if clusterID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterIdentifier is required")
		return
	}
	nodeType := strings.TrimSpace(r.Form.Get("NodeType"))
	nodeCountStr := strings.TrimSpace(r.Form.Get("NumberOfNodes"))
	if nodeType == "" && nodeCountStr == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "NodeType or NumberOfNodes is required")
		return
	}
	targetNodes := 0
	if nodeCountStr != "" {
		val, err := strconv.Atoi(nodeCountStr)
		if err != nil || val < 1 {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "NumberOfNodes is invalid")
			return
		}
		targetNodes = val
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	cluster, ok := s.redshift.clusters[clusterID]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
		return
	}
	if nodeType == "" {
		nodeType = cluster.NodeType
	}
	if targetNodes == 0 {
		targetNodes = cluster.NumberOfNode
	}
	status := &redshiftResizeStatus{
		ClusterID:       clusterID,
		Status:          "IN_PROGRESS",
		TargetNodeType:  nodeType,
		TargetNodeCount: targetNodes,
		CreatedAt:       time.Now().UTC(),
	}
	s.redshift.resizeStatus[clusterID] = status
	respondRedshiftResizeResponse(w, http.StatusOK, "ResizeCluster", status)
}

