func (s *Server) handleRedshiftRestoreTableFromClusterSnapshot(w http.ResponseWriter, r *http.Request) {
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	snapshotID := strings.TrimSpace(r.Form.Get("SnapshotIdentifier"))
	sourceDB := strings.TrimSpace(r.Form.Get("SourceDatabaseName"))
	sourceSchema := strings.TrimSpace(r.Form.Get("SourceSchemaName"))
	sourceTable := strings.TrimSpace(r.Form.Get("SourceTableName"))
	targetDB := strings.TrimSpace(r.Form.Get("TargetDatabaseName"))
	targetSchema := strings.TrimSpace(r.Form.Get("TargetSchemaName"))
	newTable := strings.TrimSpace(r.Form.Get("NewTableName"))
	if clusterID == "" || snapshotID == "" || sourceTable == "" || newTable == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterIdentifier, SnapshotIdentifier, SourceTableName, and NewTableName are required")
		return
	}
	if targetDB == "" {
		targetDB = sourceDB
	}
	if targetSchema == "" {
		targetSchema = sourceSchema
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	if _, ok := s.redshift.clusters[clusterID]; !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
		return
	}
	if _, ok := s.redshift.snapshots[snapshotID]; !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterSnapshotNotFound", "snapshot not found")
		return
	}
	requestID := fmt.Sprintf("restore-%d", time.Now().UTC().UnixNano())
	status := &redshiftTableRestoreStatus{
		RequestID:      requestID,
		ClusterID:      clusterID,
		SnapshotID:     snapshotID,
		SourceDatabase: sourceDB,
		SourceSchema:   sourceSchema,
		SourceTable:    sourceTable,
		TargetDatabase: targetDB,
		TargetSchema:   targetSchema,
		TargetTable:    newTable,
		Status:         "SUCCEEDED",
		Message:        "table restore completed",
		CreatedAt:      time.Now().UTC(),
	}
	s.redshift.tableRestores[requestID] = status
	respondRedshiftTableRestoreStatusResponse(w, http.StatusOK, "RestoreTableFromClusterSnapshot", status)
}

func (s *Server) handleRedshiftDescribeTableRestoreStatus(w http.ResponseWriter, r *http.Request) {
	if _, _, err := redshiftParsePagination(r.Form); err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", err.Error())
		return
	}
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	requestID := strings.TrimSpace(r.Form.Get("TableRestoreRequestId"))
	statusFilter := strings.TrimSpace(r.Form.Get("Status"))
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	if clusterID != "" {
		if _, ok := s.redshift.clusters[clusterID]; !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
			return
		}
	}
	items := make([]*redshiftTableRestoreStatus, 0, len(s.redshift.tableRestores))
	if requestID != "" {
		item, ok := s.redshift.tableRestores[requestID]
		if !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "TableRestoreNotFound", "table restore status not found")
			return
		}
		if (clusterID == "" || item.ClusterID == clusterID) && (statusFilter == "" || strings.EqualFold(item.Status, statusFilter)) {
			items = append(items, item)
		}
	} else {
		ids := make([]string, 0, len(s.redshift.tableRestores))
		for id := range s.redshift.tableRestores {
			ids = append(ids, id)
		}
		sort.Strings(ids)
		for _, id := range ids {
			item := s.redshift.tableRestores[id]
			if clusterID != "" && item.ClusterID != clusterID {
				continue
			}
			if statusFilter != "" && !strings.EqualFold(item.Status, statusFilter) {
				continue
			}
			items = append(items, item)
		}
	}
	respondRedshiftTableRestoreStatusesResponse(w, http.StatusOK, "DescribeTableRestoreStatus", items)
}

func (s *Server) handleRedshiftCreateScheduledAction(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimSpace(r.Form.Get("ScheduledActionName"))
	if name == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ScheduledActionName is required")
		return
	}
	target := redshiftScheduledTargetFromForm(r.Form)
	if target == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "TargetAction is required")
		return
	}
	if !isValidRedshiftScheduledTarget(target) {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "TargetAction is invalid")
		return
	}
	schedule := strings.TrimSpace(r.Form.Get("Schedule"))
	if schedule == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "Schedule is required")
		return
	}
	if !isValidRedshiftSchedule(schedule) {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "Schedule is invalid")
		return
	}
	state := strings.TrimSpace(r.Form.Get("State"))
	if state == "" {
		if enableRaw := strings.TrimSpace(r.Form.Get("Enable")); enableRaw != "" {
			enable := strings.EqualFold(enableRaw, "true")
			if enable {
				state = "ACTIVE"
			} else {
				state = "DISABLED"
			}
		}
	}
	if state == "" {
		state = "ACTIVE"
	}
	if state != "ACTIVE" && state != "DISABLED" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "State is invalid")
		return
	}
	description := strings.TrimSpace(r.Form.Get("Description"))
	if description == "" {
		description = strings.TrimSpace(r.Form.Get("ScheduledActionDescription"))
	}
	iamRole := strings.TrimSpace(r.Form.Get("IamRole"))
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	if _, ok := s.redshift.scheduled[name]; ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ScheduledActionAlreadyExists", "scheduled action already exists")
		return
	}
	action := &redshiftScheduledAction{
		Name:         name,
		TargetAction: target,
		Schedule:     schedule,
		State:        state,
		CreatedAt:    time.Now().UTC(),
		Description:  description,
		IamRole:      iamRole,
	}
	s.redshift.scheduled[name] = action
	respondRedshiftScheduledActionResponse(w, http.StatusOK, "CreateScheduledAction", action)
}

func (s *Server) handleRedshiftModifyScheduledAction(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimSpace(r.Form.Get("ScheduledActionName"))
	if name == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ScheduledActionName is required")
		return
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	action, ok := s.redshift.scheduled[name]
	if !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ScheduledActionNotFound", "scheduled action not found")
		return
	}
	if val := redshiftScheduledTargetFromForm(r.Form); val != "" {
		if !isValidRedshiftScheduledTarget(val) {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "TargetAction is invalid")
			return
		}
		action.TargetAction = val
	}
	if val := strings.TrimSpace(r.Form.Get("Schedule")); val != "" {
		if !isValidRedshiftSchedule(val) {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "Schedule is invalid")
			return
		}
		action.Schedule = val
	}
	if val := strings.TrimSpace(r.Form.Get("State")); val != "" {
		if val != "ACTIVE" && val != "DISABLED" {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "State is invalid")
			return
		}
		action.State = val
	} else if enableRaw := strings.TrimSpace(r.Form.Get("Enable")); enableRaw != "" {
		if strings.EqualFold(enableRaw, "true") {
			action.State = "ACTIVE"
		} else {
			action.State = "DISABLED"
		}
	}
	if val := strings.TrimSpace(r.Form.Get("Description")); val != "" {
		action.Description = val
	} else if val := strings.TrimSpace(r.Form.Get("ScheduledActionDescription")); val != "" {
		action.Description = val
	}
	if val := strings.TrimSpace(r.Form.Get("IamRole")); val != "" {
		action.IamRole = val
	}
	respondRedshiftScheduledActionResponse(w, http.StatusOK, "ModifyScheduledAction", action)
}

