func (s *Server) handleRedshiftRejectDataShare(w http.ResponseWriter, r *http.Request) {
	name := redshiftDataShareNameFromForm(r.Form)
	if name == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "DataShareName is required")
		return
	}
	consumer := redshiftConsumerIdentifierFromForm(r.Form)
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	share := s.redshift.dataShares[name]
	if share == nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "DataShareNotFound", "data share not found")
		return
	}
	if consumer == "" {
		if len(share.Consumers) == 0 {
			consumer = "consumer-1"
			share.Consumers[consumer] = &redshiftDataShareConsumer{Identifier: consumer, Status: "REJECTED"}
		} else {
			for _, entry := range share.Consumers {
				entry.Status = "REJECTED"
			}
		}
	} else {
		share.Consumers[consumer] = &redshiftDataShareConsumer{Identifier: consumer, Status: "REJECTED"}
	}
	respondRedshiftDataShareResponse(w, http.StatusOK, "RejectDataShare", share)
}

