func (s *Server) handleRedshiftAddPartner(w http.ResponseWriter, r *http.Request) {
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	partnerName := strings.TrimSpace(r.Form.Get("PartnerName"))
	if clusterID == "" || partnerName == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterIdentifier and PartnerName are required")
		return
	}
	accountID := strings.TrimSpace(r.Form.Get("AccountId"))
	if accountID == "" {
		accountID = "123456789012"
	}
	databaseName := strings.TrimSpace(r.Form.Get("DatabaseName"))
	if databaseName == "" {
		databaseName = "dev"
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	if _, ok := s.redshift.clusters[clusterID]; !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
		return
	}
	key := redshiftPartnerKey(accountID, clusterID, databaseName, partnerName)
	if _, ok := s.redshift.partners[key]; ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "PartnerAlreadyExists", "partner already exists")
		return
	}
	partner := &redshiftPartnerIntegration{
		AccountID:         accountID,
		ClusterIdentifier: clusterID,
		DatabaseName:      databaseName,
		PartnerName:       partnerName,
		Status:            "Active",
		CreatedAt:         time.Now().UTC(),
	}
	s.redshift.partners[key] = partner
	respondRedshiftPartnerResponse(w, http.StatusOK, "AddPartner", partner)
}

func (s *Server) handleRedshiftDescribePartners(w http.ResponseWriter, r *http.Request) {
	if _, _, err := redshiftParsePagination(r.Form); err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", err.Error())
		return
	}
	accountID := strings.TrimSpace(r.Form.Get("AccountId"))
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	databaseName := strings.TrimSpace(r.Form.Get("DatabaseName"))
	partnerName := strings.TrimSpace(r.Form.Get("PartnerName"))
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	items := make([]*redshiftPartnerIntegration, 0, len(s.redshift.partners))
	for _, item := range s.redshift.partners {
		if accountID != "" && item.AccountID != accountID {
			continue
		}
		if clusterID != "" && item.ClusterIdentifier != clusterID {
			continue
		}
		if databaseName != "" && item.DatabaseName != databaseName {
			continue
		}
		if partnerName != "" && item.PartnerName != partnerName {
			continue
		}
		items = append(items, item)
	}
	sort.Slice(items, func(i, j int) bool {
		if items[i].PartnerName == items[j].PartnerName {
			if items[i].ClusterIdentifier == items[j].ClusterIdentifier {
				return items[i].DatabaseName < items[j].DatabaseName
			}
			return items[i].ClusterIdentifier < items[j].ClusterIdentifier
		}
		return items[i].PartnerName < items[j].PartnerName
	})
	respondRedshiftPartnersResponse(w, http.StatusOK, "DescribePartners", items)
}

