func (s *Server) handleRedshiftDescribeInboundIntegrations(w http.ResponseWriter, r *http.Request) {
	filterName := strings.TrimSpace(r.Form.Get("IntegrationName"))
	filterArn := strings.TrimSpace(r.Form.Get("IntegrationArn"))
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	items := make([]*redshiftIntegration, 0, len(s.redshift.integrations))
	if filterName != "" {
		integration := s.redshift.integrations[filterName]
		if integration == nil {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "IntegrationNotFound", "integration not found")
			return
		}
		items = append(items, integration)
	} else if filterArn != "" {
		for _, integration := range s.redshift.integrations {
			if integration.Arn == filterArn {
				items = append(items, integration)
				break
			}
		}
		if len(items) == 0 {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "IntegrationNotFound", "integration not found")
			return
		}
	} else {
		for _, integration := range s.redshift.integrations {
			items = append(items, integration)
		}
	}
	respondRedshiftIntegrationsResponse(w, http.StatusOK, "DescribeInboundIntegrations", items)
}

func (s *Server) handleRedshiftGetClusterCredentials(w http.ResponseWriter, r *http.Request) {
	clusterID := strings.TrimSpace(r.Form.Get("ClusterIdentifier"))
	if clusterID == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ClusterIdentifier is required")
		return
	}
	dbUser := strings.TrimSpace(r.Form.Get("DbUser"))
	if dbUser == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "DbUser is required")
		return
	}
	duration := strings.TrimSpace(r.Form.Get("DurationSeconds"))
	if duration != "" {
		secs, err := strconv.Atoi(duration)
		if err != nil || secs < 900 || secs > 3600 {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "DurationSeconds must be between 900 and 3600")
			return
		}
	}
	dbName := strings.TrimSpace(r.Form.Get("DbName"))
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	if _, ok := s.redshift.clusters[clusterID]; !ok {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
		return
	}
	resp := redshiftClusterCredentialsResponse{
		XMLName: xml.Name{Local: "GetClusterCredentialsResponse"},
		XMLNS:   redshiftNamespace,
		Result: redshiftClusterCredentialsResult{
			XMLName:           xml.Name{Local: "GetClusterCredentialsResult"},
			DbUser:            dbUser,
			DbPassword:        "SecretPass123!",
			Expiration:        time.Now().UTC().Add(1 * time.Hour),
			ClusterIdentifier: clusterID,
			DbName:            dbName,
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	}
	respondRedshiftXML(w, http.StatusOK, resp)
}

