func (s *Server) handleRedshiftCreateTags(w http.ResponseWriter, r *http.Request) {
	resource := strings.TrimSpace(r.Form.Get("ResourceName"))
	if resource == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ResourceName is required")
		return
	}
	tags, err := redshiftParseTags(r.Form)
	if err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", err.Error())
		return
	}
	if len(tags) == 0 {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "Tags are required")
		return
	}

	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	existing := s.redshift.tags[resource]
	if existing == nil {
		existing = make(map[string]string)
		s.redshift.tags[resource] = existing
	}
	newCount := 0
	for _, tag := range tags {
		if _, ok := existing[tag.Key]; !ok {
			newCount++
		}
	}
	if len(existing)+newCount > 50 {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "Tag limit exceeded")
		return
	}
	for _, tag := range tags {
		existing[tag.Key] = tag.Value
	}
	respondRedshiftXML(w, http.StatusOK, redshiftSimpleResponse{
		XMLName:          xml.Name{Local: "CreateTagsResponse"},
		XMLNS:            redshiftNamespace,
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

func (s *Server) handleRedshiftDeleteTags(w http.ResponseWriter, r *http.Request) {
	resource := strings.TrimSpace(r.Form.Get("ResourceName"))
	if resource == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "ResourceName is required")
		return
	}
	tagKeys, err := redshiftParseTagKeys(r.Form)
	if err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", err.Error())
		return
	}
	if len(tagKeys) == 0 {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "TagKeys are required")
		return
	}
	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	if existing, ok := s.redshift.tags[resource]; ok {
		for _, key := range tagKeys {
			delete(existing, key)
		}
		if len(existing) == 0 {
			delete(s.redshift.tags, resource)
		}
	}
	respondRedshiftXML(w, http.StatusOK, redshiftSimpleResponse{
		XMLName:          xml.Name{Local: "DeleteTagsResponse"},
		XMLNS:            redshiftNamespace,
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

func (s *Server) handleRedshiftDescribeTags(w http.ResponseWriter, r *http.Request) {
	filterResource := strings.TrimSpace(r.Form.Get("ResourceName"))
	tagKeys, err := redshiftParseTagKeys(r.Form)
	if err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", err.Error())
		return
	}
	tagValues := redshiftParseTagValues(r.Form)
	maxRecords, marker, err := redshiftParsePagination(r.Form)
	if err != nil {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", err.Error())
		return
	}

	s.redshiftMu.Lock()
	defer s.redshiftMu.Unlock()
	resources := make([]string, 0)
	if filterResource != "" {
		if _, ok := s.redshift.tags[filterResource]; ok {
			resources = append(resources, filterResource)
		}
	} else {
		for resource := range s.redshift.tags {
			resources = append(resources, resource)
		}
		sort.Strings(resources)
	}

	tagged := make([]redshiftTaggedResourceXML, 0)
	for _, resource := range resources {
		tagMap := s.redshift.tags[resource]
		if tagMap == nil {
			continue
		}
		keys := make([]string, 0, len(tagMap))
		for key := range tagMap {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			value := tagMap[key]
			if len(tagKeys) > 0 && !containsString(tagKeys, key) {
				continue
			}
			if len(tagValues) > 0 && !containsString(tagValues, value) {
				continue
			}
			tagged = append(tagged, redshiftTaggedResourceXML{
				ResourceName: resource,
				ResourceType: redshiftResourceType(resource),
				Tag: redshiftTagXML{
					Key:   key,
					Value: value,
				},
			})
		}
	}

	start := 0
	if marker != "" {
		idx, err := strconv.Atoi(marker)
		if err != nil || idx < 0 || idx > len(tagged) {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "Marker is invalid")
			return
		}
		start = idx
	}
	end := len(tagged)
	nextMarker := ""
	if maxRecords > 0 && start+maxRecords < end {
		end = start + maxRecords
		nextMarker = strconv.Itoa(end)
	}
	resp := redshiftDescribeTagsResponse{
		XMLName: xml.Name{Local: "DescribeTagsResponse"},
		XMLNS:   redshiftNamespace,
		Result: redshiftDescribeTagsResult{
			XMLName:         xml.Name{Local: "DescribeTagsResult"},
			TaggedResources: tagged[start:end],
			Marker:          nextMarker,
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	}
	respondRedshiftXML(w, http.StatusOK, resp)
}

