func (s *Server) handleRedshiftCreateEventSubscription(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimSpace(r.Form.Get("SubscriptionName"))
	if name == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "SubscriptionName is required")
		return
	}
	snsTopic := strings.TrimSpace(r.Form.Get("SnsTopicArn"))
	if snsTopic == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "SnsTopicArn is required")
		return
	}
	sourceType := strings.TrimSpace(r.Form.Get("SourceType"))
	allowedSourceTypes := map[string]struct{}{
		"cluster":                 {},
		"cluster-snapshot":        {},
		"cluster-parameter-group": {},
		"cluster-security-group":  {},
		"scheduled-action":        {},
	}
	if sourceType != "" {
		if _, ok := allowedSourceTypes[sourceType]; !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "SourceType is invalid")
			return
		}
	}
	sourceIds := redshiftFormList(r.Form, "SourceIds.member.")
	if len(sourceIds) == 0 {
		sourceIds = redshiftFormList(r.Form, "SourceIds.member")
	}
	if sourceType != "" && len(sourceIds) == 0 {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "SourceIds is required")
		return
	}
	enabled := true
	if raw := strings.TrimSpace(r.Form.Get("Enabled")); raw != "" {
		val, err := strconv.ParseBool(raw)
		if err != nil {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "Enabled is invalid")
			return
		}
		enabled = val
	}
	severity := strings.TrimSpace(r.Form.Get("Severity"))
	if severity == "" {
		severity = "INFO"
	}
	s.redshiftMu.Lock()
	if _, ok := s.redshift.eventSubs[name]; ok {
		s.redshiftMu.Unlock()
		respondRedshiftErrorXML(w, http.StatusBadRequest, "EventSubscriptionAlreadyExists", "event subscription already exists")
		return
	}
	if sourceType == "cluster" {
		for _, id := range sourceIds {
			if _, ok := s.redshift.clusters[id]; !ok {
				s.redshiftMu.Unlock()
				respondRedshiftErrorXML(w, http.StatusBadRequest, "ClusterNotFound", "cluster not found")
				return
			}
		}
	}
	sub := &redshiftEventSubscription{
		Name:       name,
		SnsTopic:   snsTopic,
		SourceType: sourceType,
		SourceIds:  sourceIds,
		Severity:   severity,
		Enabled:    enabled,
		Status:     "active",
		CreatedAt:  time.Now().UTC(),
	}
	s.redshift.eventSubs[name] = sub
	s.redshiftMu.Unlock()
	respondRedshiftXML(w, http.StatusOK, redshiftEventSubscriptionResponse{
		XMLName: xml.Name{Local: "CreateEventSubscriptionResponse"},
		XMLNS:   redshiftNamespace,
		Result: redshiftEventSubscriptionResult{
			XMLName: xml.Name{Local: "CreateEventSubscriptionResult"},
			EventSubscription: redshiftEventSubscriptionXML{
				CustSubscriptionId:       sub.Name,
				SnsTopicArn:              sub.SnsTopic,
				SourceType:               sub.SourceType,
				SourceIdsList:            sub.SourceIds,
				Status:                   sub.Status,
				SubscriptionCreationTime: sub.CreatedAt.Format(time.RFC3339),
				Enabled:                  redshiftBoolString(sub.Enabled),
				Severity:                 sub.Severity,
			},
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

func (s *Server) handleRedshiftModifyEventSubscription(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimSpace(r.Form.Get("SubscriptionName"))
	if name == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "SubscriptionName is required")
		return
	}
	sourceType := strings.TrimSpace(r.Form.Get("SourceType"))
	allowedSourceTypes := map[string]struct{}{
		"cluster":                 {},
		"cluster-snapshot":        {},
		"cluster-parameter-group": {},
		"cluster-security-group":  {},
		"scheduled-action":        {},
	}
	if sourceType != "" {
		if _, ok := allowedSourceTypes[sourceType]; !ok {
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "SourceType is invalid")
			return
		}
	}
	sourceIds := redshiftFormList(r.Form, "SourceIds.member.")
	if len(sourceIds) == 0 {
		sourceIds = redshiftFormList(r.Form, "SourceIds.member")
	}
	enabled := ""
	if raw := strings.TrimSpace(r.Form.Get("Enabled")); raw != "" {
		enabled = raw
	}
	snsTopic := strings.TrimSpace(r.Form.Get("SnsTopicArn"))
	severity := strings.TrimSpace(r.Form.Get("Severity"))
	s.redshiftMu.Lock()
	sub, ok := s.redshift.eventSubs[name]
	if !ok {
		s.redshiftMu.Unlock()
		respondRedshiftErrorXML(w, http.StatusBadRequest, "EventSubscriptionNotFound", "event subscription not found")
		return
	}
	if sourceType != "" {
		sub.SourceType = sourceType
	}
	if len(sourceIds) > 0 {
		sub.SourceIds = sourceIds
	}
	if enabled != "" {
		val, err := strconv.ParseBool(enabled)
		if err != nil {
			s.redshiftMu.Unlock()
			respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "Enabled is invalid")
			return
		}
		sub.Enabled = val
	}
	if snsTopic != "" {
		sub.SnsTopic = snsTopic
	}
	if severity != "" {
		sub.Severity = severity
	}
	s.redshiftMu.Unlock()
	respondRedshiftXML(w, http.StatusOK, redshiftEventSubscriptionResponse{
		XMLName: xml.Name{Local: "ModifyEventSubscriptionResponse"},
		XMLNS:   redshiftNamespace,
		Result: redshiftEventSubscriptionResult{
			XMLName: xml.Name{Local: "ModifyEventSubscriptionResult"},
			EventSubscription: redshiftEventSubscriptionXML{
				CustSubscriptionId:       sub.Name,
				SnsTopicArn:              sub.SnsTopic,
				SourceType:               sub.SourceType,
				SourceIdsList:            sub.SourceIds,
				Status:                   sub.Status,
				SubscriptionCreationTime: sub.CreatedAt.Format(time.RFC3339),
				Enabled:                  redshiftBoolString(sub.Enabled),
				Severity:                 sub.Severity,
			},
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

func (s *Server) handleRedshiftDeleteEventSubscription(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimSpace(r.Form.Get("SubscriptionName"))
	if name == "" {
		respondRedshiftErrorXML(w, http.StatusBadRequest, "InvalidParameterValue", "SubscriptionName is required")
		return
	}
	s.redshiftMu.Lock()
	if _, ok := s.redshift.eventSubs[name]; !ok {
		s.redshiftMu.Unlock()
		respondRedshiftErrorXML(w, http.StatusBadRequest, "EventSubscriptionNotFound", "event subscription not found")
		return
	}
	delete(s.redshift.eventSubs, name)
	s.redshiftMu.Unlock()
	respondRedshiftXML(w, http.StatusOK, redshiftSimpleResponse{
		XMLName:          xml.Name{Local: "DeleteEventSubscriptionResponse"},
		XMLNS:            redshiftNamespace,
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

func (s *Server) handleRedshiftDescribeEventSubscriptions(w http.ResponseWriter, r *http.Request) {
	filter := strings.TrimSpace(r.Form.Get("SubscriptionName"))
	s.redshiftMu.Lock()
	subs := make([]redshiftEventSubscriptionXML, 0, len(s.redshift.eventSubs))
	if filter != "" {
		sub, ok := s.redshift.eventSubs[filter]
		if !ok {
			s.redshiftMu.Unlock()
			respondRedshiftErrorXML(w, http.StatusBadRequest, "EventSubscriptionNotFound", "event subscription not found")
			return
		}
		subs = append(subs, redshiftEventSubscriptionXML{
			CustSubscriptionId:       sub.Name,
			SnsTopicArn:              sub.SnsTopic,
			SourceType:               sub.SourceType,
			SourceIdsList:            sub.SourceIds,
			Status:                   sub.Status,
			SubscriptionCreationTime: sub.CreatedAt.Format(time.RFC3339),
			Enabled:                  redshiftBoolString(sub.Enabled),
			Severity:                 sub.Severity,
		})
	} else {
		for _, sub := range s.redshift.eventSubs {
			subs = append(subs, redshiftEventSubscriptionXML{
				CustSubscriptionId:       sub.Name,
				SnsTopicArn:              sub.SnsTopic,
				SourceType:               sub.SourceType,
				SourceIdsList:            sub.SourceIds,
				Status:                   sub.Status,
				SubscriptionCreationTime: sub.CreatedAt.Format(time.RFC3339),
				Enabled:                  redshiftBoolString(sub.Enabled),
				Severity:                 sub.Severity,
			})
		}
	}
	s.redshiftMu.Unlock()
	respondRedshiftXML(w, http.StatusOK, redshiftEventSubscriptionsResponse{
		XMLName: xml.Name{Local: "DescribeEventSubscriptionsResponse"},
		XMLNS:   redshiftNamespace,
		Result: redshiftEventSubscriptionsResult{
			XMLName:            xml.Name{Local: "DescribeEventSubscriptionsResult"},
			EventSubscriptions: subs,
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	})
}

func respondRedshiftClusterResponse(w http.ResponseWriter, status int, action string, cluster *redshiftCluster) {
	iamRoles := make([]redshiftIamRoleXML, 0, len(cluster.IamRoles))
	for _, role := range cluster.IamRoles {
		iamRoles = append(iamRoles, redshiftIamRoleXML{IamRoleArn: role})
	}
	vpcGroups := make([]redshiftVpcSecurityGroupXML, 0, len(cluster.VpcSecurityGroupIds))
	for _, group := range cluster.VpcSecurityGroupIds {
		vpcGroups = append(vpcGroups, redshiftVpcSecurityGroupXML{VpcSecurityGroupId: group})
	}
	paramGroups := []redshiftClusterParameterGroupStatusXML{}
	if cluster.ParameterGroupName != "" {
		paramGroups = append(paramGroups, redshiftClusterParameterGroupStatusXML{
			ParameterGroupName:   cluster.ParameterGroupName,
			ParameterApplyStatus: "in-sync",
		})
	}
	var snapshotCopyStatus *redshiftClusterSnapshotCopyStatusXML
	if cluster.SnapshotCopyEnabled || cluster.SnapshotCopyDestination != "" || cluster.SnapshotCopyRetentionDays != 0 {
		snapshotCopyStatus = &redshiftClusterSnapshotCopyStatusXML{
			DestinationRegion: cluster.SnapshotCopyDestination,
			RetentionPeriod:   cluster.SnapshotCopyRetentionDays,
		}
	}
	resp := redshiftClusterResponse{
		XMLName: xml.Name{Local: action + "Response"},
		XMLNS:   redshiftNamespace,
		Result: redshiftClusterResult{
			XMLName: xml.Name{Local: action + "Result"},
			Cluster: redshiftClusterXML{
				ClusterIdentifier:          cluster.ID,
				NodeType:                   cluster.NodeType,
				ClusterStatus:              cluster.Status,
				ClusterType:                cluster.ClusterType,
				NumberOfNodes:              cluster.NumberOfNode,
				MasterUsername:             cluster.MasterUser,
				DBName:                     cluster.DBName,
				ClusterCreateTime:          cluster.CreatedAt.Format(time.RFC3339),
				ClusterParameterGroups:     paramGroups,
				PreferredMaintenanceWindow: cluster.PreferredMaintenanceWindow,
				SubnetGroupName:            cluster.SubnetGroupName,
				VpcSecurityGroups:          vpcGroups,
				IamRoles:                   iamRoles,
				ClusterDbRevision:          cluster.DBRevision,
				ClusterSnapshotCopyStatus:  snapshotCopyStatus,
			},
		},
		ResponseMetadata: redshiftResponseMetadata{RequestID: "stackyard-request"},
	}
	respondRedshiftXML(w, status, resp)
}

