func (s *Server) handleS3OutpostsCreateEndpoint(w http.ResponseWriter, r *http.Request) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "invalid request body")
		return
	}
	var req s3OutpostsCreateEndpointRequest
	if err := decodeS3OutpostsJSON(body, &req); err != nil {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "invalid JSON")
		return
	}
	if req.OutpostID == "" {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "OutpostId is required")
		return
	}
	if !isValidOutpostID(req.OutpostID) {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "OutpostId is invalid")
		return
	}
	if req.SecurityGroupID == "" || req.SubnetID == "" {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "SecurityGroupId and SubnetId are required")
		return
	}
	if req.AccessType != "" && req.AccessType != "Private" && req.AccessType != "CustomerOwnedIp" {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "AccessType is invalid")
		return
	}
	if req.NetworkType != "" && req.NetworkType != "IPV4" {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "NetworkType is invalid")
		return
	}
	accessType := req.AccessType
	if accessType == "" {
		accessType = "Private"
	}
	networkType := req.NetworkType
	if networkType == "" {
		networkType = "IPV4"
	}
	if accessType == "CustomerOwnedIp" && req.CustomerOwnedIpv4Pool == "" {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "CustomerOwnedIpv4Pool is required")
		return
	}
	if accessType != "CustomerOwnedIp" && req.CustomerOwnedIpv4Pool != "" {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "CustomerOwnedIpv4Pool is not applicable for AccessType")
		return
	}
	if accessType == "CustomerOwnedIp" && networkType != "IPV4" {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "NetworkType must be IPV4 for CustomerOwnedIp")
		return
	}
	ep := s.s3outposts.CreateEndpoint(req.OutpostID, req.SubnetID, req.SecurityGroupID, accessType, networkType, req.CustomerOwnedIpv4Pool, req.ClientToken)
	respondS3OutpostsJSON(w, http.StatusOK, s3OutpostsCreateEndpointResponse{EndpointArn: ep.EndpointArn, EndpointId: ep.EndpointID})
}

func (s *Server) handleS3OutpostsDeleteEndpoint(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query()
	outpostID := strings.TrimSpace(query.Get("outpostId"))
	endpointID := strings.TrimSpace(query.Get("endpointId"))
	if outpostID == "" {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "OutpostId is required")
		return
	}
	if !isValidOutpostID(outpostID) {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "OutpostId is invalid")
		return
	}
	if endpointID == "" {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "EndpointId is required")
		return
	}
	if !isValidOutpostsEndpointID(endpointID) {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "EndpointId is invalid")
		return
	}
	if err := s.s3outposts.DeleteEndpoint(endpointID); err != nil {
		respondS3OutpostsErrorJSON(w, http.StatusNotFound, "NotFoundException", "Endpoint not found")
		return
	}
	respondS3OutpostsJSON(w, http.StatusOK, struct{}{})
}

func (s *Server) handleS3OutpostsListEndpoints(w http.ResponseWriter, r *http.Request) {
	outpostID := strings.TrimSpace(r.URL.Query().Get("outpostId"))
	if outpostID != "" && !isValidOutpostID(outpostID) {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "OutpostId is invalid")
		return
	}
	maxResults, nextToken, err := parseOutpostsListParams(r)
	if err != nil {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", err.Error())
		return
	}
	offset, err := parseOutpostsNextToken(nextToken)
	if err != nil {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "NextToken is invalid")
		return
	}
	endpoints := s.s3outposts.ListEndpoints()
	if outpostID != "" {
		filtered := make([]s3outposts.Endpoint, 0, len(endpoints))
		for _, ep := range endpoints {
			if ep.OutpostsID == outpostID {
				filtered = append(filtered, ep)
			}
		}
		endpoints = filtered
	}
	if offset > len(endpoints) {
		respondS3OutpostsErrorJSON(w, http.StatusBadRequest, "ValidationException", "NextToken is invalid")
		return
	}
	if maxResults == 0 {
		maxResults = len(endpoints)
	}
	end := offset + maxResults
	if end > len(endpoints) {
		end = len(endpoints)
	}
	page := endpoints[offset:end]
	resp := s3OutpostsListEndpointsResponse{
		Endpoints: make([]s3OutpostsEndpoint, 0, len(page)),
	}
	if end < len(endpoints) {
		resp.NextToken = fmt.Sprintf("token-%d", end)
	}
	for _, ep := range page {
		resp.Endpoints = append(resp.Endpoints, s3OutpostsEndpoint{
			AccessType:            ep.AccessType,
			CreationTime:          ep.CreationTime,
			CustomerOwnedIpv4Pool: ep.CustomerOwnedIpv4Pool,
			EndpointArn:           ep.EndpointArn,
			EndpointId:            ep.EndpointID,
			NetworkInterfaces: []s3OutpostsNetworkInterface{
				{NetworkInterfaceId: ep.NetworkInterfaceID},
			},
			NetworkType:     ep.NetworkType,
			OutpostsId:      ep.OutpostsID,
			SecurityGroupId: ep.SecurityGroupID,
			Status:          ep.Status,
			SubnetId:        ep.SubnetID,
			VpcId:           ep.VpcID,
			CidrBlock:       ep.CidrBlock,
		})
	}
	respondS3OutpostsJSON(w, http.StatusOK, resp)
}

