func (s *Server) handleS3TablesListNamespaces(w http.ResponseWriter, r *http.Request, tableBucketARN string) {
	query := r.URL.Query()
	maxResults, nextToken, err := parseS3TablesListParams(r, "maxNamespaces")
	if err != nil {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", err.Error())
		return
	}
	offset, err := parseS3TablesNextToken(nextToken)
	if err != nil {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "continuationToken is invalid")
		return
	}
	if _, ok := s.s3tables.GetTableBucket(tableBucketARN); !ok {
		respondS3TablesErrorJSON(w, http.StatusNotFound, "NotFoundException", "table bucket not found")
		return
	}
	prefix := strings.TrimSpace(query.Get("prefix"))
	items := s.s3tables.ListNamespaces(tableBucketARN, prefix)
	if offset > len(items) {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "continuationToken is invalid")
		return
	}
	if maxResults == 0 {
		maxResults = len(items)
	}
	end := offset + maxResults
	if end > len(items) {
		end = len(items)
	}
	page := items[offset:end]
	resp := s3TablesListNamespacesResponse{
		Namespaces: make([]s3TablesNamespace, 0, len(page)),
	}
	if end < len(items) {
		resp.ContinuationToken = fmt.Sprintf("token-%d", end)
	}
	for _, ns := range page {
		resp.Namespaces = append(resp.Namespaces, s3TablesNamespace{
			CreatedAt:      ns.CreatedAt,
			CreatedBy:      ns.CreatedBy,
			Namespace:      ns.Namespace,
			NamespaceId:    ns.NamespaceId,
			OwnerAccountId: ns.OwnerAccountId,
			TableBucketId:  ns.TableBucketId,
		})
	}
	respondS3TablesJSON(w, http.StatusOK, resp)
}

func (s *Server) handleS3TablesCreateTable(
	w http.ResponseWriter,
	r *http.Request,
	tableBucketARN string,
	namespaceOverride []string,
) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "invalid request body")
		return
	}
	var req s3TablesCreateTableRequest
	if err := decodeS3TablesJSON(body, &req); err != nil {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "invalid JSON")
		return
	}
	namespace := req.Namespace
	if len(namespaceOverride) > 0 {
		namespace = namespaceOverride
	}
	if len(namespace) == 0 || strings.TrimSpace(req.Name) == "" {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "namespace and name are required")
		return
	}
	if strings.TrimSpace(req.Format) == "" && r.Method == http.MethodPut {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "format is required")
		return
	}
	if _, ok := s.s3tables.GetTableBucket(tableBucketARN); !ok {
		respondS3TablesErrorJSON(w, http.StatusNotFound, "NotFoundException", "table bucket not found")
		return
	}
	if _, ok := s.s3tables.GetNamespace(tableBucketARN, namespace); !ok {
		respondS3TablesErrorJSON(w, http.StatusNotFound, "NotFoundException", "namespace not found")
		return
	}
	table, _ := s.s3tables.CreateTable(tableBucketARN, namespace, req.Name)
	respondS3TablesJSON(w, http.StatusOK, s3TablesCreateTableResponse{
		Name:             table.Name,
		Namespace:        table.Namespace,
		TableBucketARN:   table.TableBucketArn,
		TableId:          table.TableId,
		TableArn:         table.TableArn,
		MetadataLocation: table.MetadataLocation,
	})
}

