func (s *Server) handleS3TablesRenameTable(
	w http.ResponseWriter,
	r *http.Request,
	tableBucketARN string,
	namespaceOverride []string,
	nameOverride string,
) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "invalid request body")
		return
	}
	var req s3TablesRenameTableRequest
	if err := decodeS3TablesJSON(body, &req); err != nil {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "invalid JSON")
		return
	}
	namespace := req.Namespace
	if len(namespaceOverride) > 0 {
		namespace = namespaceOverride
	}
	name := strings.TrimSpace(req.Name)
	if strings.TrimSpace(nameOverride) != "" {
		name = strings.TrimSpace(nameOverride)
	}
	if len(namespace) == 0 || name == "" || strings.TrimSpace(req.NewName) == "" {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "namespace, name, and newName are required")
		return
	}
	if val := strings.TrimSpace(req.NewNamespaceName); val != "" {
		newNamespace, ok := parseS3TablesNamespaceValue(val)
		if !ok || strings.Join(newNamespace, ".") != strings.Join(namespace, ".") {
			respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "namespace mismatch")
			return
		}
	}
	table, ok := s.s3tables.RenameTable(tableBucketARN, namespace, name, req.NewName)
	if !ok {
		respondS3TablesErrorJSON(w, http.StatusNotFound, "NotFoundException", "table not found")
		return
	}
	respondS3TablesJSON(w, http.StatusOK, s3TablesRenameTableResponse{
		Name:             table.Name,
		Namespace:        table.Namespace,
		TableArn:         table.TableArn,
		TableId:          table.TableId,
		MetadataLocation: table.MetadataLocation,
	})
}

