func (s *Server) handleS3TablesTagResource(w http.ResponseWriter, r *http.Request, arn string) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "invalid request body")
		return
	}
	var req s3TablesTagResourceRequest
	if err := decodeS3TablesJSON(body, &req); err != nil {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "invalid JSON")
		return
	}
	if len(req.Tags) == 0 {
		respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "tags are required")
		return
	}
	tags := map[string]string{}
	for _, tag := range req.Tags {
		key := strings.TrimSpace(tag.Key)
		if key == "" {
			respondS3TablesErrorJSON(w, http.StatusBadRequest, "BadRequestException", "tag key is required")
			return
		}
		tags[key] = tag.Value
	}
	if ok := s.s3tables.TagResource(arn, tags); !ok {
		respondS3TablesErrorJSON(w, http.StatusNotFound, "NotFoundException", "resource not found")
		return
	}
	respondS3TablesJSON(w, http.StatusOK, struct{}{})
}

