func (s *Server) handleS3TablesListTagsForResource(w http.ResponseWriter, r *http.Request, arn string) {
	tags, ok := s.s3tables.ListTagsForResource(arn)
	if !ok {
		respondS3TablesErrorJSON(w, http.StatusNotFound, "NotFoundException", "resource not found")
		return
	}
	resp := s3TablesListTagsForResourceResponse{
		Tags: make([]s3TablesTag, 0, len(tags)),
	}
	for key, value := range tags {
		resp.Tags = append(resp.Tags, s3TablesTag{Key: key, Value: value})
	}
	sort.Slice(resp.Tags, func(i, j int) bool {
		return resp.Tags[i].Key < resp.Tags[j].Key
	})
	respondS3TablesJSON(w, http.StatusOK, resp)
}

