func (s *Server) handleS3TablesGetTableMaintenanceJobStatus(w http.ResponseWriter, r *http.Request, tableArn string) {
	status, ok := s.s3tables.GetTableMaintenanceStatus(tableArn)
	if !ok {
		respondS3TablesErrorJSON(w, http.StatusNotFound, "NotFoundException", "table not found")
		return
	}
	jobStatus := "Not_Yet_Run"
	switch strings.ToUpper(strings.TrimSpace(status)) {
	case "ACTIVE", "SUCCESS", "SUCCESSFUL":
		jobStatus = "Successful"
	case "FAILED":
		jobStatus = "Failed"
	case "DISABLED":
		jobStatus = "Disabled"
	}
	respondS3TablesJSON(w, http.StatusOK, map[string]any{
		"tableARN": tableArn,
		"status": map[string]any{
			"icebergCompaction": map[string]any{
				"status": jobStatus,
			},
		},
	})
}

