func (s *Server) handleS3ControlListAccessPoints(w http.ResponseWriter, r *http.Request, accountID string) {
	query := r.URL.Query()
	bucketFilter := strings.TrimSpace(query.Get("bucket"))
	maxResults := 1000
	if raw := strings.TrimSpace(query.Get("maxResults")); raw != "" {
		val, err := strconv.Atoi(raw)
		if err != nil || val < 0 {
			respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid maxResults")
			return
		}
		maxResults = val
	}
	nextToken := strings.TrimSpace(query.Get("nextToken"))

	accessPoints := s.s3control.ListAccessPoints(accountID)
	filtered := make([]*s3control.AccessPoint, 0, len(accessPoints))
	for _, ap := range accessPoints {
		if bucketFilter != "" && ap.Bucket != bucketFilter {
			continue
		}
		filtered = append(filtered, ap)
	}
	start := 0
	if nextToken != "" {
		found := false
		for i, ap := range filtered {
			if ap.Name == nextToken {
				start = i + 1
				found = true
				break
			}
		}
		if !found && len(filtered) > 0 {
			respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid nextToken")
			return
		}
	}
	end := start + maxResults
	if end > len(filtered) {
		end = len(filtered)
	}
	out := make([]s3ControlAccessPointInfo, 0, max(0, end-start))
	for _, ap := range filtered[start:end] {
		entry := s3ControlAccessPointInfo{
			AccessPointArn:  ap.AccessPointArn,
			Alias:           ap.Alias,
			Bucket:          ap.Bucket,
			BucketAccountID: ap.BucketAccount,
			DataSourceID:    ap.DataSourceID,
			DataSourceType:  ap.DataSourceType,
			Name:            ap.Name,
			NetworkOrigin:   ap.NetworkOrigin,
		}
		if ap.VpcID != "" {
			entry.VpcConfiguration = &s3ControlVpcConfiguration{VpcID: ap.VpcID}
		}
		out = append(out, entry)
	}
	resp := s3ControlAccessPointListResult{
		AccessPointList: out,
	}
	if maxResults > 0 && end < len(filtered) {
		resp.NextToken = filtered[end-1].Name
	}
	respondS3XML(w, http.StatusOK, resp)
}

func (s *Server) handleS3ControlPutAccessPointPolicy(w http.ResponseWriter, r *http.Request, accountID, name string) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read request body")
		return
	}
	allowed := map[string]map[string]bool{
		"PutAccessPointPolicyRequest": {
			"Policy": true,
		},
	}
	required := []string{
		"PutAccessPointPolicyRequest/Policy",
	}
	if err := validateS3ControlXML(body, "PutAccessPointPolicyRequest", s3ControlNamespace, allowed, required); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var req s3ControlPutAccessPointPolicyRequest
	if err := xml.NewDecoder(bytes.NewReader(body)).Decode(&req); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	policy := strings.TrimSpace(req.Policy)
	if policy == "" {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedPolicy", "missing policy")
		return
	}
	if err := json.Unmarshal([]byte(policy), &map[string]any{}); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedPolicy", "invalid policy")
		return
	}
	if err := s.s3control.SetAccessPointPolicy(accountID, name, policy); err != nil {
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchAccessPoint", "access point not found")
		return
	}
	w.WriteHeader(http.StatusOK)
}

