func (s *Server) handleS3ControlCreateMultiRegionAccessPoint(w http.ResponseWriter, r *http.Request, accountID string) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read request body")
		return
	}
	allowed := map[string]map[string]bool{
		"CreateMultiRegionAccessPointRequest": {
			"ClientToken": true,
			"Details":     true,
		},
		"CreateMultiRegionAccessPointRequest/Details": {
			"Name":              true,
			"PublicAccessBlock": true,
			"Regions":           true,
		},
		"CreateMultiRegionAccessPointRequest/Details/PublicAccessBlock": {
			"BlockPublicAcls":       true,
			"IgnorePublicAcls":      true,
			"BlockPublicPolicy":     true,
			"RestrictPublicBuckets": true,
		},
		"CreateMultiRegionAccessPointRequest/Details/Regions": {
			"Region": true,
		},
		"CreateMultiRegionAccessPointRequest/Details/Regions/Region": {
			"Bucket":          true,
			"BucketAccountId": true,
			"Region":          true,
		},
	}
	required := []string{
		"CreateMultiRegionAccessPointRequest/Details",
		"CreateMultiRegionAccessPointRequest/Details/Name",
		"CreateMultiRegionAccessPointRequest/Details/Regions",
		"CreateMultiRegionAccessPointRequest/Details/Regions/Region",
		"CreateMultiRegionAccessPointRequest/Details/Regions/Region/Bucket",
	}
	if err := validateS3ControlXML(body, "CreateMultiRegionAccessPointRequest", s3ControlNamespace, allowed, required); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if err := validateS3ControlElementOrder(body, "CreateMultiRegionAccessPointRequest", []string{
		"ClientToken",
		"Details",
	}); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if err := validateS3ControlNestedOrder(body, "CreateMultiRegionAccessPointRequest/Details", []string{
		"Name",
		"PublicAccessBlock",
		"Regions",
	}); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if err := validateS3ControlRepeatedNestedOrder(body, "CreateMultiRegionAccessPointRequest/Details/Regions/Region", []string{
		"Bucket",
		"BucketAccountId",
		"Region",
	}); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	hasPAB := strings.TrimSpace(extractXMLPathValue(body, "Details/PublicAccessBlock/BlockPublicAcls")) != "" ||
		strings.TrimSpace(extractXMLPathValue(body, "Details/PublicAccessBlock/IgnorePublicAcls")) != "" ||
		strings.TrimSpace(extractXMLPathValue(body, "Details/PublicAccessBlock/BlockPublicPolicy")) != "" ||
		strings.TrimSpace(extractXMLPathValue(body, "Details/PublicAccessBlock/RestrictPublicBuckets")) != ""
	if hasPAB {
		if err := validateS3ControlNestedOrder(body, "CreateMultiRegionAccessPointRequest/Details/PublicAccessBlock", []string{
			"BlockPublicAcls",
			"IgnorePublicAcls",
			"BlockPublicPolicy",
			"RestrictPublicBuckets",
		}); err != nil {
			respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
			return
		}
		for _, field := range []string{
			"Details/PublicAccessBlock/BlockPublicAcls",
			"Details/PublicAccessBlock/IgnorePublicAcls",
			"Details/PublicAccessBlock/BlockPublicPolicy",
			"Details/PublicAccessBlock/RestrictPublicBuckets",
		} {
			val := extractXMLPathValue(body, field)
			if strings.TrimSpace(val) == "" || !validateBoolText(val) {
				respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
				return
			}
		}
	}
	var req s3ControlCreateMultiRegionAccessPointRequest
	if err := xml.NewDecoder(bytes.NewReader(body)).Decode(&req); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	name := strings.TrimSpace(req.Details.Name)
	if !isValidAccessPointName(name) {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid name")
		return
	}
	if len(req.Details.Regions.Regions) == 0 {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing regions")
		return
	}
	regions := make([]s3control.MultiRegionAccessPointRegion, 0, len(req.Details.Regions.Regions))
	routes := make([]s3control.MultiRegionAccessPointRoute, 0, len(req.Details.Regions.Regions))
	for _, region := range req.Details.Regions.Regions {
		bucket := strings.TrimSpace(region.Bucket)
		if bucket == "" {
			respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing bucket")
			return
		}
		if region.BucketAccountId != "" && !isValidAccountID(region.BucketAccountId) {
			respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid bucket account id")
			return
		}
		if !s.s3.HasBucket(bucket) {
			respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchBucket", "bucket does not exist")
			return
		}
		reg := strings.TrimSpace(region.Region)
		if reg == "" {
			reg = "us-east-1"
		}
		regions = append(regions, s3control.MultiRegionAccessPointRegion{
			Bucket:        bucket,
			BucketAccount: coalesce(region.BucketAccountId, accountID),
			Region:        reg,
		})
		routes = append(routes, s3control.MultiRegionAccessPointRoute{
			Bucket:                bucket,
			Region:                reg,
			TrafficDialPercentage: 100,
		})
	}
	mrap := &s3control.MultiRegionAccessPoint{
		Name:      name,
		Alias:     mrapAlias(name),
		CreatedAt: time.Now().UTC(),
		Status:    "READY",
		Regions:   regions,
		Routes:    routes,
	}
	if req.Details.PublicAccessBlock != nil {
		mrap.PublicAccessBlock = &s3control.MultiRegionAccessPointPublicAccessBlock{
			BlockPublicAcls:       req.Details.PublicAccessBlock.BlockPublicAcls,
			BlockPublicPolicy:     req.Details.PublicAccessBlock.BlockPublicPolicy,
			IgnorePublicAcls:      req.Details.PublicAccessBlock.IgnorePublicAcls,
			RestrictPublicBuckets: req.Details.PublicAccessBlock.RestrictPublicBuckets,
		}
	}
	if err := s.s3control.CreateMultiRegionAccessPoint(accountID, mrap); err != nil {
		if errors.Is(err, s3control.ErrMultiRegionAccessPointExists) {
			respondS3ControlErrorXML(w, http.StatusConflict, "MultiRegionAccessPointAlreadyExists", "multi-region access point already exists")
			return
		}
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	token := mrapOperationToken(accountID)
	op := &s3control.MultiRegionAccessPointOperation{
		TokenARN:      token,
		CreationTime:  time.Now().UTC(),
		Operation:     "CreateMultiRegionAccessPoint",
		RequestStatus: "SUCCEEDED",
		RequestParams: s3control.MultiRegionAccessPointRequestParameters{
			CreateRequest: mrap,
		},
	}
	for _, region := range regions {
		op.RegionStatuses = append(op.RegionStatuses, s3control.MultiRegionAccessPointRegionStatus{
			Name:          region.Region,
			RequestStatus: "SUCCEEDED",
		})
	}
	s.s3control.CreateMultiRegionOperation(accountID, op)
	respondS3XML(w, http.StatusOK, s3ControlCreateMultiRegionAccessPointResult{
		RequestTokenARN: token,
	})
}

