func (s *Server) handleS3ControlPutMultiRegionAccessPointPolicy(w http.ResponseWriter, r *http.Request, accountID string) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read request body")
		return
	}
	allowed := map[string]map[string]bool{
		"PutMultiRegionAccessPointPolicyRequest": {
			"ClientToken": true,
			"Details":     true,
		},
		"PutMultiRegionAccessPointPolicyRequest/Details": {
			"Name":   true,
			"Policy": true,
		},
	}
	required := []string{
		"PutMultiRegionAccessPointPolicyRequest/Details/Name",
		"PutMultiRegionAccessPointPolicyRequest/Details/Policy",
	}
	if err := validateS3ControlXML(body, "PutMultiRegionAccessPointPolicyRequest", s3ControlNamespace, allowed, required); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if err := validateS3ControlElementOrder(body, "PutMultiRegionAccessPointPolicyRequest", []string{
		"ClientToken",
		"Details",
	}); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if err := validateS3ControlNestedOrder(body, "PutMultiRegionAccessPointPolicyRequest/Details", []string{
		"Name",
		"Policy",
	}); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var req s3ControlPutMultiRegionAccessPointPolicyRequest
	if err := xml.NewDecoder(bytes.NewReader(body)).Decode(&req); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	name := strings.TrimSpace(req.Details.Name)
	if name == "" {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing name")
		return
	}
	policy := strings.TrimSpace(req.Details.Policy)
	if policy == "" {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedPolicy", "missing policy")
		return
	}
	if err := json.Unmarshal([]byte(policy), &map[string]any{}); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedPolicy", "invalid policy")
		return
	}
	mrap, err := s.findMultiRegionAccessPoint(accountID, name)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchMultiRegionAccessPoint", "multi-region access point not found")
		return
	}
	if err := s.s3control.SetMultiRegionAccessPointPolicy(accountID, mrap.Name, policy); err != nil {
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchMultiRegionAccessPoint", "multi-region access point not found")
		return
	}
	token := mrapOperationToken(accountID)
	op := &s3control.MultiRegionAccessPointOperation{
		TokenARN:      token,
		CreationTime:  time.Now().UTC(),
		Operation:     "PutMultiRegionAccessPointPolicy",
		RequestStatus: "SUCCEEDED",
		RequestParams: s3control.MultiRegionAccessPointRequestParameters{
			PutPolicyName: mrap.Name,
			PutPolicyBody: policy,
		},
	}
	s.s3control.CreateMultiRegionOperation(accountID, op)
	respondS3XML(w, http.StatusOK, s3ControlPutMultiRegionAccessPointPolicyResult{
		RequestTokenARN: token,
	})
}

