func (s *Server) handleS3ControlSubmitMultiRegionAccessPointRoutes(w http.ResponseWriter, r *http.Request, accountID, value string) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read request body")
		return
	}
	allowed := map[string]map[string]bool{
		"SubmitMultiRegionAccessPointRoutesRequest": {
			"RouteUpdates": true,
		},
		"SubmitMultiRegionAccessPointRoutesRequest/RouteUpdates": {
			"Route": true,
		},
		"SubmitMultiRegionAccessPointRoutesRequest/RouteUpdates/Route": {
			"Bucket":                true,
			"Region":                true,
			"TrafficDialPercentage": true,
		},
	}
	required := []string{
		"SubmitMultiRegionAccessPointRoutesRequest/RouteUpdates/Route",
		"SubmitMultiRegionAccessPointRoutesRequest/RouteUpdates/Route/Bucket",
		"SubmitMultiRegionAccessPointRoutesRequest/RouteUpdates/Route/Region",
		"SubmitMultiRegionAccessPointRoutesRequest/RouteUpdates/Route/TrafficDialPercentage",
	}
	if err := validateS3ControlXML(body, "SubmitMultiRegionAccessPointRoutesRequest", s3ControlNamespace, allowed, required); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if err := validateS3ControlElementOrder(body, "SubmitMultiRegionAccessPointRoutesRequest", []string{
		"RouteUpdates",
	}); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if err := validateS3ControlRepeatedNestedOrder(body, "SubmitMultiRegionAccessPointRoutesRequest/RouteUpdates/Route", []string{
		"Bucket",
		"Region",
		"TrafficDialPercentage",
	}); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var req s3ControlSubmitMultiRegionAccessPointRoutesRequest
	if err := xml.NewDecoder(bytes.NewReader(body)).Decode(&req); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if len(req.RouteUpdates) == 0 {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing routes")
		return
	}
	mrap, err := s.findMultiRegionAccessPoint(accountID, value)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchMultiRegionAccessPoint", "multi-region access point not found")
		return
	}
	allowedRegions := map[string]string{}
	for _, region := range mrap.Regions {
		allowedRegions[region.Region] = region.Bucket
	}
	routes := make([]s3control.MultiRegionAccessPointRoute, 0, len(req.RouteUpdates))
	active := 0
	for _, route := range req.RouteUpdates {
		bucket := strings.TrimSpace(route.Bucket)
		region := strings.TrimSpace(route.Region)
		if bucket == "" || region == "" {
			respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid route")
			return
		}
		if allowedBucket, ok := allowedRegions[region]; !ok || allowedBucket != bucket {
			respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "route does not match access point region")
			return
		}
		if route.TrafficDialPercentage < 0 || route.TrafficDialPercentage > 100 {
			respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid traffic dial percentage")
			return
		}
		if route.TrafficDialPercentage > 0 {
			active++
		}
		routes = append(routes, s3control.MultiRegionAccessPointRoute{
			Bucket:                bucket,
			Region:                region,
			TrafficDialPercentage: route.TrafficDialPercentage,
		})
	}
	if active == 0 {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "at least one route must be active")
		return
	}
	if err := s.s3control.SetMultiRegionAccessPointRoutes(accountID, mrap.Name, routes); err != nil {
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchMultiRegionAccessPoint", "multi-region access point not found")
		return
	}
	w.WriteHeader(http.StatusOK)
}

func (s *Server) handleS3ControlDescribeMultiRegionAccessPointOperation(w http.ResponseWriter, r *http.Request, accountID, token string) {
	op, err := s.s3control.GetMultiRegionOperation(accountID, token)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchMultiRegionAccessPointOperation", "operation not found")
		return
	}
	result := s3ControlDescribeMultiRegionAccessPointOperationResult{
		AsyncOperation: s3ControlAsyncOperation{
			CreationTime:    op.CreationTime.Format(time.RFC3339),
			Operation:       op.Operation,
			RequestStatus:   op.RequestStatus,
			RequestTokenARN: op.TokenARN,
		},
	}
	params := &s3ControlAsyncRequestParameters{}
	switch op.Operation {
	case "CreateMultiRegionAccessPoint":
		if op.RequestParams.CreateRequest != nil {
			params.CreateMultiRegionAccessPointRequest = &s3ControlCreateMultiRegionAccessPointRequest{
				Xmlns: s3ControlNamespace,
				Details: s3ControlMultiRegionAccessPointInput{
					Name: op.RequestParams.CreateRequest.Name,
					Regions: s3ControlMultiRegionAccessPointRegions{
						Regions: s.mrapRegionsXML(op.RequestParams.CreateRequest.Regions),
					},
				},
			}
		}
	case "PutMultiRegionAccessPointPolicy":
		params.PutMultiRegionAccessPointPolicyRequest = &s3ControlPutMultiRegionAccessPointPolicyRequest{
			Xmlns: s3ControlNamespace,
			Details: s3ControlPutMultiRegionAccessPointPolicyInput{
				Name:   op.RequestParams.PutPolicyName,
				Policy: op.RequestParams.PutPolicyBody,
			},
		}
	}
	if params.CreateMultiRegionAccessPointRequest != nil || params.PutMultiRegionAccessPointPolicyRequest != nil {
		result.AsyncOperation.RequestParameters = params
	}
	if op.RequestParams.CreateRequest != nil {
		report := s.mrapReport(op.RequestParams.CreateRequest)
		result.AsyncOperation.ResponseDetails = &s3ControlAsyncResponseDetails{
			MultiRegionAccessPointDetails: &report,
		}
	}
	respondS3XML(w, http.StatusOK, result)
}

func (s *Server) handleS3ControlDeleteMultiRegionAccessPoint(w http.ResponseWriter, r *http.Request, accountID string) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read request body")
		return
	}
	var req struct {
		Details struct {
			Name string `xml:"Name"`
		} `xml:"Details"`
	}
	if err := xml.NewDecoder(bytes.NewReader(body)).Decode(&req); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	name := strings.TrimSpace(req.Details.Name)
	if name == "" {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing name")
		return
	}
	if err := s.s3control.DeleteMultiRegionAccessPoint(accountID, name); err != nil {
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchMultiRegionAccessPoint", "multi-region access point not found")
		return
	}
	token := mrapOperationToken(accountID)
	op := &s3control.MultiRegionAccessPointOperation{
		TokenARN:      token,
		CreationTime:  time.Now().UTC(),
		Operation:     "DeleteMultiRegionAccessPoint",
		RequestStatus: "SUCCEEDED",
		RequestParams: s3control.MultiRegionAccessPointRequestParameters{DeleteName: name},
	}
	s.s3control.CreateMultiRegionOperation(accountID, op)
	respondS3XML(w, http.StatusOK, s3ControlDeleteMultiRegionAccessPointResult{RequestTokenARN: token})
}

