func (s *Server) handleS3ControlCreateAccessGrantsInstance(w http.ResponseWriter, r *http.Request, accountID string) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read request body")
		return
	}
	bodyStr := string(body)
	allowed := map[string]map[string]bool{
		"CreateAccessGrantsInstanceRequest": {
			"IdentityCenterArn": true,
			"Tags":              true,
		},
		"CreateAccessGrantsInstanceRequest/Tags": {
			"Tag":    true,
			"member": true,
		},
		"CreateAccessGrantsInstanceRequest/Tags/Tag": {
			"Key":   true,
			"Value": true,
		},
		"CreateAccessGrantsInstanceRequest/Tags/member": {
			"Key":   true,
			"Value": true,
		},
	}
	if err := validateS3ControlXML(body, "CreateAccessGrantsInstanceRequest", s3ControlNamespace, allowed, nil); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	order := make([]string, 0, 2)
	if strings.Contains(bodyStr, "<IdentityCenterArn") {
		order = append(order, "IdentityCenterArn")
	}
	if strings.Contains(bodyStr, "<Tags") {
		order = append(order, "Tags")
	}
	if err := validateS3ControlElementOrder(body, "CreateAccessGrantsInstanceRequest", order); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var req s3ControlCreateAccessGrantsInstanceRequest
	if err := xml.NewDecoder(bytes.NewReader(body)).Decode(&req); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	instanceID := "default"
	instance := &s3control.AccessGrantsInstance{
		ID:                           instanceID,
		Arn:                          accessGrantsInstanceArn(accountID, instanceID),
		IdentityCenterArn:            strings.TrimSpace(req.IdentityCenterArn),
		IdentityCenterInstanceArn:    strings.TrimSpace(req.IdentityCenterArn),
		IdentityCenterApplicationArn: "",
		CreatedAt:                    time.Now().UTC(),
	}
	if err := s.s3control.CreateAccessGrantsInstance(accountID, instance); err != nil {
		if errors.Is(err, s3control.ErrAccessGrantsInstanceAlreadyExists) {
			respondS3ControlErrorXML(w, http.StatusConflict, "AccessGrantsInstanceAlreadyExists", "access grants instance already exists")
			return
		}
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to create access grants instance")
		return
	}
	respondS3XML(w, http.StatusOK, s3ControlAccessGrantsInstanceResult{
		XMLName:                      xml.Name{Local: "CreateAccessGrantsInstanceResult"},
		AccessGrantsInstanceArn:      instance.Arn,
		AccessGrantsInstanceId:       instance.ID,
		IdentityCenterArn:            instance.IdentityCenterArn,
		IdentityCenterInstanceArn:    instance.IdentityCenterInstanceArn,
		IdentityCenterApplicationArn: instance.IdentityCenterApplicationArn,
		CreatedAt:                    instance.CreatedAt.Format(time.RFC3339),
	})
}

