func (s *Server) handleS3ControlCreateAccessGrant(w http.ResponseWriter, r *http.Request, accountID string) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read request body")
		return
	}
	bodyStr := string(body)
	allowed := map[string]map[string]bool{
		"CreateAccessGrantRequest": {
			"AccessGrantsLocationId":            true,
			"AccessGrantsLocationConfiguration": true,
			"Grantee":                           true,
			"Permission":                        true,
			"ApplicationArn":                    true,
			"S3PrefixType":                      true,
			"Tags":                              true,
		},
		"CreateAccessGrantRequest/AccessGrantsLocationConfiguration": {
			"S3SubPrefix": true,
		},
		"CreateAccessGrantRequest/Grantee": {
			"GranteeType":       true,
			"GranteeIdentifier": true,
		},
		"CreateAccessGrantRequest/Tags": {
			"Tag":    true,
			"member": true,
		},
		"CreateAccessGrantRequest/Tags/Tag": {
			"Key":   true,
			"Value": true,
		},
		"CreateAccessGrantRequest/Tags/member": {
			"Key":   true,
			"Value": true,
		},
	}
	required := []string{
		"CreateAccessGrantRequest/AccessGrantsLocationId",
		"CreateAccessGrantRequest/Grantee",
		"CreateAccessGrantRequest/Permission",
	}
	if err := validateS3ControlXML(body, "CreateAccessGrantRequest", s3ControlNamespace, allowed, required); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if err := validateS3ControlNestedOrder(body, "CreateAccessGrantRequest/Grantee", []string{"GranteeType", "GranteeIdentifier"}); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if strings.Contains(bodyStr, "<AccessGrantsLocationConfiguration") {
		if err := validateS3ControlNestedOrder(body, "CreateAccessGrantRequest/AccessGrantsLocationConfiguration", []string{"S3SubPrefix"}); err != nil {
			respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
			return
		}
	}
	var req s3ControlCreateAccessGrantRequest
	if err := xml.NewDecoder(bytes.NewReader(body)).Decode(&req); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	locationID := strings.TrimSpace(req.AccessGrantsLocationId)
	location, err := s.s3control.GetAccessGrantsLocation(accountID, locationID)
	if err != nil {
		if errors.Is(err, s3control.ErrAccessGrantsLocationNotFound) {
			respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchAccessGrantsLocation", "access grants location not found")
			return
		}
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchAccessGrantsInstance", "access grants instance not found")
		return
	}
	grantID := "ag-000001"
	grant := &s3control.AccessGrant{
		ID:                        grantID,
		Arn:                       accessGrantArn(accountID, grantID),
		AccessGrantsLocationID:    location.ID,
		AccessGrantsLocationScope: location.LocationScope,
		Permission:                strings.TrimSpace(req.Permission),
		ApplicationArn:            strings.TrimSpace(req.ApplicationArn),
		S3PrefixType:              strings.TrimSpace(req.S3PrefixType),
		S3SubPrefix:               "",
		Grantee: s3control.AccessGrantGrantee{
			Type:       strings.TrimSpace(req.Grantee.GranteeType),
			Identifier: strings.TrimSpace(req.Grantee.GranteeIdentifier),
		},
		Tags:      parseS3ControlTagsFromXML(body),
		CreatedAt: time.Now().UTC(),
	}
	if req.AccessGrantsLocationConfiguration != nil {
		grant.S3SubPrefix = strings.TrimSpace(req.AccessGrantsLocationConfiguration.S3SubPrefix)
	}
	if err := s.s3control.CreateAccessGrant(accountID, grant); err != nil {
		if errors.Is(err, s3control.ErrAccessGrantsLocationNotFound) {
			respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchAccessGrantsLocation", "access grants location not found")
			return
		}
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchAccessGrantsInstance", "access grants instance not found")
		return
	}
	respondS3XML(w, http.StatusOK, s3ControlAccessGrantResult{
		XMLName:                   xml.Name{Local: "CreateAccessGrantResult"},
		AccessGrantId:             grant.ID,
		AccessGrantArn:            grant.Arn,
		AccessGrantsLocationId:    grant.AccessGrantsLocationID,
		AccessGrantsLocationScope: grant.AccessGrantsLocationScope,
		Permission:                grant.Permission,
		Grantee: s3ControlAccessGrantGrantee{
			GranteeType:       grant.Grantee.Type,
			GranteeIdentifier: grant.Grantee.Identifier,
		},
		ApplicationArn: grant.ApplicationArn,
		S3PrefixType:   grant.S3PrefixType,
		CreatedAt:      grant.CreatedAt.Format(time.RFC3339),
	})
}

