func (s *Server) handleS3ControlCreateOutpostsBucket(w http.ResponseWriter, r *http.Request, accountID, outpostID string) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read request body")
		return
	}
	allowed := map[string]map[string]bool{
		"CreateBucketRequest": {
			"Bucket":  true,
			"Tagging": true,
		},
		"CreateBucketRequest/Tagging": {
			"Tag": true,
		},
		"CreateBucketRequest/Tagging/Tag": {
			"Key":   true,
			"Value": true,
		},
	}
	required := []string{"CreateBucketRequest/Bucket"}
	if err := validateS3ControlXML(body, "CreateBucketRequest", s3ControlNamespace, allowed, required); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	bodyStr := string(body)
	order := []string{"Bucket"}
	if strings.Contains(bodyStr, "<Tagging") {
		order = append(order, "Tagging")
	}
	if err := validateS3ControlElementOrder(body, "CreateBucketRequest", order); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var req s3ControlCreateOutpostsBucketRequest
	if err := xml.NewDecoder(bytes.NewReader(body)).Decode(&req); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	name := strings.TrimSpace(req.Bucket)
	if name == "" {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing bucket")
		return
	}
	bucket := &s3control.OutpostsBucket{
		Name:      name,
		OutpostID: outpostID,
		Arn:       outpostsBucketArn(accountID, outpostID, name),
		CreatedAt: time.Now().UTC(),
		Tags:      parseS3ControlTags(req.Tagging),
	}
	if err := s.s3control.CreateOutpostsBucket(accountID, bucket); err != nil {
		if errors.Is(err, s3control.ErrOutpostsBucketAlreadyExists) {
			respondS3ControlErrorXML(w, http.StatusConflict, "BucketAlreadyExists", "bucket already exists")
			return
		}
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to create bucket")
		return
	}
	respondS3XML(w, http.StatusOK, s3ControlCreateOutpostsBucketResult{
		BucketArn:  bucket.Arn,
		BucketName: bucket.Name,
		OutpostId:  bucket.OutpostID,
	})
}

