func (s *Server) handleS3ControlPutOutpostsBucketTagging(w http.ResponseWriter, r *http.Request, accountID, outpostID, bucket string) {
	body, err := readBodyBytes(r)
	if err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read request body")
		return
	}
	allowed := map[string]map[string]bool{
		"Tagging": {
			"Tag": true,
		},
		"Tagging/Tag": {
			"Key":   true,
			"Value": true,
		},
	}
	if err := validateS3ControlXML(body, "Tagging", s3ControlNamespace, allowed, nil); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var tagging s3ControlTagging
	if err := xml.NewDecoder(bytes.NewReader(body)).Decode(&tagging); err != nil {
		respondS3ControlErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	info, err := s.s3control.GetOutpostsBucket(accountID, bucket)
	if err != nil || info.OutpostID != outpostID {
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchOutpostsBucket", "outposts bucket not found")
		return
	}
	if err := s.s3control.PutOutpostsBucketTagging(accountID, bucket, parseS3ControlTags(&tagging)); err != nil {
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchOutpostsBucket", "outposts bucket not found")
		return
	}
	w.WriteHeader(http.StatusOK)
}

func (s *Server) handleS3ControlGetOutpostsBucketTagging(w http.ResponseWriter, r *http.Request, accountID, outpostID, bucket string) {
	info, err := s.s3control.GetOutpostsBucket(accountID, bucket)
	if err != nil || info.OutpostID != outpostID {
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchOutpostsBucket", "outposts bucket not found")
		return
	}
	tags, err := s.s3control.GetOutpostsBucketTagging(accountID, bucket)
	if err != nil {
		if errors.Is(err, s3control.ErrOutpostsBucketTaggingNotFound) {
			respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchTagSet", "tagging not found")
			return
		}
		respondS3ControlErrorXML(w, http.StatusNotFound, "NoSuchOutpostsBucket", "outposts bucket not found")
		return
	}
	tagging := s3ControlTagging{}
	for k, v := range tags {
		tagging.Tags = append(tagging.Tags, s3ControlTag{Key: k, Value: v})
	}
	respondS3XML(w, http.StatusOK, s3ControlGetOutpostsBucketTaggingResult{Tagging: tagging})
}

