func (s *Server) handleS3OptionsAWS(w http.ResponseWriter, r *http.Request) {
	bucket := bucketFromHost(r.Host)
	if bucket == "" {
		bucket = pathFirstSegment(r.URL.Path)
	}
	if bucket == "" {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	applyCORS(w, r, s.s3, bucket)
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) handleS3CreateBucket(w http.ResponseWriter, r *http.Request) {
	bucket := r.PathValue("bucket")
	acl := r.Header.Get("x-amz-acl")
	if acl != "" && !awsmodels.IsValidS3BucketCannedACL(acl) {
		respondError(w, http.StatusBadRequest, "invalid canned ACL")
		return
	}
	created, err := s.s3.CreateBucket(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketExists) {
			respondError(w, http.StatusConflict, err.Error())
			return
		}
		respondError(w, http.StatusBadRequest, err.Error())
		return
	}
	respondJSON(w, http.StatusCreated, created)
}

func (s *Server) handleS3ListBuckets(w http.ResponseWriter, _ *http.Request) {
	respondJSON(w, http.StatusOK, map[string]any{"buckets": s.s3.ListBuckets()})
}

func (s *Server) handleS3PutObject(w http.ResponseWriter, r *http.Request) {
	bucket := r.PathValue("bucket")
	key := r.PathValue("key")

	body, err := io.ReadAll(io.LimitReader(r.Body, 25<<20))
	if err != nil {
		respondError(w, http.StatusBadRequest, "unable to read object body")
		return
	}

	meta := map[string]string{}
	for k, v := range r.Header {
		if !strings.HasPrefix(strings.ToLower(k), "x-amz-meta-") || len(v) == 0 {
			continue
		}
		meta[strings.TrimPrefix(strings.ToLower(k), "x-amz-meta-")] = v[0]
	}

	acl := r.Header.Get("x-amz-acl")
	storageClass := r.Header.Get("x-amz-storage-class")
	if acl != "" && !awsmodels.IsValidS3ObjectCannedACL(acl) {
		respondError(w, http.StatusBadRequest, "invalid canned ACL")
		return
	}
	if !awsmodels.IsValidS3StorageClass(storageClass) {
		respondError(w, http.StatusBadRequest, "invalid storage class")
		return
	}
	obj, err := s.s3.PutObject(bucket, key, r.Header.Get("Content-Type"), body, meta, acl, storageClass)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondError(w, http.StatusNotFound, err.Error())
			return
		}
		respondError(w, http.StatusBadRequest, err.Error())
		return
	}
	respondJSON(w, http.StatusCreated, obj)
}

func (s *Server) handleS3GetObject(w http.ResponseWriter, r *http.Request) {
	bucket := r.PathValue("bucket")
	key := r.PathValue("key")
	versionID := r.URL.Query().Get("versionId")
	var obj s3.Object
	var err error
	if versionID != "" {
		obj, err = s.s3.GetObjectVersion(bucket, key, versionID)
	} else {
		obj, err = s.s3.GetObject(bucket, key)
	}
	if err != nil {
		status := http.StatusBadRequest
		if errors.Is(err, s3.ErrBucketNotFound) || errors.Is(err, s3.ErrObjectNotFound) {
			status = http.StatusNotFound
		}
		respondError(w, status, err.Error())
		return
	}

	for k, v := range obj.Metadata {
		w.Header().Set("x-amz-meta-"+k, v)
	}
	w.Header().Set("ETag", obj.ETag)
	if obj.ContentType != "" {
		w.Header().Set("Content-Type", obj.ContentType)
	}
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(obj.Body)
}

func (s *Server) handleS3ListObjects(w http.ResponseWriter, r *http.Request) {
	bucket := r.PathValue("bucket")
	objects, err := s.s3.ListObjects(bucket, r.URL.Query().Get("prefix"))
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondError(w, http.StatusNotFound, err.Error())
			return
		}
		respondError(w, http.StatusBadRequest, err.Error())
		return
	}
	respondJSON(w, http.StatusOK, map[string]any{"objects": objects})
}

