type sqsMessageAttributeInput struct {
	name       string
	dataType   string
	stringVal  string
	binaryVal  string
	hasString  bool
	hasBinary  bool
	hasListVal bool
}

func parseSQSMessageSystemAttributes(values url.Values, prefix string) (map[string]string, map[string]sqs.MessageAttributeValue, error) {
	items := map[string]*sqsMessageAttributeInput{}
	for key, vals := range values {
		if !strings.HasPrefix(key, prefix+".") {
			continue
		}
		if len(vals) == 0 {
			continue
		}
		rest := strings.TrimPrefix(key, prefix+".")
		parts := strings.Split(rest, ".")
		if len(parts) < 2 {
			continue
		}
		idx := parts[0]
		field := strings.Join(parts[1:], ".")
		item := items[idx]
		if item == nil {
			item = &sqsMessageAttributeInput{}
			items[idx] = item
		}
		switch field {
		case "Name":
			item.name = vals[0]
		case "Value.DataType":
			item.dataType = vals[0]
		case "Value.StringValue":
			item.stringVal = vals[0]
			item.hasString = true
		case "Value.BinaryValue":
			item.binaryVal = vals[0]
			item.hasBinary = true
		default:
			if strings.Contains(field, "StringListValue") || strings.Contains(field, "BinaryListValue") {
				item.hasListVal = true
			}
		}
	}
	if len(items) == 0 {
		return nil, nil, nil
	}
	out := map[string]string{}
	md5Attrs := map[string]sqs.MessageAttributeValue{}
	for _, item := range items {
		if item.name == "" {
			return nil, nil, errors.New("MessageSystemAttribute name is required")
		}
		if item.dataType == "" {
			return nil, nil, errors.New("MessageSystemAttribute data type is required")
		}
		baseType := item.dataType
		if strings.Contains(baseType, ".") {
			baseType = strings.Split(baseType, ".")[0]
		}
		switch baseType {
		case "String", "Number":
			if !item.hasString {
				return nil, nil, errors.New("MessageSystemAttribute string value is required")
			}
		case "Binary":
			if !item.hasBinary {
				return nil, nil, errors.New("MessageSystemAttribute binary value is required")
			}
		default:
			return nil, nil, errors.New("MessageSystemAttribute data type is invalid")
		}
		if item.hasListVal {
			return nil, nil, errors.New("MessageSystemAttribute list values are not supported")
		}
		out[item.name] = item.stringVal
		if baseType == "Binary" {
			out[item.name] = item.binaryVal
		}
		md5Attrs[item.name] = sqs.MessageAttributeValue{
			DataType:    item.dataType,
			StringValue: item.stringVal,
			BinaryValue: item.binaryVal,
		}
	}
	return out, md5Attrs, nil
}

func parseSQSMessageAttributes(values url.Values, prefix string) (map[string]sqs.MessageAttributeValue, error) {
	items := map[string]*sqsMessageAttributeInput{}
	for key, vals := range values {
		if !strings.HasPrefix(key, prefix+".") {
			continue
		}
		if len(vals) == 0 {
			continue
		}
		rest := strings.TrimPrefix(key, prefix+".")
		parts := strings.Split(rest, ".")
		if len(parts) < 2 {
			continue
		}
		idx := parts[0]
		field := strings.Join(parts[1:], ".")
		item := items[idx]
		if item == nil {
			item = &sqsMessageAttributeInput{}
			items[idx] = item
		}
		switch field {
		case "Name":
			item.name = vals[0]
		case "Value.DataType":
			item.dataType = vals[0]
		case "Value.StringValue":
			item.stringVal = vals[0]
			item.hasString = true
		case "Value.BinaryValue":
			item.binaryVal = vals[0]
			item.hasBinary = true
		default:
			if strings.Contains(field, "StringListValue") || strings.Contains(field, "BinaryListValue") {
				item.hasListVal = true
			}
		}
	}
	if len(items) == 0 {
		return nil, nil
	}
	if len(items) > 10 {
		return nil, errors.New("MessageAttribute exceeds maximum count of 10")
	}
	out := make(map[string]sqs.MessageAttributeValue, len(items))
	for _, item := range items {
		if item.name == "" {
			return nil, errors.New("MessageAttribute name is required")
		}
		if len(item.name) > 256 {
			return nil, errors.New("MessageAttribute name too long")
		}
		if strings.HasPrefix(item.name, "AWS.") || strings.HasPrefix(item.name, "Amazon.") {
			return nil, errors.New("MessageAttribute name prefix is reserved")
		}
		if item.dataType == "" {
			return nil, errors.New("MessageAttribute data type is required")
		}
		baseType := item.dataType
		if strings.Contains(baseType, ".") {
			baseType = strings.Split(baseType, ".")[0]
		}
		switch baseType {
		case "String", "Number":
			if !item.hasString {
				return nil, errors.New("MessageAttribute string value is required")
			}
		case "Binary":
			if !item.hasBinary {
				return nil, errors.New("MessageAttribute binary value is required")
			}
		default:
			return nil, errors.New("MessageAttribute data type is invalid")
		}
		if item.hasListVal {
			return nil, errors.New("MessageAttribute list values are not supported")
		}
		if _, exists := out[item.name]; exists {
			return nil, errors.New("MessageAttribute name must be unique")
		}
		out[item.name] = sqs.MessageAttributeValue{
			DataType:    item.dataType,
			StringValue: item.stringVal,
			BinaryValue: item.binaryVal,
		}
	}
	return out, nil
}

func parseSQSBatchMessageSystemAttributes(values url.Values, entryPrefix string) (map[string]map[string]string, map[string]map[string]sqs.MessageAttributeValue, map[string]error) {
	type attrKey struct {
		entry string
		idx   string
	}
	items := map[attrKey]*sqsMessageAttributeInput{}
	for key, vals := range values {
		if !strings.HasPrefix(key, entryPrefix+".") {
			continue
		}
		if len(vals) == 0 {
			continue
		}
		rest := strings.TrimPrefix(key, entryPrefix+".")
		parts := strings.Split(rest, ".")
		if len(parts) < 4 {
			continue
		}
		entryIdx := parts[0]
		if parts[1] != "MessageSystemAttribute" {
			continue
		}
		attrIdx := parts[2]
		field := strings.Join(parts[3:], ".")
		k := attrKey{entry: entryIdx, idx: attrIdx}
		item := items[k]
		if item == nil {
			item = &sqsMessageAttributeInput{}
			items[k] = item
		}
		switch field {
		case "Name":
			item.name = vals[0]
		case "Value.DataType":
			item.dataType = vals[0]
		case "Value.StringValue":
			item.stringVal = vals[0]
			item.hasString = true
		case "Value.BinaryValue":
			item.binaryVal = vals[0]
			item.hasBinary = true
		default:
			if strings.Contains(field, "StringListValue") || strings.Contains(field, "BinaryListValue") {
				item.hasListVal = true
			}
		}
	}
	out := map[string]map[string]string{}
	md5Attrs := map[string]map[string]sqs.MessageAttributeValue{}
	errs := map[string]error{}
	if len(items) == 0 {
		return out, md5Attrs, errs
	}
	byEntry := map[string][]*sqsMessageAttributeInput{}
	for k, item := range items {
		byEntry[k.entry] = append(byEntry[k.entry], item)
	}
	for entry, list := range byEntry {
		attrMap := map[string]string{}
		md5Map := map[string]sqs.MessageAttributeValue{}
		for _, item := range list {
			if item.name == "" {
				errs[entry] = errors.New("MessageSystemAttribute name is required")
				break
			}
			if item.dataType == "" {
				errs[entry] = errors.New("MessageSystemAttribute data type is required")
				break
			}
			baseType := item.dataType
			if strings.Contains(baseType, ".") {
				baseType = strings.Split(baseType, ".")[0]
			}
			switch baseType {
			case "String", "Number":
				if !item.hasString {
					errs[entry] = errors.New("MessageSystemAttribute string value is required")
					break
				}
			case "Binary":
				if !item.hasBinary {
					errs[entry] = errors.New("MessageSystemAttribute binary value is required")
					break
				}
			default:
				errs[entry] = errors.New("MessageSystemAttribute data type is invalid")
				break
			}
			if item.hasListVal {
				errs[entry] = errors.New("MessageSystemAttribute list values are not supported")
				break
			}
			attrMap[item.name] = item.stringVal
			if baseType == "Binary" {
				attrMap[item.name] = item.binaryVal
			}
			md5Map[item.name] = sqs.MessageAttributeValue{
				DataType:    item.dataType,
				StringValue: item.stringVal,
				BinaryValue: item.binaryVal,
			}
		}
		if errs[entry] == nil {
			out[entry] = attrMap
			md5Attrs[entry] = md5Map
		}
	}
	return out, md5Attrs, errs
}

