func (s *Server) getObjectAttributes(w http.ResponseWriter, r *http.Request, bucket, key string) {
	if !s.requireSigV4(w, r) {
		return
	}
	attrHeader := r.Header.Get("x-amz-object-attributes")
	if strings.TrimSpace(attrHeader) == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing x-amz-object-attributes header")
		return
	}
	requested := map[string]bool{}
	for _, part := range strings.Split(attrHeader, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		requested[part] = true
	}
	versionID := r.URL.Query().Get("versionId")
	var obj s3.Object
	var err error
	if versionID != "" {
		obj, err = s.s3.GetObjectVersion(bucket, key, versionID)
	} else {
		obj, err = s.s3.GetObject(bucket, key)
	}
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}

	resp := s3ObjectAttributesResponse{
		Xmlns: "http://s3.amazonaws.com/doc/2006-03-01/",
	}
	for attr := range requested {
		switch attr {
		case "ETag":
			resp.ETag = `"` + obj.ETag + `"`
		case "ObjectSize":
			size := obj.SizeBytes
			resp.ObjectSize = &size
		case "StorageClass":
			resp.StorageClass = storageClassOrDefault(obj.StorageClass)
		case "LastModified":
			resp.LastModified = obj.UpdatedAt.Format(time.RFC3339)
		case "VersionId":
			if obj.VersionID != "" {
				resp.VersionID = obj.VersionID
			}
		case "DeleteMarker":
			if obj.DeleteMarker {
				val := true
				resp.DeleteMarker = &val
			}
		default:
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unsupported object attribute")
			return
		}
	}

	respondS3XML(w, http.StatusOK, resp)
}

func (s *Server) getObjectRetention(w http.ResponseWriter, r *http.Request, bucket, key string) {
	if !s.requireSigV4(w, r) {
		return
	}
	versionID := r.URL.Query().Get("versionId")
	retention, err := s.s3.GetObjectRetention(bucket, key, versionID)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if retention == nil {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchObjectLockConfiguration", "retention not configured")
		return
	}
	respondS3XML(w, http.StatusOK, s3ObjectRetentionConfiguration{
		Xmlns:       "http://s3.amazonaws.com/doc/2006-03-01/",
		Mode:        retention.Mode,
		RetainUntil: retention.RetainUntil.UTC().Format(time.RFC3339),
	})
}

func (s *Server) putObjectRetention(w http.ResponseWriter, r *http.Request, bucket, key string) {
	if !s.requireSigV4(w, r) {
		return
	}
	var cfg s3ObjectRetentionConfiguration
	if err := xml.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&cfg); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if strings.TrimSpace(cfg.Mode) == "" || strings.TrimSpace(cfg.RetainUntil) == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing retention fields")
		return
	}
	mode := strings.ToUpper(strings.TrimSpace(cfg.Mode))
	if mode != "GOVERNANCE" && mode != "COMPLIANCE" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid retention mode")
		return
	}
	retainUntil, err := time.Parse(time.RFC3339, strings.TrimSpace(cfg.RetainUntil))
	if err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid retain until date")
		return
	}
	if retainUntil.Before(time.Now().UTC()) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "retain until date must be in the future")
		return
	}
	lockCfg, err := s.s3.GetBucketObjectLock(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if lockCfg == nil || !lockCfg.Enabled {
		respondS3ErrorXML(w, http.StatusNotFound, "ObjectLockConfigurationNotFoundError", "object lock not configured")
		return
	}
	versionID := r.URL.Query().Get("versionId")
	retention := &s3.ObjectRetention{
		Mode:        mode,
		RetainUntil: retainUntil,
	}
	if err := s.s3.SetObjectRetention(bucket, key, versionID, retention); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	w.WriteHeader(http.StatusOK)
}

