func (s *Server) putObjectLegalHold(w http.ResponseWriter, r *http.Request, bucket, key string) {
	if !s.requireSigV4(w, r) {
		return
	}
	var cfg s3ObjectLegalHoldConfiguration
	if err := xml.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&cfg); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	status := strings.ToUpper(strings.TrimSpace(cfg.Status))
	if status == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing legal hold status")
		return
	}
	if status != "ON" && status != "OFF" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid legal hold status")
		return
	}
	lockCfg, err := s.s3.GetBucketObjectLock(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if lockCfg == nil || !lockCfg.Enabled {
		respondS3ErrorXML(w, http.StatusNotFound, "ObjectLockConfigurationNotFoundError", "object lock not configured")
		return
	}
	versionID := r.URL.Query().Get("versionId")
	hold := &s3.ObjectLegalHold{Status: status}
	if err := s.s3.SetObjectLegalHold(bucket, key, versionID, hold); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	w.WriteHeader(http.StatusOK)
}

func (s *Server) getBucketObjectLockConfiguration(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	cfg, err := s.s3.GetBucketObjectLock(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if cfg == nil || !cfg.Enabled {
		respondS3ErrorXML(w, http.StatusNotFound, "ObjectLockConfigurationNotFoundError", "object lock not configured")
		return
	}
	resp := s3ObjectLockConfiguration{
		Xmlns:             "http://s3.amazonaws.com/doc/2006-03-01/",
		ObjectLockEnabled: "Enabled",
	}
	if cfg.DefaultRetention != nil {
		resp.Rule = &s3ObjectLockRule{
			DefaultRetention: &s3ObjectLockDefaultRetention{
				Mode:  cfg.DefaultRetention.Mode,
				Days:  cfg.DefaultRetention.Days,
				Years: cfg.DefaultRetention.Years,
			},
		}
	}
	respondS3XML(w, http.StatusOK, resp)
}

func (s *Server) putBucketObjectLockConfiguration(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	var cfg s3ObjectLockConfiguration
	if err := xml.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&cfg); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if strings.TrimSpace(cfg.ObjectLockEnabled) == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing object lock enabled")
		return
	}
	out := &s3.ObjectLockConfiguration{
		Enabled: strings.EqualFold(cfg.ObjectLockEnabled, "Enabled"),
	}
	if cfg.Rule != nil && cfg.Rule.DefaultRetention != nil {
		out.DefaultRetention = &s3.DefaultRetention{
			Mode:  cfg.Rule.DefaultRetention.Mode,
			Days:  cfg.Rule.DefaultRetention.Days,
			Years: cfg.Rule.DefaultRetention.Years,
		}
	}
	if err := s.s3.SetBucketObjectLock(bucket, out); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	w.WriteHeader(http.StatusOK)
}

