func (s *Server) getBucketAnalyticsConfig(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	if _, err := s.s3.GetBucket(bucket); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, "", "s3:GetAnalyticsConfiguration", "private") {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	id := r.URL.Query().Get("id")
	if id == "" {
		s.listBucketAnalyticsConfigs(w, r, bucket)
		return
	}
	cfg, ok, err := s.s3.GetBucketAnalyticsConfig(bucket, id)
	if err != nil {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
		return
	}
	if !ok {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchConfiguration", "analytics configuration not found")
		return
	}
	rendered, err := renderAnalyticsConfig(cfg.Payload)
	if err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid configuration")
		return
	}
	w.Header().Set("Content-Type", "application/xml")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte(stripXMLHeader(rendered)))
}

func (s *Server) listBucketAnalyticsConfigs(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.authorizeS3Request(r, bucket, "", "s3:ListBucketAnalyticsConfigurations", "private") {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	configs, err := s.s3.ListBucketAnalyticsConfigs(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	continuation := r.URL.Query().Get("continuation-token")
	maxKeys := parseMaxKeys(r.URL.Query().Get("max-keys"))
	start := 0
	if continuation != "" {
		for i := range configs {
			if configs[i].ID > continuation {
				start = i
				break
			}
		}
	}
	end := start + maxKeys
	truncated := false
	nextToken := ""
	if end < len(configs) {
		truncated = true
		nextToken = configs[end-1].ID
	} else {
		end = len(configs)
	}
	payloads := make([]s3AnalyticsConfigDoc, 0, end-start)
	for _, cfg := range configs[start:end] {
		rendered, err := parseAnalyticsConfig(cfg.Payload)
		if err != nil {
			continue
		}
		rendered.Xmlns = ""
		payloads = append(payloads, rendered)
	}
	resp := s3ListAnalyticsConfigsResult{
		Xmlns:                   "http://s3.amazonaws.com/doc/2006-03-01/",
		IsTruncated:             truncated,
		ContinuationToken:       continuation,
		NextContinuationToken:   nextToken,
		AnalyticsConfigurations: payloads,
	}
	respondS3XML(w, http.StatusOK, resp)
}

func (s *Server) putBucketAnalyticsConfig(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	if _, err := s.s3.GetBucket(bucket); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, "", "s3:PutAnalyticsConfiguration", "private") {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var cfg s3AnalyticsConfiguration
	if err := xml.Unmarshal(body, &cfg); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var full struct {
		ID                   string        `xml:"Id"`
		Filter               *s3FilterSpec `xml:"Filter,omitempty"`
		StorageClassAnalysis any           `xml:"StorageClassAnalysis"`
	}
	if err := xml.Unmarshal(body, &full); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if err := validateFilterSpec(full.Filter); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if err := validateConfigXML(body, "AnalyticsConfiguration",
		map[string]bool{"Id": true, "Filter": true, "StorageClassAnalysis": true},
		[]string{"Id", "StorageClassAnalysis"},
		nil,
		nil,
	); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if cfg.ID == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing Id")
		return
	}
	if err := s.s3.SetBucketAnalyticsConfig(bucket, s3.BucketAnalyticsConfiguration{ID: cfg.ID, Payload: string(body)}); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	w.WriteHeader(http.StatusOK)
}

