	if !s.authorizeS3Request(r, bucket, "", "s3:GetInventoryConfiguration", "private") {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	id := r.URL.Query().Get("id")
	if id == "" {
		s.listBucketInventoryConfigs(w, r, bucket)
		return
	}
	cfg, ok, err := s.s3.GetBucketInventoryConfig(bucket, id)
	if err != nil {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
		return
	}
	if !ok {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchConfiguration", "inventory configuration not found")
		return
	}
	rendered, err := renderInventoryConfig(cfg.Payload)
	if err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid configuration")
		return
	}
	w.Header().Set("Content-Type", "application/xml")
	w.WriteHeader(http.StatusOK)
