func (s *Server) putBucketIntelligentTieringConfig(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	if _, err := s.s3.GetBucket(bucket); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, "", "s3:PutIntelligentTieringConfiguration", "private") {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var cfg s3IntelligentTieringConfiguration
	if err := xml.Unmarshal(body, &cfg); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var full struct {
		ID     string        `xml:"Id"`
		Filter *s3FilterSpec `xml:"Filter,omitempty"`
	}
	if err := xml.Unmarshal(body, &full); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if err := validateFilterSpec(full.Filter); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if err := validateConfigXML(body, "IntelligentTieringConfiguration",
		map[string]bool{"Id": true, "Filter": true, "Status": true, "Tiering": true},
		[]string{"Id", "Status", "Tiering"},
		[]string{"Tiering/AccessTier", "Tiering/Days"},
		map[string]map[string]bool{
			"Status":             {"ENABLED": true, "DISABLED": true},
			"Tiering/AccessTier": {"ARCHIVE_ACCESS": true, "DEEP_ARCHIVE_ACCESS": true},
		},
	); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !validatePositiveInt(extractXMLPathValue(body, "Tiering/Days")) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid Tiering/Days")
		return
	}
	if cfg.ID == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing Id")
		return
	}
	status := strings.TrimSpace(extractXMLPathValue(body, "Status"))
	if strings.EqualFold(status, "ENABLED") {
		status = "Enabled"
	} else if strings.EqualFold(status, "DISABLED") {
		status = "Disabled"
	}
	if err := s.s3.SetBucketIntelligentTieringConfig(bucket, s3.BucketIntelligentTieringConfiguration{ID: cfg.ID, Payload: string(body), Status: status}); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	w.WriteHeader(http.StatusOK)
}

