func (s *Server) putBucketMetadataConfiguration(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	if _, err := s.s3.GetBucket(bucket); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	var req s3MetadataConfigurationRequest
	if err := xml.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if req.JournalTableConfiguration == nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing JournalTableConfiguration")
		return
	}
	cfg := s3.BucketMetadataConfiguration{
		TableBucketArn:  metadataTableBucketArn(bucket),
		TableBucketType: "aws",
		TableNamespace:  metadataTableNamespace(),
	}
	if req.InventoryTableConfiguration != nil {
		state := strings.TrimSpace(req.InventoryTableConfiguration.ConfigurationState)
		if state == "" {
			state = "ENABLED"
		}
		cfg.InventoryState = strings.ToUpper(state)
		cfg.InventoryTable = bucket + "_inventory"
		cfg.InventoryArn = metadataTableArn(bucket, cfg.InventoryTable)
		cfg.InventoryStatus = "ACTIVE"
	}
	if req.JournalTableConfiguration != nil {
		if req.JournalTableConfiguration.RecordExpiration != nil {
			cfg.JournalDays = req.JournalTableConfiguration.RecordExpiration.Days
			cfg.JournalExpireAt = strings.TrimSpace(req.JournalTableConfiguration.RecordExpiration.Expiration)
		}
		cfg.JournalTable = bucket + "_journal"
		cfg.JournalArn = metadataTableArn(bucket, cfg.JournalTable)
		cfg.JournalStatus = "ACTIVE"
	}
	if err := s.s3.SetBucketMetadataConfiguration(bucket, cfg); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	w.WriteHeader(http.StatusOK)
}

func (s *Server) getBucketMetadataConfiguration(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	cfg, err := s.s3.GetBucketMetadataConfiguration(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrMetadataConfigurationNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchConfiguration", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	result := s3GetBucketMetadataConfigurationResult{
		Xmlns: "http://s3.amazonaws.com/doc/2006-03-01/",
		MetadataConfigurationResult: s3MetadataConfigurationResult{
			DestinationResult: s3MetadataDestinationResult{
				TableBucketArn:  cfg.TableBucketArn,
				TableBucketType: cfg.TableBucketType,
				TableNamespace:  cfg.TableNamespace,
			},
		},
	}
	if cfg.InventoryState != "" {
		result.MetadataConfigurationResult.InventoryTableConfigurationResult = &s3MetadataInventoryTableConfigurationResult{
			ConfigurationState: cfg.InventoryState,
			TableArn:           cfg.InventoryArn,
			TableName:          cfg.InventoryTable,
			TableStatus:        cfg.InventoryStatus,
		}
	}
	if cfg.JournalTable != "" {
		rec := &s3MetadataRecordExpiration{}
		if cfg.JournalDays > 0 {
			rec.Days = cfg.JournalDays
		}
		if cfg.JournalExpireAt != "" {
			rec.Expiration = cfg.JournalExpireAt
		}
		result.MetadataConfigurationResult.JournalTableConfigurationResult = &s3MetadataJournalTableConfigurationResult{
			RecordExpiration: rec,
			TableArn:         cfg.JournalArn,
			TableName:        cfg.JournalTable,
			TableStatus:      cfg.JournalStatus,
		}
	}
	respondS3XML(w, http.StatusOK, result)
}

