func (s *Server) createSessionAWS(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	if _, err := s.s3.GetBucket(bucket); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !isDirectoryBucketName(bucket) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "session supported only for directory buckets")
		return
	}
	resp := s3CreateSessionResult{
		Xmlns: "http://s3.amazonaws.com/doc/2006-03-01/",
		Credentials: s3SessionCredentials{
			AccessKeyID:     "ASIA" + randomHex(8),
			SecretAccessKey: randomHex(16),
			SessionToken:    randomHex(24),
			Expiration:      time.Now().UTC().Add(15 * time.Minute).Format(time.RFC3339),
		},
	}
	respondS3XML(w, http.StatusOK, resp)
}

func (s *Server) listDirectoryBucketsAWS(w http.ResponseWriter, r *http.Request) {
	ok, status, code, msg, authPresent := s.validateSigV4(r)
	if !ok && authPresent {
		respondS3ErrorXML(w, status, code, msg)
		return
	}
	buckets := s.s3.ListBuckets()
	filtered := make([]s3.Bucket, 0, len(buckets))
	for _, b := range buckets {
		if isDirectoryBucketName(b.Name) {
			filtered = append(filtered, b)
		}
	}
	continuation := r.URL.Query().Get("continuation-token")
	max := parseMaxKeys(r.URL.Query().Get("max-directory-buckets"))
	start := 0
	if continuation != "" {
		for i := range filtered {
			if filtered[i].Name > continuation {
				start = i
				break
			}
		}
	}
	end := start + max
	nextToken := ""
	if end < len(filtered) {
		nextToken = filtered[end-1].Name
	} else {
		end = len(filtered)
	}
	resp := s3ListAllMyDirectoryBucketsResult{
		Xmlns:             "http://s3.amazonaws.com/doc/2006-03-01/",
		ContinuationToken: nextToken,
		Buckets:           s3DirectoryBucketList{Buckets: make([]s3DirectoryBucket, 0, end-start)},
	}
	for _, b := range filtered[start:end] {
		resp.Buckets.Buckets = append(resp.Buckets.Buckets, s3DirectoryBucket{
			BucketArn:    "arn:aws:s3:::" + b.Name,
			BucketRegion: "us-east-1",
			CreationDate: b.CreatedAt.Format(time.RFC3339),
			Name:         b.Name,
		})
	}
	respondS3XML(w, http.StatusOK, resp)
}

func (s *Server) getBucketNotification(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	cfg, err := s.s3.GetBucketNotifications(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	resp := s3NotificationConfiguration{
		Xmlns: "http://s3.amazonaws.com/doc/2006-03-01/",
	}
	if cfg != nil {
		for _, q := range cfg.QueueConfigurations {
			queueCfg := s3QueueConfiguration{
				ID:     q.ID,
				Queue:  q.Queue,
				Events: append([]string(nil), q.Events...),
			}
			if q.Prefix != "" || q.Suffix != "" {
				filter := &s3FilterWrapper{S3Key: &s3KeyFilter{}}
				if q.Prefix != "" {
					filter.S3Key.Rules = append(filter.S3Key.Rules, s3FilterRule{Name: "prefix", Value: q.Prefix})
				}
				if q.Suffix != "" {
					filter.S3Key.Rules = append(filter.S3Key.Rules, s3FilterRule{Name: "suffix", Value: q.Suffix})
				}
				queueCfg.Filter = filter
			}
			resp.QueueConfigurations = append(resp.QueueConfigurations, queueCfg)
		}
	}
	respondS3XML(w, http.StatusOK, resp)
}

func (s *Server) putBucketNotification(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	var req s3NotificationConfiguration
	if err := xml.Unmarshal(body, &req); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	cfg := &s3.BucketNotificationConfiguration{}
	for _, q := range req.QueueConfigurations {
		queue := strings.TrimSpace(q.Queue)
		if queue == "" {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidArgument", "missing queue ARN")
			return
		}
		if len(q.Events) == 0 {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidArgument", "missing event configuration")
			return
		}
		if err := validateNotificationEvents(q.Events); err != nil {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidArgument", err.Error())
			return
		}
		prefix, suffix, err := parseNotificationFilter(q.Filter)
		if err != nil {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidArgument", err.Error())
			return
		}
		cfg.QueueConfigurations = append(cfg.QueueConfigurations, s3.QueueNotificationConfiguration{
			ID:     q.ID,
			Queue:  queue,
			Events: append([]string(nil), q.Events...),
			Prefix: prefix,
			Suffix: suffix,
		})
	}
	if err := s.s3.SetBucketNotifications(bucket, cfg); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	w.WriteHeader(http.StatusOK)
}

