func (s *Server) getBucketReplication(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	cfg, err := s.s3.GetBucketReplication(bucket)
	if err != nil {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
		return
	}
	if cfg == nil || len(cfg.Rules) == 0 {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchReplicationConfiguration", "replication not configured")
		return
	}
	resp := s3ReplicationConfiguration{
		Xmlns: "http://s3.amazonaws.com/doc/2006-03-01/",
		Role:  cfg.Role,
	}
	for _, rule := range cfg.Rules {
		outRule := s3ReplicationRule{
			ID:     rule.ID,
			Status: rule.Status,
			Prefix: rule.Prefix,
			Destination: s3ReplicationDestination{
				Bucket: rule.DestinationBucket,
			},
		}
		if rule.DeleteMarkerReplication {
			outRule.DeleteMarkerReplication = &s3DeleteMarkerReplication{Status: "Enabled"}
		}
		resp.Rules = append(resp.Rules, outRule)
	}
	respondS3XML(w, http.StatusOK, resp)
}

