func (s *Server) putBucketReplication(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	var cfg s3ReplicationConfiguration
	if err := xml.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&cfg); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	out := &s3.ReplicationConfiguration{Role: cfg.Role}
	for _, rule := range cfg.Rules {
		prefix := rule.Prefix
		if prefix == "" && rule.Filter != nil {
			prefix = rule.Filter.Prefix
		}
		destBucket := parseReplicationDestination(rule.Destination.Bucket)
		if destBucket == "" {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing replication destination bucket")
			return
		}
		status := rule.Status
		if status == "" {
			status = "Disabled"
		}
		deleteMarkers := false
		if rule.DeleteMarkerReplication != nil && strings.EqualFold(rule.DeleteMarkerReplication.Status, "Enabled") {
			deleteMarkers = true
		}
		out.Rules = append(out.Rules, s3.ReplicationRule{
			ID:                      rule.ID,
			Status:                  status,
			Prefix:                  prefix,
			DestinationBucket:       destBucket,
			DeleteMarkerReplication: deleteMarkers,
		})
	}
	if err := s.s3.SetBucketReplication(bucket, out); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	w.WriteHeader(http.StatusOK)
}

