func (s *Server) listObjectVersionsAWS(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	bucketInfo, err := s.s3.GetBucket(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, "", "s3:ListBucket", bucketInfo.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	prefix := r.URL.Query().Get("prefix")
	state := []s3ObjectVersion{}
	deletes := []s3DeleteMarker{}

	objects, err := s.s3.ListObjectVersions(bucket, prefix)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	for _, obj := range objects {
		if obj.DeleteMarker {
			deletes = append(deletes, s3DeleteMarker{
				Key:          obj.Key,
				VersionID:    obj.VersionID,
				IsLatest:     obj.IsLatest,
				LastModified: obj.UpdatedAt.Format(time.RFC3339),
			})
			continue
		}
		state = append(state, s3ObjectVersion{
			Key:          obj.Key,
			VersionID:    obj.VersionID,
			IsLatest:     obj.IsLatest,
			LastModified: obj.UpdatedAt.Format(time.RFC3339),
			ETag:         `"` + obj.ETag + `"`,
			Size:         obj.SizeBytes,
			StorageClass: storageClassOrDefault(obj.StorageClass),
		})
	}

	resp := s3ListObjectVersionsResult{
		Xmlns:         "http://s3.amazonaws.com/doc/2006-03-01/",
		Name:          bucket,
		Prefix:        prefix,
		IsTruncated:   false,
		Versions:      state,
		DeleteMarkers: deletes,
	}
	respondS3XML(w, http.StatusOK, resp)
}

func (s *Server) putObjectAWS(w http.ResponseWriter, r *http.Request, bucket, key string) {
	if bucket == "" || key == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing bucket or key")
		return
	}
	bucketInfo, err := s.s3.GetBucket(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, key, "s3:PutObject", bucketInfo.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	if !checkPutPreconditions(r, s.s3, bucket, key) {
		respondS3ErrorXML(w, http.StatusPreconditionFailed, "PreconditionFailed", "precondition failed")
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, 25<<20))
	if err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read object body")
		return
	}
	if !validateContentMD5(r.Header.Get("Content-MD5"), body) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidDigest", "Content-MD5 mismatch")
		return
	}

	sseInfo, sseCode, sseMsg := parseSSEHeaders(r)
	if sseCode != "" {
		respondS3ErrorXML(w, http.StatusBadRequest, sseCode, sseMsg)
		return
	}

	meta := map[string]string{}
	for k, v := range r.Header {
		if !strings.HasPrefix(strings.ToLower(k), "x-amz-meta-") || len(v) == 0 {
			continue
		}
		meta[strings.TrimPrefix(strings.ToLower(k), "x-amz-meta-")] = v[0]
	}

	acl := r.Header.Get("x-amz-acl")
	if !validateS3ObjectACLHeader(w, acl) {
		return
	}
	storageClass := r.Header.Get("x-amz-storage-class")
	if !awsmodels.IsValidS3StorageClass(storageClass) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidStorageClass", "invalid storage class")
		return
	}
	obj, err := s.s3.PutObject(bucket, key, r.Header.Get("Content-Type"), body, meta, acl, storageClass)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if sseInfo.Algorithm != "" || sseInfo.CustomerAlgorithm != "" {
		if err := s.s3.SetObjectEncryption(bucket, key, obj.VersionID, sseInfo.Algorithm, sseInfo.CustomerAlgorithm, sseInfo.CustomerKeyMD5); err != nil {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
			return
		}
	}

	w.Header().Set("ETag", `"`+obj.ETag+`"`)
	if sseInfo.Algorithm != "" {
		w.Header().Set("x-amz-server-side-encryption", sseInfo.Algorithm)
	}
	if sseInfo.CustomerAlgorithm != "" {
		w.Header().Set("x-amz-server-side-encryption-customer-algorithm", sseInfo.CustomerAlgorithm)
		w.Header().Set("x-amz-server-side-encryption-customer-key-md5", sseInfo.CustomerKeyMD5)
	}
	if obj.VersionID != "" {
		w.Header().Set("x-amz-version-id", obj.VersionID)
	}
	w.WriteHeader(http.StatusOK)

	s.replicateObject(bucket, key, obj)
	s.emitS3Notification(bucket, key, "ObjectCreated:Put", &obj)
}

func (s *Server) getObjectAWS(w http.ResponseWriter, r *http.Request, bucket, key string) {
	if bucket == "" || key == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing bucket or key")
		return
	}
	applyCORS(w, r, s.s3, bucket)
	versionID := r.URL.Query().Get("versionId")
	var obj s3.Object
	var err error
	if versionID != "" {
		obj, err = s.s3.GetObjectVersion(bucket, key, versionID)
	} else {
		obj, err = s.s3.GetObject(bucket, key)
	}
	if err != nil {
		status := http.StatusBadRequest
		code := "InvalidRequest"
		if errors.Is(err, s3.ErrBucketNotFound) {
			status = http.StatusNotFound
			code = "NoSuchBucket"
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			if versionID != "" {
				if marker, ok := s.s3.GetDeleteMarker(bucket, key, versionID); ok {
					w.Header().Set("x-amz-delete-marker", "true")
					if marker.VersionID != "" {
						w.Header().Set("x-amz-version-id", marker.VersionID)
					}
				}
			} else {
				if marker, ok := s.s3.GetLatestDeleteMarker(bucket, key); ok {
					w.Header().Set("x-amz-delete-marker", "true")
					if marker.VersionID != "" {
						w.Header().Set("x-amz-version-id", marker.VersionID)
					}
				}
			}
			status = http.StatusNotFound
			code = "NoSuchKey"
		}
		respondS3ErrorXML(w, status, code, err.Error())
		return
	}

	if !s.authorizeS3Request(r, bucket, key, "s3:GetObject", obj.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}

	if ok, status := checkConditionalHeaders(r, obj); !ok {
		if status == http.StatusNotModified {
			w.WriteHeader(status)
			return
		}
		respondS3ErrorXML(w, status, "PreconditionFailed", "precondition failed")
		return
	}

	if ok, code, msg := validateSSECustomerHeaders(r, obj); !ok {
		respondS3ErrorXML(w, http.StatusBadRequest, code, msg)
		return
	}

	for k, v := range obj.Metadata {
		w.Header().Set("x-amz-meta-"+k, v)
	}
	w.Header().Set("ETag", `"`+obj.ETag+`"`)
	if obj.ContentType != "" {
		w.Header().Set("Content-Type", obj.ContentType)
	}
	setSSEHeaders(w, obj)
	if restore := restoreHeaderValue(obj); restore != "" {
		w.Header().Set("x-amz-restore", restore)
	}

	if rangeHeader := r.Header.Get("Range"); rangeHeader != "" {
		start, end, ok := parseByteRange(rangeHeader, obj.SizeBytes)
		if !ok {
			w.Header().Set("Content-Range", "bytes */"+strconv.Itoa(obj.SizeBytes))
			respondS3ErrorXML(w, http.StatusRequestedRangeNotSatisfiable, "InvalidRange", "invalid range")
			return
		}
		w.Header().Set("Content-Range", "bytes "+strconv.Itoa(start)+"-"+strconv.Itoa(end)+"/"+strconv.Itoa(obj.SizeBytes))
		w.Header().Set("Content-Length", strconv.Itoa(end-start+1))
		w.WriteHeader(http.StatusPartialContent)
		_, _ = w.Write(obj.Body[start : end+1])
		return
	}

	if obj.VersionID != "" {
		w.Header().Set("x-amz-version-id", obj.VersionID)
	}
	w.Header().Set("Content-Length", strconv.Itoa(obj.SizeBytes))
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(obj.Body)
}

func (s *Server) selectObjectContentAWS(w http.ResponseWriter, r *http.Request, bucket, key string) {
	selectType := r.URL.Query().Get("select-type")
	if selectType != "2" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unsupported select type")
		return
	}
	versionID := r.URL.Query().Get("versionId")
	var obj s3.Object
	var err error
	if versionID != "" {
		obj, err = s.s3.GetObjectVersion(bucket, key, versionID)
	} else {
		obj, err = s.s3.GetObject(bucket, key)
	}
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, key, "s3:GetObject", obj.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	if ok, code, msg := validateSSECustomerHeaders(r, obj); !ok {
		respondS3ErrorXML(w, http.StatusBadRequest, code, msg)
		return
	}

	var req s3SelectObjectContentRequest
	if err := xml.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	if req.Expression == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing expression")
		return
	}
	if req.ExpressionType != "" && !strings.EqualFold(req.ExpressionType, "SQL") {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unsupported expression type")
		return
	}
	if req.InputSerialization.CSV == nil && req.InputSerialization.JSON == nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing input serialization")
		return
	}
	if req.InputSerialization.CompressionType != "" && !strings.EqualFold(req.InputSerialization.CompressionType, "NONE") {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "compression not supported")
		return
	}
	if req.OutputSerialization.CSV == nil && req.OutputSerialization.JSON == nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing output serialization")
		return
	}
	if req.OutputSerialization.CSV != nil && req.OutputSerialization.JSON != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "multiple output formats not supported")
		return
	}

	selectInfo, err := parseSelectExpression(req.Expression)
	if err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}

	var buf bytes.Buffer
	switch {
	case req.InputSerialization.CSV != nil:
		csvOutput := req.OutputSerialization.CSV != nil
		if err := runSelectCSV(&buf, obj.Body, req.InputSerialization.CSV, selectInfo, csvOutput); err != nil {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
			return
		}
	case req.InputSerialization.JSON != nil:
		jsonOutput := req.OutputSerialization.JSON != nil
		if !jsonOutput && req.OutputSerialization.CSV != nil {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "JSON input requires JSON output")
			return
		}
		if err := runSelectJSON(&buf, obj.Body, req.InputSerialization.JSON, selectInfo); err != nil {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
			return
		}
	default:
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unsupported input serialization")
		return
	}

	setSSEHeaders(w, obj)
	if req.OutputSerialization.JSON != nil {
		w.Header().Set("Content-Type", "application/json")
	} else {
		w.Header().Set("Content-Type", "text/csv")
	}
	w.Header().Set("Content-Length", strconv.Itoa(buf.Len()))
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(buf.Bytes())
}

func (s *Server) getObjectTorrentAWS(w http.ResponseWriter, r *http.Request, bucket, key string) {
	if bucket == "" || key == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing bucket or key")
		return
	}
	if isDirectoryBucketName(bucket) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "GetObjectTorrent not supported for directory buckets")
		return
	}
	versionID := r.URL.Query().Get("versionId")
	var obj s3.Object
	var err error
	if versionID != "" {
		obj, err = s.s3.GetObjectVersion(bucket, key, versionID)
	} else {
		obj, err = s.s3.GetObject(bucket, key)
	}
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, key, "s3:GetObject", obj.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	w.Header().Set("Content-Type", "application/x-bittorrent")
	w.Header().Set("Content-Length", "0")
	w.WriteHeader(http.StatusOK)
}

func (s *Server) restoreObjectAWS(w http.ResponseWriter, r *http.Request, bucket, key string) {
	if bucket == "" || key == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing bucket or key")
		return
	}
	var req s3RestoreRequest
	if err := xml.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	versionID := r.URL.Query().Get("versionId")
	obj, created, err := s.s3.RestoreObject(bucket, key, versionID, req.Days)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if restore := restoreHeaderValue(obj); restore != "" {
		w.Header().Set("x-amz-restore", restore)
	}
	if created {
		w.WriteHeader(http.StatusAccepted)
	} else {
		w.WriteHeader(http.StatusOK)
	}
}

func (s *Server) writeGetObjectResponseAWS(w http.ResponseWriter, r *http.Request) {
	if !s.requireSigV4(w, r) {
		return
	}
	if strings.TrimSpace(r.Header.Get("x-amz-request-route")) == "" || strings.TrimSpace(r.Header.Get("x-amz-request-token")) == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing request route or token")
		return
	}
	if _, err := io.Copy(io.Discard, io.LimitReader(r.Body, 10<<20)); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid body")
		return
	}
	w.WriteHeader(http.StatusOK)
}

func (s *Server) renameObjectAWS(w http.ResponseWriter, r *http.Request, bucket, key string) {
	if bucket == "" || key == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing bucket or key")
		return
	}
	if !isDirectoryBucketName(bucket) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "rename supported only for directory buckets")
		return
	}
	renameSource := r.Header.Get("x-amz-rename-source")
	if renameSource == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing x-amz-rename-source")
		return
	}
	srcBucket, srcKey := parseCopySource(renameSource)
	if srcBucket == "" || srcKey == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid x-amz-rename-source")
		return
	}
	if srcBucket != bucket {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "rename must stay within bucket")
		return
	}
	if !checkRenamePreconditions(r, s.s3, srcBucket, srcKey) {
		respondS3ErrorXML(w, http.StatusPreconditionFailed, "PreconditionFailed", "rename precondition failed")
		return
	}
	if !checkPutPreconditions(r, s.s3, bucket, key) {
		respondS3ErrorXML(w, http.StatusPreconditionFailed, "PreconditionFailed", "destination precondition failed")
		return
	}
	srcObj, err := s.s3.GetObject(srcBucket, srcKey)
	if err != nil {
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, srcBucket, srcKey, "s3:GetObject", srcObj.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	destBucket, err := s.s3.GetBucket(bucket)
	if err == nil {
		if !s.authorizeS3Request(r, bucket, key, "s3:PutObject", destBucket.ACL) {
			respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
			return
		}
	}
	acl := r.Header.Get("x-amz-acl")
	storageClass := r.Header.Get("x-amz-storage-class")
	if !awsmodels.IsValidS3StorageClass(storageClass) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidStorageClass", "invalid storage class")
		return
	}
	obj, err := s.s3.CopyObject(srcBucket, srcKey, bucket, key, nil, "", acl, storageClass)
	if err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	_ = s.s3.DeleteObject(srcBucket, srcKey)
	resp := s3CopyObjectResult{
		LastModified: obj.UpdatedAt.Format(time.RFC3339),
		ETag:         `"` + obj.ETag + `"`,
	}
	respondS3XML(w, http.StatusOK, resp)
}

func (s *Server) deleteObjectAWS(w http.ResponseWriter, r *http.Request, bucket, key, versionID string) {
	bucketInfo, err := s.s3.GetBucket(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, key, "s3:DeleteObject", bucketInfo.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	bypassGov := bypassGovernanceRetention(r)
	var obj s3.Object
	if versionID != "" {
		obj, err = s.s3.GetObjectVersion(bucket, key, versionID)
	} else {
		obj, err = s.s3.GetObject(bucket, key)
	}
	if err == nil {
		if denied, code, msg := objectLockDenies(obj, bypassGov); denied {
			respondS3ErrorXML(w, http.StatusForbidden, code, msg)
			return
		}
	}
	vid, deleteMarker, err := s.s3.DeleteObjectVersioned(bucket, key, versionID)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if versionID == "" {
		if deleteMarker {
			w.Header().Set("x-amz-delete-marker", "true")
			w.Header().Set("x-amz-version-id", vid)
		}
		w.WriteHeader(http.StatusNoContent)
		replicaVersionID := ""
		if deleteMarker {
			replicaVersionID = vid
		}
		s.replicateDelete(bucket, key, replicaVersionID, deleteMarker)
		eventName := "ObjectRemoved:Delete"
		eventObj := obj
		if deleteMarker {
			eventName = "ObjectRemoved:DeleteMarkerCreated"
			eventObj = s3.Object{Key: key, Bucket: bucket, VersionID: vid, DeleteMarker: true}
		}
		s.emitS3Notification(bucket, key, eventName, &eventObj)
		return
	}
	if vid != "" {
		w.Header().Set("x-amz-version-id", vid)
	}
	w.WriteHeader(http.StatusNoContent)
	s.replicateDelete(bucket, key, versionID, deleteMarker)
	eventName := "ObjectRemoved:Delete"
	eventObj := obj
	if deleteMarker {
		eventName = "ObjectRemoved:DeleteMarkerCreated"
		eventObj = s3.Object{Key: key, Bucket: bucket, VersionID: vid, DeleteMarker: true}
	}
	s.emitS3Notification(bucket, key, eventName, &eventObj)
}

func (s *Server) deleteBucketAWS(w http.ResponseWriter, _ *http.Request, bucket string) {
	if err := s.s3.DeleteBucket(bucket); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrBucketNotEmpty) {
			respondS3ErrorXML(w, http.StatusConflict, "BucketNotEmpty", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

type s3DeleteObjectsRequest struct {
	XMLName xml.Name `xml:"Delete"`
	Quiet   bool     `xml:"Quiet"`
	Objects []struct {
		Key string `xml:"Key"`
	} `xml:"Object"`
}

type s3DeleteObjectsResult struct {
	XMLName xml.Name `xml:"DeleteResult"`
	Xmlns   string   `xml:"xmlns,attr"`
	Deleted []struct {
		Key          string `xml:"Key"`
		VersionID    string `xml:"VersionId,omitempty"`
		DeleteMarker bool   `xml:"DeleteMarker,omitempty"`
	} `xml:"Deleted"`
	Errors []struct {
		Key     string `xml:"Key"`
		Code    string `xml:"Code"`
		Message string `xml:"Message"`
	} `xml:"Error"`
}

func (s *Server) deleteObjectsAWS(w http.ResponseWriter, r *http.Request, bucket string) {
	bucketInfo, err := s.s3.GetBucket(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, "", "s3:DeleteObject", bucketInfo.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	var req s3DeleteObjectsRequest
	if err := xml.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	keys := make([]string, 0, len(req.Objects))
	result := s3DeleteObjectsResult{Xmlns: "http://s3.amazonaws.com/doc/2006-03-01/"}
	bypassGov := bypassGovernanceRetention(r)
	for _, obj := range req.Objects {
		if obj.Key == "" {
			continue
		}
		current, err := s.s3.GetObject(bucket, obj.Key)
		if err == nil {
			if denied, code, msg := objectLockDenies(current, bypassGov); denied {
				result.Errors = append(result.Errors, struct {
					Key     string `xml:"Key"`
					Code    string `xml:"Code"`
					Message string `xml:"Message"`
				}{
					Key:     obj.Key,
					Code:    code,
					Message: msg,
				})
				continue
			}
		}
		keys = append(keys, obj.Key)
	}
	deleted, err := s.s3.DeleteObjects(bucket, keys)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}

	for _, obj := range deleted {
		result.Deleted = append(result.Deleted, struct {
			Key          string `xml:"Key"`
			VersionID    string `xml:"VersionId,omitempty"`
			DeleteMarker bool   `xml:"DeleteMarker,omitempty"`
		}{
			Key:          obj.Key,
			VersionID:    obj.VersionID,
			DeleteMarker: obj.DeleteMarker,
		})
	}
	respondS3XML(w, http.StatusOK, result)

	for _, obj := range deleted {
		s.replicateDelete(bucket, obj.Key, obj.VersionID, obj.DeleteMarker)
		eventName := "ObjectRemoved:Delete"
		if obj.DeleteMarker {
			eventName = "ObjectRemoved:DeleteMarkerCreated"
		}
		eventObj := obj
		s.emitS3Notification(bucket, obj.Key, eventName, &eventObj)
	}
}

type s3CopyObjectResult struct {
	XMLName      xml.Name `xml:"CopyObjectResult"`
	LastModified string   `xml:"LastModified"`
	ETag         string   `xml:"ETag"`
}

func (s *Server) copyObjectAWS(w http.ResponseWriter, r *http.Request, bucket, key, copySource string) {
	if !s.s3.HasBucket(bucket) {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", "bucket not found")
		return
	}
	destBucket, err := s.s3.GetBucket(bucket)
	if err == nil {
		if !s.authorizeS3Request(r, bucket, key, "s3:PutObject", destBucket.ACL) {
			respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
			return
		}
	}
	srcBucket, srcKey := parseCopySource(copySource)
	if srcBucket == "" || srcKey == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid x-amz-copy-source")
		return
	}
	if !s.s3.HasBucket(srcBucket) {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", "bucket not found")
		return
	}
	srcObj, err := s.s3.GetObject(srcBucket, srcKey)
	if err != nil {
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if _, err := s.s3.GetBucket(srcBucket); err == nil {
		if !s.authorizeS3Request(r, srcBucket, srcKey, "s3:GetObject", srcObj.ACL) {
			respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
			return
		}
	}
	if !checkCopyPreconditions(r, s.s3, srcBucket, srcKey) {
		respondS3ErrorXML(w, http.StatusPreconditionFailed, "PreconditionFailed", "copy precondition failed")
		return
	}

	metaDirective := strings.ToUpper(r.Header.Get("x-amz-metadata-directive"))
	if !awsmodels.IsValidS3MetadataDirective(metaDirective) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid metadata directive")
		return
	}
	var metadata map[string]string
	contentType := ""
	storageClass := r.Header.Get("x-amz-storage-class")
	if !awsmodels.IsValidS3StorageClass(storageClass) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidStorageClass", "invalid storage class")
		return
	}
	if metaDirective == "REPLACE" {
		metadata = map[string]string{}
		for k, v := range r.Header {
			if !strings.HasPrefix(strings.ToLower(k), "x-amz-meta-") || len(v) == 0 {
				continue
			}
			metadata[strings.TrimPrefix(strings.ToLower(k), "x-amz-meta-")] = v[0]
		}
		contentType = r.Header.Get("Content-Type")
	}
	acl := r.Header.Get("x-amz-acl")
	if !validateS3ObjectACLHeader(w, acl) {
		return
	}
	sseInfo, sseCode, sseMsg := parseSSEHeaders(r)
	if sseCode != "" {
		respondS3ErrorXML(w, http.StatusBadRequest, sseCode, sseMsg)
		return
	}

	obj, err := s.s3.CopyObject(srcBucket, srcKey, bucket, key, metadata, contentType, acl, storageClass)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if sseInfo.Algorithm != "" || sseInfo.CustomerAlgorithm != "" {
		if err := s.s3.SetObjectEncryption(bucket, key, obj.VersionID, sseInfo.Algorithm, sseInfo.CustomerAlgorithm, sseInfo.CustomerKeyMD5); err != nil {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
			return
		}
	}

	result := s3CopyObjectResult{
		LastModified: obj.UpdatedAt.Format(time.RFC3339),
		ETag:         `"` + obj.ETag + `"`,
	}
	if sseInfo.Algorithm != "" {
		w.Header().Set("x-amz-server-side-encryption", sseInfo.Algorithm)
	}
	if sseInfo.CustomerAlgorithm != "" {
		w.Header().Set("x-amz-server-side-encryption-customer-algorithm", sseInfo.CustomerAlgorithm)
		w.Header().Set("x-amz-server-side-encryption-customer-key-md5", sseInfo.CustomerKeyMD5)
	}
	if obj.VersionID != "" {
		w.Header().Set("x-amz-version-id", obj.VersionID)
	}
	respondS3XML(w, http.StatusOK, result)

	s.replicateObject(bucket, key, obj)
	s.emitS3Notification(bucket, key, "ObjectCreated:Copy", &obj)
}

