func (s *Server) initiateMultipartAWS(w http.ResponseWriter, r *http.Request, bucket string) {
	key := objectKeyFromPath(r.URL.Path, bucket)
	if key == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing object key")
		return
	}
	bucketInfo, err := s.s3.GetBucket(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, key, "s3:PutObject", bucketInfo.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	meta := map[string]string{}
	for k, v := range r.Header {
		if !strings.HasPrefix(strings.ToLower(k), "x-amz-meta-") || len(v) == 0 {
			continue
		}
		meta[strings.TrimPrefix(strings.ToLower(k), "x-amz-meta-")] = v[0]
	}
	acl := r.Header.Get("x-amz-acl")
	if !validateS3ObjectACLHeader(w, acl) {
		return
	}
	storageClass := r.Header.Get("x-amz-storage-class")
	if !awsmodels.IsValidS3StorageClass(storageClass) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidStorageClass", "invalid storage class")
		return
	}
	sseInfo, sseCode, sseMsg := parseSSEHeaders(r)
	if sseCode != "" {
		respondS3ErrorXML(w, http.StatusBadRequest, sseCode, sseMsg)
		return
	}
	uploadID, err := s.s3.InitiateMultipartUpload(bucket, key, r.Header.Get("Content-Type"), meta, acl, storageClass, sseInfo.Algorithm, sseInfo.CustomerAlgorithm, sseInfo.CustomerKeyMD5)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	result := s3InitiateMultipartUploadResult{
		Xmlns:    "http://s3.amazonaws.com/doc/2006-03-01/",
		Bucket:   bucket,
		Key:      key,
		UploadID: uploadID,
	}
	if sseInfo.Algorithm != "" {
		w.Header().Set("x-amz-server-side-encryption", sseInfo.Algorithm)
	}
	if sseInfo.CustomerAlgorithm != "" {
		w.Header().Set("x-amz-server-side-encryption-customer-algorithm", sseInfo.CustomerAlgorithm)
		w.Header().Set("x-amz-server-side-encryption-customer-key-md5", sseInfo.CustomerKeyMD5)
	}
	respondS3XML(w, http.StatusOK, result)
}

func (s *Server) getACL(w http.ResponseWriter, r *http.Request, bucket, key string) {
	if !s.requireSigV4(w, r) {
		return
	}
	owner := s3Owner{ID: "stackyard", DisplayName: "stackyard"}
	acl := "private"
	if key == "" {
		b, err := s.s3.GetBucket(bucket)
		if err != nil {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", "bucket not found")
			return
		}
		acl = b.ACL
	} else {
		versionID := r.URL.Query().Get("versionId")
		var obj s3.Object
		var err error
		if versionID != "" {
			obj, err = s.s3.GetObjectVersion(bucket, key, versionID)
		} else {
			obj, err = s.s3.GetObject(bucket, key)
		}
		if err != nil {
			if errors.Is(err, s3.ErrBucketNotFound) {
				respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
				return
			}
			if errors.Is(err, s3.ErrObjectNotFound) {
				respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
				return
			}
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
			return
		}
		acl = obj.ACL
	}
	policy := aclPolicyFor(acl, owner)
	respondS3XML(w, http.StatusOK, policy)
}

func (s *Server) putACL(w http.ResponseWriter, r *http.Request, bucket string) {
	if !s.requireSigV4(w, r) {
		return
	}
	key := objectKeyFromPath(r.URL.Path, bucket)
	acl := r.Header.Get("x-amz-acl")
	if acl == "" {
		var policy s3AccessControlPolicy
		if err := xml.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&policy); err == nil {
			acl = "private"
		}
	}
	if acl == "" {
		acl = "private"
	}
	if key == "" {
		if !validateS3BucketACLHeader(w, acl) {
			return
		}
	} else {
		if !validateS3ObjectACLHeader(w, acl) {
			return
		}
	}
	if key == "" {
		if err := s.s3.SetBucketACL(bucket, acl); err != nil {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", "bucket not found")
			return
		}
		w.WriteHeader(http.StatusOK)
		return
	}
	versionID := r.URL.Query().Get("versionId")
	if err := s.s3.SetObjectACL(bucket, key, versionID, acl); err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	w.WriteHeader(http.StatusOK)
}

func aclPolicyFor(acl string, owner s3Owner) s3AccessControlPolicy {
	policy := s3AccessControlPolicy{
		Xmlns: "http://s3.amazonaws.com/doc/2006-03-01/",
		Owner: owner,
	}
	grant := s3Grant{
		Grantee: s3Grantee{
			Xmlns:       "http://www.w3.org/2001/XMLSchema-instance",
			XsiType:     "CanonicalUser",
			ID:          owner.ID,
			DisplayName: owner.DisplayName,
		},
		Permission: "FULL_CONTROL",
	}
	policy.AccessControlList.Grants = append(policy.AccessControlList.Grants, grant)
	if acl == "public-read" {
		policy.AccessControlList.Grants = append(policy.AccessControlList.Grants, s3Grant{
			Grantee: s3Grantee{
				Xmlns:   "http://www.w3.org/2001/XMLSchema-instance",
				XsiType: "Group",
				URI:     "http://acs.amazonaws.com/groups/global/AllUsers",
			},
			Permission: "READ",
		})
	}
	return policy
}

func (s *Server) uploadPartAWS(w http.ResponseWriter, r *http.Request, bucket, uploadID string) {
	key := objectKeyFromPath(r.URL.Path, bucket)
	if key == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing object key")
		return
	}
	bucketInfo, err := s.s3.GetBucket(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, key, "s3:PutObject", bucketInfo.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	partNumberStr := r.URL.Query().Get("partNumber")
	partNumber, err := strconv.Atoi(partNumberStr)
	if err != nil || partNumber <= 0 {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid part number")
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, 25<<20))
	if err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "unable to read part body")
		return
	}
	if !validateContentMD5(r.Header.Get("Content-MD5"), body) {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidDigest", "Content-MD5 mismatch")
		return
	}
	upload, ok := s.s3.GetMultipartUpload(uploadID)
	if !ok {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	if upload.Key != key {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	if upload.SSECustomerAlgorithm != "" {
		info, code, msg := parseSSEHeaders(r)
		if code != "" {
			respondS3ErrorXML(w, http.StatusBadRequest, code, msg)
			return
		}
		if info.CustomerAlgorithm == "" {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing customer encryption headers")
			return
		}
		if info.CustomerAlgorithm != upload.SSECustomerAlgorithm || info.CustomerKeyMD5 != upload.SSECustomerKeyMD5 {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidDigest", "customer key MD5 mismatch")
			return
		}
	}
	obj, err := s.s3.PutMultipartPart(uploadID, partNumber, body)
	if err != nil {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	w.Header().Set("ETag", `"`+obj.ETag+`"`)
	if obj.VersionID != "" {
		w.Header().Set("x-amz-version-id", obj.VersionID)
	}
	w.WriteHeader(http.StatusOK)
}

func (s *Server) uploadPartCopyAWS(w http.ResponseWriter, r *http.Request, bucket, uploadID string) {
	key := objectKeyFromPath(r.URL.Path, bucket)
	if key == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing object key")
		return
	}
	bucketInfo, err := s.s3.GetBucket(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, key, "s3:PutObject", bucketInfo.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	partNumberStr := r.URL.Query().Get("partNumber")
	partNumber, err := strconv.Atoi(partNumberStr)
	if err != nil || partNumber <= 0 {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid part number")
		return
	}
	upload, ok := s.s3.GetMultipartUpload(uploadID)
	if !ok {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	if upload.Key != key {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	if upload.SSECustomerAlgorithm != "" {
		info, code, msg := parseSSEHeaders(r)
		if code != "" {
			respondS3ErrorXML(w, http.StatusBadRequest, code, msg)
			return
		}
		if info.CustomerAlgorithm == "" {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing customer encryption headers")
			return
		}
		if info.CustomerAlgorithm != upload.SSECustomerAlgorithm || info.CustomerKeyMD5 != upload.SSECustomerKeyMD5 {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidDigest", "customer key MD5 mismatch")
			return
		}
	}
	copySource := r.Header.Get("x-amz-copy-source")
	srcBucket, srcKey := parseCopySource(copySource)
	if srcBucket == "" || srcKey == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "invalid x-amz-copy-source")
		return
	}
	srcObj, err := s.s3.GetObject(srcBucket, srcKey)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		if errors.Is(err, s3.ErrObjectNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchKey", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, srcBucket, srcKey, "s3:GetObject", srcObj.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	body := srcObj.Body
	if rangeHeader := r.Header.Get("x-amz-copy-source-range"); rangeHeader != "" {
		start, end, ok := parseByteRange(rangeHeader, srcObj.SizeBytes)
		if !ok {
			respondS3ErrorXML(w, http.StatusRequestedRangeNotSatisfiable, "InvalidRange", "invalid copy source range")
			return
		}
		body = srcObj.Body[start : end+1]
	}
	partObj, err := s.s3.PutMultipartPart(uploadID, partNumber, body)
	if err != nil {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	resp := s3CopyPartResult{
		Xmlns:        "http://s3.amazonaws.com/doc/2006-03-01/",
		LastModified: partObj.UpdatedAt.Format(time.RFC3339),
		ETag:         `"` + partObj.ETag + `"`,
	}
	respondS3XML(w, http.StatusOK, resp)
}

func (s *Server) completeMultipartAWS(w http.ResponseWriter, r *http.Request, bucket, uploadID string) {
	key := objectKeyFromPath(r.URL.Path, bucket)
	if key == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing object key")
		return
	}
	bucketInfo, err := s.s3.GetBucket(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, key, "s3:PutObject", bucketInfo.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	var req s3CompleteMultipartUpload
	if err := xml.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		respondS3ErrorXML(w, http.StatusBadRequest, "MalformedXML", "invalid XML")
		return
	}
	upload, ok := s.s3.GetMultipartUpload(uploadID)
	if !ok {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	if upload.Bucket != bucket {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	if upload.Key != key {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	if upload.SSECustomerAlgorithm != "" {
		info, code, msg := parseSSEHeaders(r)
		if code != "" {
			respondS3ErrorXML(w, http.StatusBadRequest, code, msg)
			return
		}
		if info.CustomerAlgorithm == "" {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing customer encryption headers")
			return
		}
		if info.CustomerAlgorithm != upload.SSECustomerAlgorithm || info.CustomerKeyMD5 != upload.SSECustomerKeyMD5 {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidDigest", "customer key MD5 mismatch")
			return
		}
	}
	if len(req.Parts) == 0 {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing parts")
		return
	}
	if len(req.Parts) > 10000 {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "too many parts")
		return
	}
	parts := make([]int, 0, len(req.Parts))
	lastPartNumber := 0
	for _, part := range req.Parts {
		if part.PartNumber <= lastPartNumber {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidPartOrder", "parts must be in ascending order")
			return
		}
		lastPartNumber = part.PartNumber
		stored, ok := upload.Parts[part.PartNumber]
		if !ok {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidPart", "part not found")
			return
		}
		if strings.Trim(part.ETag, "\"") != stored.ETag {
			respondS3ErrorXML(w, http.StatusBadRequest, "InvalidPart", "etag mismatch")
			return
		}
		parts = append(parts, part.PartNumber)
	}
	for i := 0; i < len(parts)-1; i++ {
		stored := upload.Parts[parts[i]]
		if stored.SizeBytes < 5*1024*1024 {
			respondS3ErrorXML(w, http.StatusBadRequest, "EntityTooSmall", "part too small")
			return
		}
	}
	obj, err := s.s3.CompleteMultipartUpload(uploadID, parts)
	if err != nil {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	result := s3CompleteMultipartUploadResult{
		Xmlns:    "http://s3.amazonaws.com/doc/2006-03-01/",
		Location: "/" + bucket + "/" + key,
		Bucket:   bucket,
		Key:      key,
		ETag:     `"` + obj.ETag + `"`,
	}
	if upload.SSEAlgorithm != "" {
		w.Header().Set("x-amz-server-side-encryption", upload.SSEAlgorithm)
	}
	if upload.SSECustomerAlgorithm != "" {
		w.Header().Set("x-amz-server-side-encryption-customer-algorithm", upload.SSECustomerAlgorithm)
		w.Header().Set("x-amz-server-side-encryption-customer-key-md5", upload.SSECustomerKeyMD5)
	}
	if obj.VersionID != "" {
		w.Header().Set("x-amz-version-id", obj.VersionID)
	}
	respondS3XML(w, http.StatusOK, result)

	s.replicateObject(bucket, key, obj)
	s.emitS3Notification(bucket, key, "ObjectCreated:CompleteMultipartUpload", &obj)
}

func (s *Server) abortMultipartAWS(w http.ResponseWriter, r *http.Request, bucket, uploadID string) {
	key := objectKeyFromPath(r.URL.Path, bucket)
	if key == "" {
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", "missing object key")
		return
	}
	bucketInfo, err := s.s3.GetBucket(bucket)
	if err != nil {
		if errors.Is(err, s3.ErrBucketNotFound) {
			respondS3ErrorXML(w, http.StatusNotFound, "NoSuchBucket", err.Error())
			return
		}
		respondS3ErrorXML(w, http.StatusBadRequest, "InvalidRequest", err.Error())
		return
	}
	if !s.authorizeS3Request(r, bucket, key, "s3:PutObject", bucketInfo.ACL) {
		respondS3ErrorXML(w, http.StatusForbidden, "AccessDenied", "access denied")
		return
	}
	upload, ok := s.s3.GetMultipartUpload(uploadID)
	if !ok || upload.Bucket != bucket || upload.Key != key {
		respondS3ErrorXML(w, http.StatusNotFound, "NoSuchUpload", "upload not found")
		return
	}
	s.s3.AbortMultipartUpload(uploadID)
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) handleSQSCreateQueue(w http.ResponseWriter, r *http.Request) {
	queue := r.PathValue("queue")
	created, err := s.sqs.CreateQueue(queue, nil)
	if err != nil {
		if errors.Is(err, sqs.ErrQueueExists) {
			respondError(w, http.StatusConflict, err.Error())
			return
		}
		respondError(w, http.StatusBadRequest, err.Error())
		return
	}
	respondJSON(w, http.StatusCreated, created)
}

func (s *Server) handleSQSListQueues(w http.ResponseWriter, _ *http.Request) {
	respondJSON(w, http.StatusOK, map[string]any{"queues": s.sqs.ListQueues()})
}

func (s *Server) handleSQSSendMessage(w http.ResponseWriter, r *http.Request) {
	queue := r.PathValue("queue")

	var req struct {
		Body              string                               `json:"body"`
		Attributes        map[string]string                    `json:"attributes"`
		MessageAttributes map[string]sqs.MessageAttributeValue `json:"message_attributes"`
	}
	if err := json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		respondError(w, http.StatusBadRequest, "invalid JSON body")
		return
	}

	msg, err := s.sqs.SendMessage(queue, req.Body, req.Attributes, req.MessageAttributes)
	if err != nil {
		if errors.Is(err, sqs.ErrQueueNotFound) {
			respondError(w, http.StatusNotFound, err.Error())
			return
		}
		respondError(w, http.StatusBadRequest, err.Error())
		return
	}
	respondJSON(w, http.StatusCreated, msg)
}

func (s *Server) handleSQSReceiveMessage(w http.ResponseWriter, r *http.Request) {
	queue := r.PathValue("queue")

	var req struct {
		MaxMessages int `json:"max_messages"`
	}
	if r.Body != nil {
		_ = json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req)
	}

	msgs, err := s.sqs.ReceiveMessages(queue, req.MaxMessages)
	if err != nil {
		if errors.Is(err, sqs.ErrQueueNotFound) {
			respondError(w, http.StatusNotFound, err.Error())
			return
		}
		respondError(w, http.StatusBadRequest, err.Error())
		return
	}
	respondJSON(w, http.StatusOK, map[string]any{"messages": msgs})
}

func respondJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(body); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
	}
}

func respondError(w http.ResponseWriter, status int, message string) {
	respondJSON(w, status, map[string]string{"error": message})
}

func bucketFromHost(host string) string {
	host = strings.TrimSpace(host)
	if host == "" {
		return ""
	}
	if strings.Contains(host, ":") {
		host, _, _ = strings.Cut(host, ":")
	}
	if netIP := net.ParseIP(host); netIP != nil {
		return ""
	}
	lower := strings.ToLower(host)
	if idx := strings.Index(lower, ".s3-accesspoint."); idx != -1 {
		label := host[:idx]
		return trimAccessPointLabel(label)
	}
	if idx := strings.Index(lower, ".s3-accesspoint-"); idx != -1 {
		label := host[:idx]
		return trimAccessPointLabel(label)
	}
	parts := strings.Split(host, ".")
	if len(parts) < 2 {
		return ""
	}
	return parts[0]
}

func trimAccessPointLabel(label string) string {
	if label == "" {
		return ""
	}
	if len(label) > 13 && label[len(label)-13] == '-' {
		suffix := label[len(label)-12:]
		allDigits := true
		for i := 0; i < len(suffix); i++ {
			if suffix[i] < '0' || suffix[i] > '9' {
				allDigits = false
				break
			}
		}
		if allDigits {
			return label[:len(label)-13]
		}
	}
	return label
}

func pathFirstSegment(path string) string {
	path = strings.TrimPrefix(path, "/")
	if path == "" {
		return ""
	}
	segment, _, _ := strings.Cut(path, "/")
	return segment
}

func objectKeyFromPath(path, bucket string) string {
	path = strings.TrimPrefix(path, "/")
	if path == "" {
		return ""
	}
	if bucket == "" {
		return ""
	}
	if !strings.HasPrefix(path, bucket) {
		return ""
	}
	remainder := strings.TrimPrefix(path, bucket)
	remainder = strings.TrimPrefix(remainder, "/")
	return remainder
}

func bucketAndKeyFromPath(path string) (string, string) {
	path = strings.TrimPrefix(path, "/")
	if path == "" {
		return "", ""
	}
	if bucket, key, ok := parseAccessPointArn(path); ok {
		return bucket, key
	}
	bucket, key, _ := strings.Cut(path, "/")
	return bucket, key
}

func parseAccessPointArn(value string) (string, string, bool) {
	value = strings.TrimSpace(value)
	value = strings.TrimPrefix(value, "/")
	if value == "" {
		return "", "", false
	}
	if !strings.HasPrefix(value, "arn:") {
		return "", "", false
	}
	idx := strings.Index(value, ":accesspoint/")
	if idx == -1 {
		return "", "", false
	}
	rest := value[idx+len(":accesspoint/"):]
	if rest == "" {
		return "", "", false
	}
	apName := rest
	key := ""
	if slash := strings.Index(rest, "/"); slash != -1 {
		apName = rest[:slash]
		key = rest[slash+1:]
	}
	if apName == "" {
		return "", "", false
	}
	return apName, key, true
}

func parseByteRange(value string, size int) (int, int, bool) {
	value = strings.TrimSpace(value)
	if !strings.HasPrefix(value, "bytes=") {
		return 0, 0, false
	}
	value = strings.TrimPrefix(value, "bytes=")
	startStr, endStr, _ := strings.Cut(value, "-")
	if startStr == "" && endStr == "" {
		return 0, 0, false
	}

	if startStr == "" {
		end, err := strconv.Atoi(endStr)
		if err != nil || end <= 0 {
			return 0, 0, false
		}
		if end > size {
			end = size
		}
		start := size - end
		if start < 0 {
			start = 0
		}
		return start, size - 1, true
	}

	start, err := strconv.Atoi(startStr)
	if err != nil || start < 0 {
		return 0, 0, false
	}
	if endStr == "" {
		if start >= size {
			return 0, 0, false
		}
		return start, size - 1, true
	}

	end, err := strconv.Atoi(endStr)
	if err != nil || end < start {
		return 0, 0, false
	}
	if start >= size {
		return 0, 0, false
	}
	if end >= size {
		end = size - 1
	}
	return start, end, true
}

func parseMaxKeys(value string) int {
	if value == "" {
		return 1000
	}
	n, err := strconv.Atoi(value)
	if err != nil || n <= 0 {
		return 1000
	}
	if n > 1000 {
		return 1000
	}
	return n
}

func validateS3BucketACLHeader(w http.ResponseWriter, acl string) bool {
	if acl == "" {
		return true
	}
	if awsmodels.IsValidS3BucketCannedACL(acl) {
		return true
	}
	respondS3ErrorXML(w, http.StatusBadRequest, "InvalidArgument", "invalid canned ACL")
	return false
}

func validateS3ObjectACLHeader(w http.ResponseWriter, acl string) bool {
	if acl == "" {
		return true
	}
	if awsmodels.IsValidS3ObjectCannedACL(acl) {
		return true
	}
	respondS3ErrorXML(w, http.StatusBadRequest, "InvalidArgument", "invalid canned ACL")
	return false
}

type sseHeaders struct {
	Algorithm         string
	CustomerAlgorithm string
	CustomerKeyMD5    string
}

func parseSSEHeaders(r *http.Request) (sseHeaders, string, string) {
	sseAlg := strings.ToUpper(strings.TrimSpace(r.Header.Get("x-amz-server-side-encryption")))
	customerAlg := strings.ToUpper(strings.TrimSpace(r.Header.Get("x-amz-server-side-encryption-customer-algorithm")))
	customerKey := strings.TrimSpace(r.Header.Get("x-amz-server-side-encryption-customer-key"))
	customerMD5 := strings.TrimSpace(r.Header.Get("x-amz-server-side-encryption-customer-key-md5"))
	hasCustomer := customerAlg != "" || customerKey != "" || customerMD5 != ""

	if sseAlg != "" && sseAlg != "AES256" {
		if !awsmodels.IsValidS3ServerSideEncryption(sseAlg) {
			return sseHeaders{}, "InvalidRequest", "unsupported server side encryption"
		}
	}
	if sseAlg != "" && hasCustomer {
		return sseHeaders{}, "InvalidRequest", "conflicting server side encryption headers"
	}
	if hasCustomer {
		if customerAlg == "" || customerKey == "" || customerMD5 == "" {
			return sseHeaders{}, "InvalidRequest", "missing customer encryption headers"
		}
		if customerAlg != "AES256" {
			return sseHeaders{}, "InvalidRequest", "unsupported customer encryption algorithm"
		}
		rawKey, err := base64.StdEncoding.DecodeString(customerKey)
		if err != nil {
			return sseHeaders{}, "InvalidRequest", "invalid customer encryption key"
		}
		sum := md5.Sum(rawKey)
		calculated := base64.StdEncoding.EncodeToString(sum[:])
		if calculated != customerMD5 {
			return sseHeaders{}, "InvalidDigest", "customer key MD5 mismatch"
		}
	}
	return sseHeaders{
		Algorithm:         sseAlg,
		CustomerAlgorithm: customerAlg,
		CustomerKeyMD5:    customerMD5,
	}, "", ""
}

func validateSSECustomerHeaders(r *http.Request, obj s3.Object) (bool, string, string) {
	if obj.SSECustomerAlgorithm == "" {
		return true, "", ""
	}
	info, code, msg := parseSSEHeaders(r)
	if code != "" {
		return false, code, msg
	}
	if info.CustomerAlgorithm == "" || info.CustomerKeyMD5 == "" {
		return false, "InvalidRequest", "missing customer encryption headers"
	}
	if info.CustomerAlgorithm != obj.SSECustomerAlgorithm {
		return false, "InvalidRequest", "invalid customer encryption algorithm"
	}
	if info.CustomerKeyMD5 != obj.SSECustomerKeyMD5 {
		return false, "InvalidDigest", "customer key MD5 mismatch"
	}
	return true, "", ""
}

func setSSEHeaders(w http.ResponseWriter, obj s3.Object) {
	if obj.SSEAlgorithm != "" {
		w.Header().Set("x-amz-server-side-encryption", obj.SSEAlgorithm)
	}
	if obj.SSECustomerAlgorithm != "" {
		w.Header().Set("x-amz-server-side-encryption-customer-algorithm", obj.SSECustomerAlgorithm)
		w.Header().Set("x-amz-server-side-encryption-customer-key-md5", obj.SSECustomerKeyMD5)
	}
}

type selectPredicate struct {
	Field string
	Op    string
	Value any
}

type selectExpression struct {
	Predicates []selectPredicate
}

func parseSelectExpression(expr string) (selectExpression, error) {
	expr = strings.TrimSpace(expr)
	expr = strings.TrimSuffix(expr, ";")
	if expr == "" {
		return selectExpression{}, fmt.Errorf("missing expression")
	}
	lower := strings.ToLower(strings.Join(strings.Fields(expr), " "))
	if lower == "select * from s3object" || lower == "select s.* from s3object s" {
		return selectExpression{}, nil
	}
	whereIdx := strings.Index(strings.ToLower(expr), " where ")
	if whereIdx == -1 {
		return selectExpression{}, fmt.Errorf("unsupported select expression")
	}
	head := strings.TrimSpace(expr[:whereIdx])
	headLower := strings.ToLower(strings.Join(strings.Fields(head), " "))
	if headLower != "select * from s3object" && headLower != "select s.* from s3object s" {
		return selectExpression{}, fmt.Errorf("unsupported select expression")
	}
	predicate := strings.TrimSpace(expr[whereIdx+len(" where "):])
	predicates, err := parseSelectPredicates(predicate)
	if err != nil {
		return selectExpression{}, err
	}
	return selectExpression{Predicates: predicates}, nil
}

func parseSelectPredicates(predicate string) ([]selectPredicate, error) {
	parts := splitSelectAnd(predicate)
	out := make([]selectPredicate, 0, len(parts))
	for _, part := range parts {
		field, op, value, err := parseSelectPredicate(part)
		if err != nil {
			return nil, err
		}
		out = append(out, selectPredicate{Field: field, Op: op, Value: value})
	}
	return out, nil
}

func splitSelectAnd(expr string) []string {
	out := []string{}
	var buf strings.Builder
	inSingle := false
	inDouble := false
	upper := strings.ToUpper(expr)
	for i := 0; i < len(expr); i++ {
		ch := expr[i]
		if ch == '\'' && !inDouble {
			inSingle = !inSingle
		} else if ch == '"' && !inSingle {
			inDouble = !inDouble
		}
		if !inSingle && !inDouble && i+3 <= len(expr) && upper[i:i+3] == "AND" {
			before := byte(' ')
			after := byte(' ')
			if i > 0 {
				before = expr[i-1]
			}
			if i+3 < len(expr) {
				after = expr[i+3]
			}
			if isSpace(before) && isSpace(after) {
				part := strings.TrimSpace(buf.String())
				if part != "" {
					out = append(out, part)
				}
				buf.Reset()
				i += 2
				continue
			}
		}
		buf.WriteByte(ch)
	}
	if trimmed := strings.TrimSpace(buf.String()); trimmed != "" {
		out = append(out, trimmed)
	}
	return out
}

func isSpace(ch byte) bool {
	return ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r'
}

func parseSelectPredicate(predicate string) (string, string, any, error) {
	predicate = strings.TrimSpace(predicate)
	ops := []string{"!=", ">=", "<=", "=", ">", "<"}
	for _, op := range ops {
		if idx := strings.Index(predicate, op); idx != -1 {
			field := strings.TrimSpace(predicate[:idx])
			valueRaw := strings.TrimSpace(predicate[idx+len(op):])
			if field == "" || valueRaw == "" {
				return "", "", nil, fmt.Errorf("invalid where clause")
			}
			field = strings.TrimPrefix(field, "s.")
			field = strings.TrimPrefix(field, "S3Object.")
			if strings.HasPrefix(valueRaw, "'") && strings.HasSuffix(valueRaw, "'") && len(valueRaw) >= 2 {
				return field, op, strings.Trim(valueRaw, "'"), nil
			}
			if strings.HasPrefix(valueRaw, "\"") && strings.HasSuffix(valueRaw, "\"") && len(valueRaw) >= 2 {
				return field, op, strings.Trim(valueRaw, "\""), nil
			}
			if num, err := strconv.ParseFloat(valueRaw, 64); err == nil {
				return field, op, num, nil
			}
			return "", "", nil, fmt.Errorf("unsupported where clause literal")
		}
	}
	return "", "", nil, fmt.Errorf("unsupported where clause")
}

func runSelectCSV(buf *bytes.Buffer, body []byte, csvInput *s3SelectCSVInput, expr selectExpression, csvOutput bool) error {
	reader := csv.NewReader(bytes.NewReader(body))
	records, err := reader.ReadAll()
	if err != nil {
		return fmt.Errorf("invalid CSV input")
	}
	if len(records) == 0 {
		return nil
	}
	headerInfo := strings.ToUpper(strings.TrimSpace(csvInput.FileHeaderInfo))
	header := []string{}
	start := 0
	if headerInfo == "USE" {
		header = records[0]
		start = 1
	}
	writer := csv.NewWriter(buf)
	for i := start; i < len(records); i++ {
		rec := records[i]
		if len(expr.Predicates) > 0 {
			ok, err := matchCSVPredicates(rec, header, expr.Predicates)
			if err != nil {
				return err
			}
			if !ok {
				continue
			}
		}
		if err := writer.Write(rec); err != nil {
			return fmt.Errorf("invalid CSV output")
		}
	}
	writer.Flush()
	if err := writer.Error(); err != nil {
		return fmt.Errorf("invalid CSV output")
	}
	return nil
}

func matchCSVPredicates(record []string, header []string, predicates []selectPredicate) (bool, error) {
	for _, pred := range predicates {
		field := pred.Field
		if field == "" {
			continue
		}
		idx := -1
		if len(header) > 0 {
			for i := range header {
				if strings.EqualFold(header[i], field) {
					idx = i
					break
				}
			}
		} else if strings.HasPrefix(field, "_") {
			if n, err := strconv.Atoi(strings.TrimPrefix(field, "_")); err == nil && n > 0 {
				idx = n - 1
			}
		}
		if idx < 0 || idx >= len(record) {
			return false, nil
		}
		val := record[idx]
		ok, err := compareSelectValue(strings.TrimSpace(val), pred.Op, pred.Value)
		if err != nil {
			return false, err
		}
		if !ok {
			return false, nil
		}
	}
	return true, nil
}

func runSelectJSON(buf *bytes.Buffer, body []byte, jsonInput *s3SelectJSONInput, expr selectExpression) error {
	inputType := strings.ToUpper(strings.TrimSpace(jsonInput.Type))
	if inputType == "" {
		inputType = "DOCUMENT"
	}
	switch inputType {
	case "DOCUMENT":
		var payload any
		if err := json.Unmarshal(body, &payload); err != nil {
			return fmt.Errorf("invalid JSON input")
		}
		records := make([]map[string]any, 0)
		switch val := payload.(type) {
		case []any:
			for _, entry := range val {
				obj, ok := entry.(map[string]any)
				if !ok {
					continue
				}
				records = append(records, obj)
			}
		case map[string]any:
			records = append(records, val)
		default:
			return fmt.Errorf("invalid JSON input")
		}
		for _, rec := range records {
			if len(expr.Predicates) > 0 {
				if !matchJSONPredicates(rec, expr.Predicates) {
					continue
				}
			}
			line, err := json.Marshal(rec)
			if err != nil {
				return fmt.Errorf("invalid JSON output")
			}
			buf.Write(line)
			buf.WriteByte('\n')
		}
		return nil
	case "LINES":
		scanner := bufio.NewScanner(bytes.NewReader(body))
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}
			var rec map[string]any
			if err := json.Unmarshal([]byte(line), &rec); err != nil {
				return fmt.Errorf("invalid JSON input")
			}
			if len(expr.Predicates) > 0 && !matchJSONPredicates(rec, expr.Predicates) {
				continue
			}
			out, err := json.Marshal(rec)
			if err != nil {
				return fmt.Errorf("invalid JSON output")
			}
			buf.Write(out)
			buf.WriteByte('\n')
		}
		if err := scanner.Err(); err != nil {
			return fmt.Errorf("invalid JSON input")
		}
		return nil
	default:
		return fmt.Errorf("unsupported JSON input type")
	}
}

func matchJSONPredicates(record map[string]any, predicates []selectPredicate) bool {
	for _, pred := range predicates {
		value, ok := lookupJSONValue(record, pred.Field)
		if !ok {
			return false
		}
		ok = compareSelectAny(value, pred.Op, pred.Value)
		if !ok {
			return false
		}
	}
	return true
}

func lookupJSONValue(record map[string]any, field string) (any, bool) {
	field = strings.TrimSpace(field)
	if field == "" {
		return nil, false
	}
	parts := strings.Split(field, ".")
	var current any = record
	for _, part := range parts {
		obj, ok := current.(map[string]any)
		if !ok {
			return nil, false
		}
		val, ok := obj[part]
		if !ok {
			return nil, false
		}
		current = val
	}
	return current, true
}

func compareSelectValue(raw string, op string, want any) (bool, error) {
	switch v := want.(type) {
	case string:
		return compareStrings(raw, op, v), nil
	case float64:
		num, err := strconv.ParseFloat(raw, 64)
		if err != nil {
			return false, nil
		}
		return compareNumbers(num, op, v), nil
	default:
		return false, fmt.Errorf("unsupported where clause literal")
	}
}

func compareSelectAny(value any, op string, want any) bool {
	switch v := want.(type) {
	case string:
		if s, ok := value.(string); ok {
			return compareStrings(s, op, v)
		}
		return false
	case float64:
		num, ok := toFloat64(value)
		if !ok {
			return false
		}
		return compareNumbers(num, op, v)
	default:
		return false
	}
}

func toFloat64(value any) (float64, bool) {
	switch v := value.(type) {
	case float64:
		return v, true
	case int:
		return float64(v), true
	case int64:
		return float64(v), true
	case json.Number:
		num, err := v.Float64()
		if err != nil {
			return 0, false
		}
		return num, true
	default:
		return 0, false
	}
}

func compareStrings(left string, op string, right string) bool {
	switch op {
	case "=":
		return left == right
	case "!=":
		return left != right
	default:
		return false
	}
}

func compareNumbers(left float64, op string, right float64) bool {
	switch op {
	case "=":
		return left == right
	case "!=":
		return left != right
	case ">":
		return left > right
	case "<":
		return left < right
	case ">=":
		return left >= right
	case "<=":
		return left <= right
	default:
		return false
	}
}

func hasAuthRequest(r *http.Request) bool {
	return strings.TrimSpace(r.Header.Get("Authorization")) != "" ||
		r.URL.Query().Get("X-Amz-Algorithm") != "" ||
		r.URL.Query().Get("X-Amz-Credential") != ""
}

func isPublicObjectQuery(values url.Values) bool {
	if len(values) == 0 {
		return true
	}
	if len(values) == 1 && values.Get("versionId") != "" {
		return true
	}
	return false
}

func isPublicBucketQuery(values url.Values) bool {
	if len(values) == 0 {
		return true
	}
	allowed := map[string]bool{
		"list-type":          true,
		"prefix":             true,
		"delimiter":          true,
		"max-keys":           true,
		"continuation-token": true,
		"start-after":        true,
		"encoding-type":      true,
		"marker":             true,
	}
	for key := range values {
		if !allowed[key] {
			return false
		}
	}
	return true
}

func bucketIsPublic(acl string) bool {
	switch strings.ToLower(strings.TrimSpace(acl)) {
	case "public-read", "public-read-write":
		return true
	default:
		return false
	}
}

func objectLockDenies(obj s3.Object, bypassGovernance bool) (bool, string, string) {
	if obj.LegalHold != nil && strings.EqualFold(obj.LegalHold.Status, "ON") {
		return true, "AccessDenied", "object is under legal hold"
	}
	if obj.Retention == nil {
		return false, "", ""
	}
	if obj.Retention.RetainUntil.After(time.Now().UTC()) {
		mode := strings.ToUpper(strings.TrimSpace(obj.Retention.Mode))
		if mode == "COMPLIANCE" {
			return true, "AccessDenied", "object retention in effect"
		}
		if mode == "GOVERNANCE" && !bypassGovernance {
			return true, "AccessDenied", "object retention in effect"
		}
	}
	return false, "", ""
}

func bypassGovernanceRetention(r *http.Request) bool {
	if _, ok := r.Header["X-Amz-Bypass-Governance-Retention"]; ok {
		return true
	}
	if _, ok := r.URL.Query()["x-amz-bypass-governance-retention"]; ok {
		return true
	}
	val := strings.TrimSpace(r.Header.Get("x-amz-bypass-governance-retention"))
	if val == "" {
		val = strings.TrimSpace(r.URL.Query().Get("x-amz-bypass-governance-retention"))
	}
	if val == "" {
		return false
	}
	if strings.EqualFold(val, "false") {
		return false
	}
	return true
}

type sigV4Request struct {
	AccessKey     string
	ScopeDate     string
	Region        string
	Service       string
	AmzDate       string
	SignedHeaders string
	Signature     string
	QueryAuth     bool
	Expires       int
}

func (s *Server) requireSigV4(w http.ResponseWriter, r *http.Request) bool {
	ok, status, code, msg, _ := s.validateSigV4WithService(r, "")
	if !ok {
		respondS3ErrorXML(w, status, code, msg)
		return false
	}
	return true
}

func (s *Server) requireSigV4Service(w http.ResponseWriter, r *http.Request, service string) bool {
	ok, status, code, msg, _ := s.validateSigV4WithService(r, service)
	if !ok {
		respondS3ControlErrorXML(w, status, code, msg)
		return false
	}
	return true
}

func (s *Server) requireSigV4ServiceAny(w http.ResponseWriter, r *http.Request, services ...string) bool {
	if len(services) == 0 {
		return s.requireSigV4Service(w, r, "")
	}
	lastStatus := http.StatusForbidden
	lastCode := "SignatureDoesNotMatch"
	lastMsg := "signature mismatch"
	for _, service := range services {
		ok, status, code, msg, _ := s.validateSigV4WithService(r, service)
		if ok {
			return true
		}
		lastStatus = status
		lastCode = code
		lastMsg = msg
	}
	respondS3ControlErrorXML(w, lastStatus, lastCode, lastMsg)
	return false
}

func (s *Server) requireSigV4ServiceOutposts(w http.ResponseWriter, r *http.Request, service string) bool {
	ok, status, code, msg, _ := s.validateSigV4WithService(r, service)
	if !ok {
		respondS3OutpostsErrorJSON(w, status, code, msg)
		return false
	}
	return true
}

func (s *Server) requireSigV4ServiceTables(w http.ResponseWriter, r *http.Request, service string) bool {
	ok, status, code, msg, _ := s.validateSigV4WithService(r, service)
	if !ok {
		respondS3TablesErrorJSON(w, status, code, msg)
		return false
	}
	return true
}

func (s *Server) requireSigV4ServiceVectors(w http.ResponseWriter, r *http.Request, service string) bool {
	ok, status, code, msg, _ := s.validateSigV4WithService(r, service)
	if !ok {
		respondS3VectorsErrorJSON(w, status, code, msg)
		return false
	}
	accountID := strings.TrimSpace(r.Header.Get("x-amz-account-id"))
	if accountID != "" {
		if !isValidAccountID(accountID) {
			respondS3VectorsErrorJSON(w, http.StatusBadRequest, "InvalidRequest", "invalid x-amz-account-id")
			return false
		}
		if !isSignedHeader(r, "x-amz-account-id") {
			respondS3VectorsErrorJSON(w, http.StatusForbidden, "SignatureDoesNotMatch", "signed headers missing x-amz-account-id")
			return false
		}
	}
	return true
}

func (s *Server) requireSigV4ServiceRedshift(w http.ResponseWriter, r *http.Request, service string) bool {
	ok, status, code, msg, _ := s.validateSigV4WithService(r, service)
	if !ok {
		respondRedshiftErrorXML(w, status, code, msg)
		return false
	}
	return true
}

