func respondRedshiftErrorXML(w http.ResponseWriter, status int, code, message string) {
	errType := "Sender"
	if status >= 500 {
		errType = "Receiver"
	}
	body := redshiftErrorResponse{
		XMLNS: redshiftNamespace,
		Error: redshiftError{
			Type:    errType,
			Code:    code,
			Message: message,
		},
		RequestID: "stackyard-request",
	}
	payload, err := xml.Marshal(body)
	if err != nil {
		w.WriteHeader(http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/xml")
	w.WriteHeader(status)
	_, _ = w.Write(payload)
}

