func decodeS3TablesARN(pathValue, prefix string) (string, bool) {
	if !strings.HasPrefix(pathValue, prefix) {
		return "", false
	}
	remainder := strings.TrimPrefix(pathValue, prefix)
	if remainder == "" {
		return "", false
	}
	decoded, err := url.PathUnescape(remainder)
	if err != nil || strings.TrimSpace(decoded) == "" {
		return "", false
	}
	return decoded, true
}

func decodeS3TablesARNSuffix(pathValue, prefix, suffix string) (string, bool) {
	if !strings.HasPrefix(pathValue, prefix) || !strings.HasSuffix(pathValue, suffix) {
		return "", false
	}
	remainder := strings.TrimPrefix(pathValue, prefix)
	remainder = strings.TrimSuffix(remainder, suffix)
	if remainder == "" {
		return "", false
	}
	decoded, err := url.PathUnescape(remainder)
	if err != nil || strings.TrimSpace(decoded) == "" {
		return "", false
	}
	return decoded, true
}

func decodeS3TablesARNWithRest(pathValue, prefix string) (string, []string, bool) {
	if !strings.HasPrefix(pathValue, prefix) {
		return "", nil, false
	}
	remainder := strings.TrimPrefix(pathValue, prefix)
	if remainder == "" {
		return "", nil, false
	}
	parts := strings.Split(remainder, "/")
	if len(parts) == 0 {
		return "", nil, false
	}
	first, err := url.PathUnescape(parts[0])
	if err != nil || strings.TrimSpace(first) == "" {
		return "", nil, false
	}
	arn := strings.TrimSpace(first)
	consumed := 1

	// S3 Tables bucket ARNs include a slash in the resource component
	// (":bucket/<name>"). Requests may arrive encoded or decoded.
	if strings.HasSuffix(arn, ":bucket") {
		if len(parts) < 2 {
			return "", nil, false
		}
		bucketName, err := url.PathUnescape(parts[1])
		if err != nil || strings.TrimSpace(bucketName) == "" {
			return "", nil, false
		}
		arn = arn + "/" + strings.TrimSpace(bucketName)
		consumed = 2
	}
	if !strings.Contains(arn, ":bucket/") {
		return "", nil, false
	}
	rest := make([]string, 0, len(parts)-consumed)
	for _, segment := range parts[consumed:] {
		if strings.TrimSpace(segment) == "" {
			return "", nil, false
		}
		decoded, err := url.PathUnescape(segment)
		if err != nil || strings.TrimSpace(decoded) == "" {
			return "", nil, false
		}
		rest = append(rest, decoded)
	}
	return arn, rest, true
}

func isS3TablesTableARN(arn string) bool {
	arn = strings.TrimSpace(arn)
	if arn == "" {
		return false
	}
	return strings.Contains(arn, ":s3tables:") && strings.Contains(arn, ":bucket/") && strings.Contains(arn, "/table/")
}

func isS3TablesBucketARN(arn string) bool {
	arn = strings.TrimSpace(arn)
	if arn == "" || strings.Contains(arn, "/table/") || !strings.Contains(arn, ":s3tables:") {
		return false
	}
	idx := strings.Index(arn, ":bucket/")
	if idx < 0 {
		return false
	}
	bucketPart := strings.TrimSpace(arn[idx+len(":bucket/"):])
	return bucketPart != "" && !strings.Contains(bucketPart, "/")
}

func s3TablesBuildTableARN(bucketARN string, namespace []string, name string) string {
	bucketName := strings.TrimSpace(bucketARN)
	if idx := strings.Index(bucketName, ":bucket/"); idx >= 0 {
		bucketName = strings.TrimSpace(bucketName[idx+len(":bucket/"):])
	}
	if bucketName == "" {
		bucketName = "unknown-bucket"
	}
	ns := strings.Join(namespace, ".")
	return "arn:aws:s3tables:us-east-1:123456789012:bucket/" + bucketName + "/table/" + ns + "/" + name
}

