func isSignedHeader(r *http.Request, header string) bool {
	header = strings.ToLower(strings.TrimSpace(header))
	if header == "" {
		return false
	}
	auth := r.Header.Get("Authorization")
	req, err := parseSigV4Authorization(auth)
	if err != nil {
		req, err = parseSigV4Query(r.URL.Query())
		if err != nil {
			return false
		}
	}
	for _, signed := range strings.Split(req.SignedHeaders, ";") {
		if strings.TrimSpace(strings.ToLower(signed)) == header {
			return true
		}
	}
	return false
}

func (s *Server) validateSigV4(r *http.Request) (bool, int, string, string, bool) {
	return s.validateSigV4WithService(r, "")
}

func (s *Server) validateSigV4WithService(r *http.Request, requiredService string) (bool, int, string, string, bool) {
	if s != nil && s.awsAuthValidator != nil {
		return s.awsAuthValidator.ValidateWithService(r, requiredService)
	}
	return s.validateSigV4WithServiceCore(r, requiredService)
}

func (s *Server) validateSigV4WithServiceCore(r *http.Request, requiredService string) (bool, int, string, string, bool) {
	if skipSigV4Validation(r) {
		return true, 0, "", "", true
	}
	auth := r.Header.Get("Authorization")
	authPresent := strings.TrimSpace(auth) != "" || r.URL.Query().Get("X-Amz-Algorithm") != "" || r.URL.Query().Get("X-Amz-Credential") != ""
	req, err := parseSigV4Authorization(auth)
	if err != nil {
		req, err = parseSigV4Query(r.URL.Query())
		if err != nil {
			return false, http.StatusForbidden, "AccessDenied", err.Error(), authPresent
		}
	}

	if req.AccessKey != s.accessKey {
		return false, http.StatusForbidden, "InvalidAccessKeyId", "unknown access key", authPresent
	}

	amzDate := r.Header.Get("x-amz-date")
	if amzDate == "" {
		amzDate = req.AmzDate
	}
	if amzDate == "" {
		return false, http.StatusBadRequest, "InvalidRequest", "missing x-amz-date", authPresent
	}
	req.AmzDate = amzDate
	if len(amzDate) >= 8 && req.ScopeDate != "" && req.ScopeDate != amzDate[:8] {
		return false, http.StatusForbidden, "SignatureDoesNotMatch", "credential scope date mismatch", authPresent
	}
	if requiredService != "" && req.Service != requiredService {
		return false, http.StatusForbidden, "SignatureDoesNotMatch", "credential scope service mismatch", authPresent
	}
	if requiredService != "" && req.Region == "" {
		return false, http.StatusForbidden, "SignatureDoesNotMatch", "credential scope region mismatch", authPresent
	}
	if requiredService == "sqs" && req.Region != "" && req.Region != defaultSigV4Region {
		return false, http.StatusForbidden, "SignatureDoesNotMatch", "credential scope region mismatch", authPresent
	}
	if requiredService == "s3vectors" && req.Region != "" && req.Region != defaultSigV4Region {
		return false, http.StatusForbidden, "SignatureDoesNotMatch", "credential scope region mismatch", authPresent
	}
	if requiredService == "redshift" && req.Region != "" && req.Region != defaultSigV4Region {
		return false, http.StatusForbidden, "SignatureDoesNotMatch", "credential scope region mismatch", authPresent
	}

	bodyBytes, err := readBodyBytes(r)
	if err != nil {
		return false, http.StatusBadRequest, "InvalidRequest", "unable to read request body", authPresent
	}

	payloadHash := r.Header.Get("x-amz-content-sha256")
	if payloadHash == "" {
		if req.QueryAuth {
			payloadHash = "UNSIGNED-PAYLOAD"
		} else {
			payloadHash = sha256Hex(bodyBytes)
		}
	}

	if payloadHash != "UNSIGNED-PAYLOAD" && payloadHash != sha256Hex(bodyBytes) {
		return false, http.StatusForbidden, "SignatureDoesNotMatch", "payload hash mismatch", authPresent
	}

	if req.QueryAuth {
		if !validateSigV4Expiry(req.AmzDate, req.Expires) {
			return false, http.StatusForbidden, "AccessDenied", "request has expired", authPresent
		}
	}

	canonicalRequest, err := buildCanonicalRequest(r, req.SignedHeaders, payloadHash, req.QueryAuth)
	if err != nil {
		return false, http.StatusBadRequest, "InvalidRequest", err.Error(), authPresent
	}

	stringToSign := buildStringToSign(req.AmzDate, req.Region, req.Service, canonicalRequest)
	expectedSignature := signString(stringToSign, req.Region, req.Service, s.secretKey)

	if hmac.Equal([]byte(expectedSignature), []byte(req.Signature)) {
		return true, 0, "", "", authPresent
	}

	for _, candidateURI := range alternateCanonicalURIs(r.URL, rawRequestPath(r), buildCanonicalURI(r.URL)) {
		candidateRequest, err := buildCanonicalRequestForURI(r, candidateURI, req.SignedHeaders, payloadHash, req.QueryAuth)
		if err != nil {
			continue
		}
		candidateToSign := buildStringToSign(req.AmzDate, req.Region, req.Service, candidateRequest)
		candidateSignature := signString(candidateToSign, req.Region, req.Service, s.secretKey)
		if hmac.Equal([]byte(candidateSignature), []byte(req.Signature)) {
			return true, 0, "", "", authPresent
		}
	}

	return false, http.StatusForbidden, "SignatureDoesNotMatch", "signature mismatch", authPresent
}

func readBodyBytes(r *http.Request) ([]byte, error) {
	if r.Body == nil {
		return nil, nil
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, 25<<20))
	if err != nil {
		return nil, err
	}
	r.Body = io.NopCloser(bytes.NewReader(body))
	return body, nil
}

func parseSigV4Authorization(value string) (sigV4Request, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return sigV4Request{}, errors.New("missing Authorization header")
	}
	if !strings.HasPrefix(value, "AWS4-HMAC-SHA256 ") {
		return sigV4Request{}, errors.New("unsupported authorization scheme")
	}

	parts := strings.Split(strings.TrimPrefix(value, "AWS4-HMAC-SHA256 "), ",")
	fields := map[string]string{}
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		kv := strings.SplitN(part, "=", 2)
		if len(kv) != 2 {
			continue
		}
		fields[kv[0]] = strings.Trim(kv[1], " ")
	}

	credential, ok := fields["Credential"]
	if !ok {
		return sigV4Request{}, errors.New("missing Credential in authorization")
	}
	signedHeaders, ok := fields["SignedHeaders"]
	if !ok {
		return sigV4Request{}, errors.New("missing SignedHeaders in authorization")
	}
	signature, ok := fields["Signature"]
	if !ok {
		return sigV4Request{}, errors.New("missing Signature in authorization")
	}

	credParts := strings.Split(credential, "/")
	if len(credParts) != 5 {
		return sigV4Request{}, errors.New("invalid credential scope")
	}

	return sigV4Request{
		AccessKey:     credParts[0],
		ScopeDate:     credParts[1],
		Region:        credParts[2],
		Service:       credParts[3],
		SignedHeaders: signedHeaders,
		Signature:     signature,
	}, nil
}

func parseSigV4Query(values url.Values) (sigV4Request, error) {
	if values.Get("X-Amz-Algorithm") != "AWS4-HMAC-SHA256" {
		return sigV4Request{}, errors.New("missing or invalid X-Amz-Algorithm")
	}
	credential := values.Get("X-Amz-Credential")
	signature := values.Get("X-Amz-Signature")
	signedHeaders := values.Get("X-Amz-SignedHeaders")
	amzDate := values.Get("X-Amz-Date")
	expiresStr := values.Get("X-Amz-Expires")
	if credential == "" || signature == "" || signedHeaders == "" || amzDate == "" || expiresStr == "" {
		return sigV4Request{}, errors.New("missing presign query parameters")
	}
	expires, err := strconv.Atoi(expiresStr)
	if err != nil || expires < 0 {
		return sigV4Request{}, errors.New("invalid X-Amz-Expires")
	}
	credParts := strings.Split(credential, "/")
	if len(credParts) != 5 {
		return sigV4Request{}, errors.New("invalid credential scope")
	}
	return sigV4Request{
		AccessKey:     credParts[0],
		ScopeDate:     credParts[1],
		Region:        credParts[2],
		Service:       credParts[3],
		AmzDate:       amzDate,
		SignedHeaders: signedHeaders,
		Signature:     signature,
		QueryAuth:     true,
		Expires:       expires,
	}, nil
}

func buildCanonicalRequest(r *http.Request, signedHeaders, payloadHash string, excludeSignature bool) (string, error) {
	canonicalURI := buildCanonicalURI(r.URL)
	return buildCanonicalRequestForURI(r, canonicalURI, signedHeaders, payloadHash, excludeSignature)
}

func buildCanonicalRequestForURI(r *http.Request, canonicalURI, signedHeaders, payloadHash string, excludeSignature bool) (string, error) {
	if canonicalURI == "" {
		canonicalURI = "/"
	}
	if !strings.HasPrefix(canonicalURI, "/") {
		canonicalURI = "/" + canonicalURI
	}
	canonicalQuery := buildCanonicalQuery(r.URL, excludeSignature)
	canonicalHeaders, err := buildCanonicalHeaders(r, signedHeaders)
	if err != nil {
		return "", err
	}

	return strings.Join([]string{
		r.Method,
		canonicalURI,
		canonicalQuery,
		canonicalHeaders,
		signedHeaders,
		payloadHash,
	}, "\n"), nil
}

func alternateCanonicalURIs(u *url.URL, requestPath, primary string) []string {
	seen := map[string]struct{}{}
	add := func(v string) {
		if v == "" {
			v = "/"
		}
		if !strings.HasPrefix(v, "/") {
			v = "/" + v
		}
		if _, ok := seen[v]; ok {
			return
		}
		seen[v] = struct{}{}
	}
	add(primary)
	add(u.EscapedPath())
	add(u.Path)
	add(doubleEncodeCanonicalPath(requestPath))
	out := make([]string, 0, len(seen))
	for key := range seen {
		if key == primary {
			continue
		}
		out = append(out, key)
	}
	return out
}

func rawRequestPath(r *http.Request) string {
	path := strings.TrimSpace(r.RequestURI)
	if path == "" {
		return r.URL.EscapedPath()
	}
	if idx := strings.Index(path, "?"); idx >= 0 {
		path = path[:idx]
	}
	if path == "" {
		return "/"
	}
	if !strings.HasPrefix(path, "/") {
		path = "/" + path
	}
	return path
}

func doubleEncodeCanonicalPath(path string) string {
	if path == "" {
		return "/"
	}
	if !strings.HasPrefix(path, "/") {
		path = "/" + path
	}
	segments := strings.Split(path, "/")
	for i, segment := range segments {
		segments[i] = encodeRfc3986(segment)
	}
	return strings.Join(segments, "/")
}

func buildCanonicalURI(u *url.URL) string {
	path := u.EscapedPath()
	if path == "" {
		path = "/"
	}
	if !strings.HasPrefix(path, "/") {
		path = "/" + path
	}

	segments := strings.Split(path, "/")
	for i, segment := range segments {
		decoded, err := url.PathUnescape(segment)
		if err == nil {
			segment = decoded
		}
		segments[i] = encodeRfc3986(segment)
	}
	return strings.Join(segments, "/")
}

func buildCanonicalHeaders(r *http.Request, signedHeaders string) (string, error) {
	if signedHeaders == "" {
		return "", errors.New("missing signed headers")
	}

	keys := strings.Split(signedHeaders, ";")
	var b strings.Builder
	for _, key := range keys {
		key = strings.ToLower(strings.TrimSpace(key))
		if key == "" {
			continue
		}
		var value string
		if key == "host" {
			value = r.Host
		} else {
			values := r.Header.Values(key)
			if len(values) == 0 {
				if key == "content-length" && r.ContentLength >= 0 {
					value = strconv.FormatInt(r.ContentLength, 10)
					goto normalize
				}
				return "", errors.New("missing signed header: " + key)
			}
			value = strings.Join(values, ",")
		}
	normalize:
		value = normalizeHeaderValue(value)
		b.WriteString(key)
		b.WriteString(":")
		b.WriteString(value)
		b.WriteString("\n")
	}
	return b.String(), nil
}

func buildCanonicalQuery(u *url.URL, excludeSignature bool) string {
	query := u.Query()
	keys := make([]string, 0, len(query))
	for k := range query {
		if excludeSignature && strings.EqualFold(k, "X-Amz-Signature") {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var pairs []string
	for _, key := range keys {
		values := query[key]
		sort.Strings(values)
		for _, val := range values {
			pairs = append(pairs, encodeRfc3986(key)+"="+encodeRfc3986(val))
		}
	}
	return strings.Join(pairs, "&")
}

func encodeRfc3986(value string) string {
	return strings.ReplaceAll(url.QueryEscape(value), "+", "%20")
}

func normalizeHeaderValue(value string) string {
	value = strings.TrimSpace(value)
	fields := strings.Fields(value)
	return strings.Join(fields, " ")
}

func buildStringToSign(amzDate, region, service, canonicalRequest string) string {
	date := amzDate
	if len(amzDate) >= 8 {
		date = amzDate[:8]
	}
	scope := strings.Join([]string{date, region, service, "aws4_request"}, "/")
	hashedRequest := sha256Hex([]byte(canonicalRequest))
	return strings.Join([]string{
		"AWS4-HMAC-SHA256",
		amzDate,
		scope,
		hashedRequest,
	}, "\n")
}

func signString(stringToSign, region, service, secret string) string {
	date := ""
	lines := strings.Split(stringToSign, "\n")
	if len(lines) > 1 {
		date = lines[1][:8]
	}

	kDate := hmacSHA256([]byte("AWS4"+secret), []byte(date))
	kRegion := hmacSHA256(kDate, []byte(region))
	kService := hmacSHA256(kRegion, []byte(service))
	kSigning := hmacSHA256(kService, []byte("aws4_request"))
	signature := hmacSHA256(kSigning, []byte(stringToSign))
	return hex.EncodeToString(signature)
}

func sha256Hex(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func hmacSHA256(key, data []byte) []byte {
	mac := hmac.New(sha256.New, key)
	_, _ = mac.Write(data)
	return mac.Sum(nil)
}

func validateSigV4Expiry(amzDate string, expires int) bool {
	if expires == 0 {
		return true
	}
	t, err := time.Parse("20060102T150405Z", amzDate)
	if err != nil {
		return false
	}
	return time.Now().UTC().Before(t.Add(time.Duration(expires) * time.Second))
}

func parseCopySource(value string) (string, string) {
	value = strings.TrimSpace(value)
	value = strings.TrimPrefix(value, "/")
	if value == "" {
		return "", ""
	}
	if decoded, err := url.PathUnescape(value); err == nil {
		value = decoded
	}
	if bucket, key, ok := parseAccessPointArn(value); ok {
		return bucket, key
	}
	bucket, key, found := strings.Cut(value, "/")
	if !found || bucket == "" || key == "" {
		return "", ""
	}
	return bucket, key
}

func isValidAccountID(accountID string) bool {
	if len(accountID) != 12 {
		return false
	}
	for _, r := range accountID {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

func isValidAccessPointName(name string) bool {
	if len(name) < 3 || len(name) > 255 {
		return false
	}
	for i, r := range name {
		if r >= 'A' && r <= 'Z' {
			return false
		}
		if (r < 'a' || r > 'z') && (r < '0' || r > '9') && r != '-' {
			return false
		}
		if (i == 0 || i == len(name)-1) && r == '-' {
			return false
		}
	}
	return true
}

func accessPointArn(name, accountID string) string {
	return fmt.Sprintf("arn:aws:s3:%s:%s:accesspoint/%s", "us-east-1", accountID, name)
}

func accessGrantsInstanceArn(accountID, instanceID string) string {
	return fmt.Sprintf("arn:aws:s3:%s:%s:access-grants/%s", "us-east-1", accountID, instanceID)
}

func accessGrantsLocationArn(accountID, locationID string) string {
	return fmt.Sprintf("arn:aws:s3:%s:%s:access-grants/location/%s", "us-east-1", accountID, locationID)
}

func accessGrantArn(accountID, grantID string) string {
	return fmt.Sprintf("arn:aws:s3:%s:%s:access-grants/grant/%s", "us-east-1", accountID, grantID)
}

func outpostsBucketArn(accountID, outpostID, bucket string) string {
	return fmt.Sprintf("arn:aws:s3-outposts:%s:%s:outpost/%s/bucket/%s", "us-east-1", accountID, outpostID, bucket)
}

func accessPointAlias(name, accountID string) string {
	base := strings.ToLower(name) + "-" + accountID
	if len(base) <= 63 {
		return base
	}
	hash := sha256Hex([]byte(base))
	suffix := "-" + hash[:12]
	limit := 63 - len(suffix)
	if limit < 1 {
		return hash[:63]
	}
	return base[:limit] + suffix
}

func mrapAlias(name string) string {
	alias := strings.ToLower(name) + ".mrap"
	if len(alias) <= 63 {
		return alias
	}
	hash := sha256Hex([]byte(alias))
	suffix := "-" + hash[:12]
	limit := 63 - len(suffix)
	if limit < 1 {
		return hash[:63]
	}
	return alias[:limit] + suffix
}

func mrapArn(name, accountID string) string {
	return fmt.Sprintf("arn:aws:s3::%s:accesspoint/%s", accountID, mrapAlias(name))
}

func mrapNameFromValue(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return ""
	}
	if strings.HasPrefix(value, "arn:") {
		if idx := strings.LastIndex(value, "/"); idx != -1 && idx+1 < len(value) {
			return value[idx+1:]
		}
	}
	if strings.Contains(value, "/") {
		_, tail, _ := strings.Cut(value, "/")
		return tail
	}
	return value
}

func mrapOperationToken(accountID string) string {
	return fmt.Sprintf("arn:aws:s3::%s:async-request/mrap/stackyard", accountID)
}

func coalesce(value, fallback string) string {
	value = strings.TrimSpace(value)
	if value != "" {
		return value
	}
	return fallback
}

func applyCORS(w http.ResponseWriter, r *http.Request, svc *s3.Service, bucket string) {
	origin := r.Header.Get("Origin")
	if origin == "" {
		return
	}
	cfg, err := svc.GetBucketCORS(bucket)
	if err != nil || cfg == nil {
		return
	}
	method := r.Method
	reqHeaders := r.Header.Get("Access-Control-Request-Headers")
	for _, rule := range cfg.Rules {
		if !stringInSlice(origin, rule.AllowedOrigins) && !stringInSlice("*", rule.AllowedOrigins) {
			continue
		}
		if !stringInSlice(method, rule.AllowedMethods) {
			continue
		}
		if reqHeaders != "" && len(rule.AllowedHeaders) > 0 {
			reqHeaderList := splitHeaderList(reqHeaders)
			if !headersAllowed(reqHeaderList, rule.AllowedHeaders) {
				continue
			}
		}
		w.Header().Set("Access-Control-Allow-Origin", origin)
		w.Header().Set("Vary", "Origin")
		w.Header().Set("Access-Control-Allow-Methods", strings.Join(rule.AllowedMethods, ", "))
		if len(rule.AllowedHeaders) > 0 {
			w.Header().Set("Access-Control-Allow-Headers", strings.Join(rule.AllowedHeaders, ", "))
		} else if reqHeaders != "" {
			w.Header().Set("Access-Control-Allow-Headers", reqHeaders)
		}
		if len(rule.ExposeHeaders) > 0 {
			w.Header().Set("Access-Control-Expose-Headers", strings.Join(rule.ExposeHeaders, ", "))
		}
		if rule.MaxAgeSeconds > 0 {
			w.Header().Set("Access-Control-Max-Age", strconv.Itoa(rule.MaxAgeSeconds))
		}
		return
	}
}

func stringInSlice(value string, list []string) bool {
	for _, v := range list {
		if v == value {
			return true
		}
	}
	return false
}

func splitHeaderList(value string) []string {
	parts := strings.Split(value, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(strings.ToLower(p))
		if p != "" {
			out = append(out, p)
		}
	}
	return out
}

func headersAllowed(req []string, allowed []string) bool {
	if len(req) == 0 {
		return true
	}
	if stringInSlice("*", allowed) {
		return true
	}
	allowedSet := map[string]struct{}{}
	for _, h := range allowed {
		allowedSet[strings.ToLower(h)] = struct{}{}
	}
	for _, h := range req {
		if _, ok := allowedSet[h]; !ok {
			return false
		}
	}
	return true
}

func validateContentMD5(md5Header string, body []byte) bool {
	if md5Header == "" {
		return true
	}
	decoded, err := base64.StdEncoding.DecodeString(md5Header)
	if err != nil {
		return false
	}
	sum := md5.Sum(body)
	return hmac.Equal(decoded, sum[:])
}

func checkConditionalHeaders(r *http.Request, obj s3.Object) (bool, int) {
	if match := r.Header.Get("If-Match"); match != "" {
		if !etagMatch(match, obj.ETag) {
			return false, http.StatusPreconditionFailed
		}
	}
	if noneMatch := r.Header.Get("If-None-Match"); noneMatch != "" {
		if etagMatch(noneMatch, obj.ETag) {
			return false, http.StatusNotModified
		}
	}
	if since := r.Header.Get("If-Modified-Since"); since != "" {
		if t, err := http.ParseTime(since); err == nil {
			if !obj.UpdatedAt.After(t) {
				return false, http.StatusNotModified
			}
		}
	}
	if since := r.Header.Get("If-Unmodified-Since"); since != "" {
		if t, err := http.ParseTime(since); err == nil {
			if obj.UpdatedAt.After(t) {
				return false, http.StatusPreconditionFailed
			}
		}
	}
	return true, http.StatusOK
}

func etagMatch(headerValue, etag string) bool {
	etag = strings.Trim(etag, "\"")
	parts := strings.Split(headerValue, ",")
	for _, part := range parts {
		part = strings.TrimSpace(strings.Trim(part, "\""))
		if part == "*" || part == etag {
			return true
		}
	}
	return false
}

func checkPutPreconditions(r *http.Request, svc *s3.Service, bucket, key string) bool {
	ifMatch := r.Header.Get("If-Match")
	ifNoneMatch := r.Header.Get("If-None-Match")
	if ifMatch == "" && ifNoneMatch == "" {
		return true
	}
	obj, err := svc.GetObject(bucket, key)
	if err != nil {
		if ifNoneMatch == "*" {
			return false
		}
		return true
	}
	if ifMatch != "" && !etagMatch(ifMatch, obj.ETag) {
		return false
	}
	if ifNoneMatch != "" && etagMatch(ifNoneMatch, obj.ETag) {
		return false
	}
	return true
}

func checkCopyPreconditions(r *http.Request, svc *s3.Service, bucket, key string) bool {
	obj, err := svc.GetObject(bucket, key)
	if err != nil {
		return false
	}
	match := r.Header.Get("x-amz-copy-source-if-match")
	if match != "" && !etagMatch(match, obj.ETag) {
		return false
	}
	noneMatch := r.Header.Get("x-amz-copy-source-if-none-match")
	if noneMatch != "" && etagMatch(noneMatch, obj.ETag) {
		return false
	}
	modSince := r.Header.Get("x-amz-copy-source-if-modified-since")
	if modSince != "" {
		if t, err := http.ParseTime(modSince); err == nil {
			if !obj.UpdatedAt.After(t) {
				return false
			}
		}
	}
	unmodSince := r.Header.Get("x-amz-copy-source-if-unmodified-since")
	if unmodSince != "" {
		if t, err := http.ParseTime(unmodSince); err == nil {
			if obj.UpdatedAt.After(t) {
				return false
			}
		}
	}
	return true
}

func checkRenamePreconditions(r *http.Request, svc *s3.Service, bucket, key string) bool {
	obj, err := svc.GetObject(bucket, key)
	if err != nil {
		return false
	}
	match := r.Header.Get("x-amz-rename-source-if-match")
	if match != "" && !etagMatch(match, obj.ETag) {
		return false
	}
	noneMatch := r.Header.Get("x-amz-rename-source-if-none-match")
	if noneMatch != "" && etagMatch(noneMatch, obj.ETag) {
		return false
	}
	modSince := r.Header.Get("x-amz-rename-source-if-modified-since")
	if modSince != "" {
		if t, err := http.ParseTime(modSince); err == nil {
			if !obj.UpdatedAt.After(t) {
				return false
			}
		}
	}
	unmodSince := r.Header.Get("x-amz-rename-source-if-unmodified-since")
	if unmodSince != "" {
		if t, err := http.ParseTime(unmodSince); err == nil {
			if obj.UpdatedAt.After(t) {
				return false
			}
		}
	}
	return true
}

