func validateS3ControlOrderSubset(observed []string, expected []string) bool {
	if len(observed) == 0 {
		return true
	}
	expectedIndex := make(map[string]int, len(expected))
	for i, name := range expected {
		expectedIndex[name] = i
	}
	last := -1
	for _, name := range observed {
		idx, ok := expectedIndex[name]
		if !ok {
			return false
		}
		if idx < last {
			return false
		}
		last = idx
	}
	return true
}

func validateBoolText(value string) bool {
	val := strings.TrimSpace(strings.ToLower(value))
	return val == "true" || val == "false"
}

func validatePositiveInt(value string) bool {
	val := strings.TrimSpace(value)
	if val == "" {
		return false
	}
	num, err := strconv.Atoi(val)
	return err == nil && num > 0
}

func extractXMLPathValue(body []byte, path string) string {
	decoder := xml.NewDecoder(bytes.NewReader(body))
	stack := make([]string, 0)
	rootSeen := false
	var value strings.Builder
	for {
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return ""
		}
		switch t := token.(type) {
		case xml.StartElement:
			if !rootSeen {
				rootSeen = true
				continue
			}
			stack = append(stack, t.Name.Local)
		case xml.EndElement:
			if rootSeen && len(stack) == 0 {
				rootSeen = false
				continue
			}
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
		case xml.CharData:
			if len(stack) == 0 {
				continue
			}
			if strings.Join(stack, "/") == path {
				value.Write(t)
			}
		}
	}
	return strings.TrimSpace(value.String())
}

func validateFilterSpec(filter *s3FilterSpec) error {
	if filter == nil {
		return nil
	}
	hasPrefix := strings.TrimSpace(filter.Prefix) != ""
	hasTag := filter.Tag != nil
	hasAnd := filter.And != nil
	count := 0
	if hasPrefix {
		count++
	}
	if hasTag {
		count++
	}
	if hasAnd {
		count++
	}
	if count == 0 {
		return fmt.Errorf("invalid filter")
	}
	if count > 1 {
		return fmt.Errorf("invalid filter")
	}
	if hasTag {
		if strings.TrimSpace(filter.Tag.Key) == "" || strings.TrimSpace(filter.Tag.Value) == "" {
			return fmt.Errorf("invalid filter tag")
		}
	}
	if hasAnd {
		hasAny := strings.TrimSpace(filter.And.Prefix) != "" || len(filter.And.Tags) > 0
		if !hasAny {
			return fmt.Errorf("invalid filter")
		}
		for _, tag := range filter.And.Tags {
			if strings.TrimSpace(tag.Key) == "" || strings.TrimSpace(tag.Value) == "" {
				return fmt.Errorf("invalid filter tag")
			}
		}
	}
	return nil
}

func validateInventoryFilter(filter *s3InventoryFilter) error {
	if filter == nil {
		return nil
	}
	if strings.TrimSpace(filter.Prefix) == "" {
		return fmt.Errorf("invalid filter")
	}
	return nil
}

func validateInventoryDestination(body []byte) error {
	type dest struct {
		Bucket string `xml:"Destination>S3BucketDestination>Bucket"`
		Format string `xml:"Destination>S3BucketDestination>Format"`
		Prefix string `xml:"Destination>S3BucketDestination>Prefix"`
	}
	var cfg dest
	if err := xml.Unmarshal(body, &cfg); err != nil {
		return fmt.Errorf("invalid destination")
	}
	bucket := strings.TrimSpace(cfg.Bucket)
	if bucket == "" {
		return fmt.Errorf("missing destination bucket")
	}
	if strings.HasPrefix(bucket, "arn:") {
		if !strings.Contains(bucket, "arn:aws:s3:::") {
			return fmt.Errorf("invalid destination bucket")
		}
	}
	format := strings.ToUpper(strings.TrimSpace(cfg.Format))
	if format == "" {
		return fmt.Errorf("missing destination format")
	}
	switch format {
	case "CSV", "ORC", "PARQUET":
	default:
		return fmt.Errorf("invalid destination format")
	}
	_ = cfg.Prefix
	return nil
}

func parseAnalyticsConfig(payload string) (s3AnalyticsConfigDoc, error) {
	var cfg s3AnalyticsConfigDoc
	if err := xml.Unmarshal([]byte(payload), &cfg); err != nil {
		return s3AnalyticsConfigDoc{}, err
	}
	return cfg, nil
}

func renderAnalyticsConfig(payload string) (string, error) {
	cfg, err := parseAnalyticsConfig(payload)
	if err != nil {
		return "", err
	}
	cfg.Xmlns = "http://s3.amazonaws.com/doc/2006-03-01/"
	out, err := xml.Marshal(cfg)
	if err != nil {
		return "", err
	}
	return string(out), nil
}

