func (s *Server) emitS3Notification(bucket, key, eventName string, obj *s3.Object) {
	cfg, err := s.s3.GetBucketNotifications(bucket)
	if err != nil || cfg == nil || len(cfg.QueueConfigurations) == 0 {
		return
	}
	for _, queueCfg := range cfg.QueueConfigurations {
		if !notificationEventMatches(eventName, queueCfg.Events) {
			continue
		}
		if !notificationKeyMatches(queueCfg.Prefix, queueCfg.Suffix, key) {
			continue
		}
		queueName := parseNotificationQueueName(queueCfg.Queue)
		if queueName == "" {
			continue
		}
		record := buildS3EventRecord(bucket, key, eventName, queueCfg.ID, obj)
		payload, err := json.Marshal(s3EventEnvelope{Records: []s3EventRecord{record}})
		if err != nil {
			continue
		}
		if _, err := s.sqs.SendMessage(queueName, string(payload), nil, nil); err != nil {
			if s.logLevel == "debug" || s.logLevel == "verbose" {
				log.Printf("notification delivery failed: %v", err)
			}
		}
	}
}

func buildS3EventRecord(bucket, key, eventName, configID string, obj *s3.Object) s3EventRecord {
	eventObj := s3EventObject{Key: key}
	if obj != nil {
		if obj.SizeBytes > 0 {
			eventObj.Size = obj.SizeBytes
		}
		if obj.ETag != "" {
			eventObj.ETag = obj.ETag
		}
		if obj.VersionID != "" {
			eventObj.VersionID = obj.VersionID
		}
	}
	return s3EventRecord{
		EventVersion: "2.1",
		EventSource:  "aws:s3",
		AwsRegion:    "us-east-1",
		EventTime:    time.Now().UTC().Format(time.RFC3339),
		EventName:    normalizeNotificationEvent(eventName),
		UserIdentity: s3EventUserIdentity{PrincipalID: "stackyard"},
		S3: s3EventS3Entity{
			S3SchemaVersion: "1.0",
			ConfigurationID: configID,
			Bucket: s3EventBucket{
				Name: bucket,
				Arn:  "arn:aws:s3:::" + bucket,
			},
			Object: eventObj,
		},
	}
}

type statusWriter struct {
	http.ResponseWriter
	status int
	bytes  int
}

func (w *statusWriter) WriteHeader(statusCode int) {
	w.status = statusCode
	w.ResponseWriter.WriteHeader(statusCode)
}

func (w *statusWriter) Write(p []byte) (int, error) {
	n, err := w.ResponseWriter.Write(p)
	w.bytes += n
	return n, err
}
